'use client';

import { useState, useEffect, useRef } from 'react';
import Link from 'next/link';
import Image from 'next/image';
import {
  ArrowRight,
  Leaf,
  Pill,
  Sprout,
  Stethoscope,
  Sparkles,
  Wind,
  Milk,
  Bath,
  Heart,
  ArrowRightCircle,
  TrendingUp,
  Award,
  Zap,
  Plus
} from 'lucide-react';
import HeroCarousel, { HeroSlide, HeroSettings } from '@/components/HeroCarousel';
import { Product } from '@/types';
import { getBestSellers, getNewArrivals, getCategories, getFilteredProducts } from '@/lib/api';
import ProductCard from '@/components/ProductCard';
import ProductReel from '@/components/ProductReel';
import BestSellerShowcase from '@/components/BestSellerShowcase';
import { trackEcommerce, EcommerceItem } from '@/lib/analytics/gtag';
import { SkeletonProductGrid } from '@/components/Skeleton';
import { AnimateOnScroll } from '@/hooks/useScrollAnimation';
import { motion, AnimatePresence } from 'framer-motion';
import { useRouter, useParams } from 'next/navigation';
import NeedHelpSection from '@/components/NeedHelpSection';
import BrandReel from '@/components/BrandReel';
import { buildPath, getCountryFromPathname } from '@/lib/currency';

export interface HomeClientProps {
  initialBestSellers?: Product[];
  initialNewArrivals?: Product[];
  initialCategories?: Record<string, unknown>[];
  initialHeroSlides?: HeroSlide[];
  initialHeroSettings?: HeroSettings;
}

export default function HomeClientPage({
  initialBestSellers = [],
  initialNewArrivals = [],
  initialCategories = [],
  initialHeroSlides = [],
  initialHeroSettings = undefined,
}: HomeClientProps) {
  const router = useRouter();
  const params = useParams();
  const country = params?.country as string || 'us';

  const [bestSellers, setBestSellers] = useState<Product[]>(initialBestSellers);
  const [newArrivals, setNewArrivals] = useState<Product[]>(initialNewArrivals);
  const [faceWash, setFaceWash] = useState<Product[]>([]);
  const [hairOils, setHairOils] = useState<Product[]>([]);
  const [allCategories, setAllCategories] = useState<Record<string, unknown>[]>(initialCategories);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    // If we didn't get initial data, fetch it
    if (bestSellers.length > 0) return;

    setLoading(true);
    async function loadData() {
      try {
        const [bestRes, newRes, catRes] = await Promise.all([
          getBestSellers({ limit: 10 }),
          getNewArrivals({ limit: 10 }),
          getCategories(true)
        ]);
        setBestSellers(bestRes.data);
        setNewArrivals(newRes.data);
        setAllCategories(catRes);
      } catch (err) {
        console.error('Failed to load shop data', err);
      } finally {
        setLoading(false);
      }
    }
    loadData();
  }, []);

  // Fetch Additional Reels independently (not gated by SSR data)
  useEffect(() => {
    // Face Wash
    getFilteredProducts({ category: 'cosmetics', sub_category: 'face-care', limit: 10 })
      .then(res => setFaceWash(res.data as Record<string, unknown>[]))
      .catch(() => {});
    
    // Hair Oils
    getFilteredProducts({ category: 'cosmetics', sub_category: 'hair-care', limit: 10 })
      .then(res => setHairOils(res.data as Record<string, unknown>[]))
      .catch(() => {});
  }, []);

  const viewListHashRef = useRef<string>('');
  useEffect(() => {
    const allItems = [...bestSellers, ...newArrivals].slice(0, 15);
    if (allItems.length === 0) return;

    const currentHash = allItems.map(p => p.product_id).join(',');
    if (viewListHashRef.current === currentHash) return;

    viewListHashRef.current = currentHash;
    const gaItems: EcommerceItem[] = allItems.map((item, index) => ({
      item_id: item.product_id,
      item_name: item.product_name,
      price: Number(item.price ?? 0),
      quantity: 1,
      index: index + 1,
      item_list_name: 'Shop Discovery Highlights',
      item_category: item.category,
      item_brand: item.brand
    }));

    trackEcommerce('view_item_list', {
      currency: 'INR',
      value: gaItems.reduce((acc, curr) => acc + curr.price, 0),
      items: gaItems
    });
  }, [bestSellers, newArrivals]);

  // Map of category slugs to colors for consistent aesthetic
  const categoryColors: Record<string, string> = {
    'herbal-supplement': 'bg-[#F5F2E8]',
    'Ayurvedic-Herbs': 'bg-[#F5F2E8]',
    'dry-fruits--snacks': 'bg-[#F5F2E8]',
    'health-condition': 'bg-[#F5F2E8]',
    'skin-care': 'bg-[#F5F2E8]',
    'hair-care': 'bg-[#F5F2E8]',
    'Natural-Foods': 'bg-[#F5F2E8]',
    'Personal-Care': 'bg-[#F5F2E8]',
    'spices-and-masala': 'bg-[#F5F2E8]',
    'teas-and-superfoods': 'bg-[#F5F2E8]',
    'natural-beauty': 'bg-[#F5F2E8]',
    'gifts--combos': 'bg-[#F5F2E8]',
    'herbal-wellness': 'bg-[#F5F2E8]',
    'indian-fruits': 'bg-[#F5F2E8]'
  };

  // Map of category slugs to specific image paths to avoid full sprite sheets
  const categoryImages: Record<string, string> = {
    'herbal-supplement': '/icons/shop/herbal-supplement.png',
    'ayurvedic-herbs': '/icons/shop/ayurvedic-herbs.png',
    'health-condition': '/icons/shop/health-condition.png',
    'skin-care': '/icons/shop/skin-care.png',
    'hair-care': '/icons/shop/hair-care.png',
    'natural-foods': '/icons/shop/natural-foods.png',
    'personal-care': '/icons/shop/personal-care.png',

    // Exact matching for DB slugs
    'dry-fruits--snacks': '/icons/shop/dry-fruits-snacks.png',
    'gifts--combos': '/icons/shop/gifts-and-combos.png',
    'herbal-wellness': '/icons/shop/ayurvedic-herbs.png',
    'spices-and-masala': '/icons/shop/spices-masalas.png',
    'indian-fruits': '/icons/shop/indian-foods.png',
    'teas-and-superfoods': '/icons/shop/teas-and-superfoods.png',
    'natural-beauty': '/icons/shop/natural-beauty.png'
  };

  return (
    <div className="bg-white min-h-screen relative overflow-hidden">
      <h1 className="sr-only">Vedashi ÔÇö Premium Wellness & Natural Products</h1>
      {/* 1. BANNER REEL */}
      <div className="relative z-10 max-w-[1600px] mx-auto px-0 sm:px-6 lg:px-8 pt-0 sm:pt-8">
        <HeroCarousel initialSlides={initialHeroSlides} initialSettings={initialHeroSettings} />
      </div>

      <div className="relative z-10 pt-0 pb-0">

        {/* 2 & 3 COMBINED TO REMOVE GAP */}
        <div className="flex flex-col">
          {/* 2. SHOP BY CATEGORY - FULL WIDTH GRID */}
          <section className="relative pt-4 sm:pt-8 pb-0 overflow-hidden bg-white">
            <div
              className="absolute inset-0 opacity-[0.07] pointer-events-none"
            // style={{
            //   backgroundImage: 'url(/backgrounds/bg3.png)',
            //   backgroundSize: '1200px',
            //   backgroundPosition: 'center',
            //   backgroundRepeat: 'repeat'
            // }} 
            />

            <div className="relative z-10 max-w-[1500px] mx-auto px-4 sm:px-6 lg:px-8">
              <div className="relative text-center mb-2 px-4">
                <div className="absolute right-6 top-3 hidden lg:block">
                  <Link
                    href={buildPath(country, `/products`)}
                    className="group flex items-center gap-2 text-[13px] font-medium text-[#FF0000] hover:text-[#CC0000] transition-all underline decoration-[#FF0000]/30 underline-offset-2 hover:decoration-[#FF0000]"
                  >
                    Explore all products
                    <ArrowRight className="h-4 w-4 transition-transform group-hover:translate-x-1" />
                  </Link>
                </div>

                <AnimatePresence mode="wait">
                  <motion.div
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -10 }}
                    transition={{ duration: 0.3 }}
                  >
                    <h2 className="text-2xl sm:text-4xl font-bold text-gray-900 tracking-tight mb-4">
                      Categories
                    </h2>
                    <p className="hidden sm:block text-gray-500 font-medium italic mb-4 max-w-xl mx-auto">
                      Explore our curated collections of traditional wisdom for modern living
                    </p>
                  </motion.div>
                </AnimatePresence>
              </div>

              <div className="relative min-h-[220px]">
                <AnimatePresence mode="wait">
                  <motion.div
                    initial={{ opacity: 0, x: 20 }}
                    animate={{ opacity: 1, x: 0 }}
                    exit={{ opacity: 0, x: -20 }}
                    transition={{ duration: 0.4, ease: "easeOut" }}
                    className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-7 gap-3 sm:gap-4 lg:gap-5"
                  >
                    {allCategories.slice(0, 8).map((cat: Record<string, unknown>, i: number) => {
                      return (
                        <div
                          key={cat.category_id}
                          onClick={() => {
                            router.push(buildPath(country, `/products?category=${cat.slug}`));
                          }}
                          className="group flex flex-col items-center gap-3 transition-all duration-500 hover:-translate-y-2 cursor-pointer"
                        >
                          <div className={`relative w-[85%] sm:w-full mx-auto aspect-[4/3] rounded-xl sm:rounded-2xl ${categoryColors[cat.slug] || 'bg-[#F2F4F2]'} flex items-center justify-center shadow-sm group-hover:shadow-[0_20px_50px_rgba(59,93,59,0.12)] group-hover:bg-[#E2F0E2] transition-all duration-700 overflow-hidden isolate`}>
                            <Image
                              src={cat.image_url || categoryImages[cat.slug?.toLowerCase() || ''] || `/icons/shop/${cat.slug}.png`}
                              alt={cat.name}
                              fill
                              sizes="(max-width: 640px) 50vw, (max-width: 1024px) 25vw, 15vw"
                              onError={(e) => {
                                (e.target as HTMLImageElement).src = '/icons/shop/category-sprite.png';
                                (e.target as HTMLImageElement).srcset = '';
                              }}
                              className="object-cover relative z-10 opacity-90 group-hover:opacity-100 transition-all duration-[800ms] cubic-bezier(0.34,1.56,0.64,1) group-hover:scale-110 pointer-events-none"
                            />

                            {/* Hover Pulse Effect */}
                            <div className="absolute inset-0 rounded-xl sm:rounded-2xl border border-[#3B5D3B]/20 scale-100 opacity-0 group-hover:scale-105 group-hover:opacity-100 transition-all duration-700 pointer-events-none" />
                          </div>

                          <div className="text-center px-1">
                            <span className="text-[12px] sm:text-base font-bold text-gray-800 group-hover:text-[#3B5D3B] transition-colors leading-tight block line-clamp-2 min-h-[1.5em]">
                              {cat.name}
                            </span>
                          </div>
                        </div>
                      );
                    })}
                  </motion.div>
                </AnimatePresence>
              </div>

              {/* Mobile View All - Shop all products */}
              <div className="sm:hidden flex justify-end mt-4">
                <Link
                  href={buildPath(country, `/products`)}
                  className="text-[10px] font-medium text-[#FF0000] hover:text-[#CC0000] transition-colors underline decoration-[#FF0000]/30 underline-offset-2"
                >
                  Explore all products
                </Link>
              </div>
            </div>
          </section>

          <section className="relative pt-0 pb-0 overflow-hidden bg-white content-lazy">
            <div className="max-w-[1500px] mx-auto relative z-10">
              <BestSellerShowcase
                products={bestSellers}
                loading={loading}
                title="Best Sellers"
                subtitle="Our most-loved natural wellness essentials, chosen by you."
                viewAllLink={buildPath(country, `/products?bestSeller=true`)}
                viewAllText="Shop all Best Sellers"
              />
            </div>
          </section>


        </div>

        {/* 3.5 BRAND REEL */}
        <div className="w-full content-lazy">
          <BrandReel />
        </div>

        {/* 3.6 NEED HELP CHOOSING */}
        <div className="w-full content-lazy">
          <NeedHelpSection />
        </div>

        {/* 5. NEW ARRIVALS - CLEAN & RADIANT */}
        <section className="relative py-0 overflow-hidden bg-white content-lazy">


          <div className="max-w-[1500px] mx-auto relative z-10">
            <ProductReel
              products={newArrivals}
              loading={loading}
              title="New Arrivals"
              subtitle="Discover the newest additions to our natural wellness collection."
              viewAllLink="/products?newArrival=true"
              viewAllText="Shop New Arrivals"
            />
          </div>
        </section>

        {/* 6. FACE WASH REEL */}
        <section className="relative py-0 overflow-hidden bg-white content-lazy">
          <div className="max-w-[1500px] mx-auto relative z-10">
            <ProductReel
              products={faceWash}
              loading={loading}
              title="Face Wash"
              subtitle="Gentle cleansers for a fresh, radiant complexion every day."
              viewAllLink={buildPath(country, `/products?category=cosmetics&sub_category=face-care&sub_sub_category=cleansers-and-face-wash`)}
              viewAllText="Shop All Face Wash"
            />
          </div>
        </section>
        {/* 7. HAIR OILS REEL */}
        <section className="relative py-0 overflow-hidden bg-white content-lazy">
          <div className="max-w-[1500px] mx-auto relative z-10">
            <ProductReel
              products={hairOils}
              loading={loading}
              title="Hair oils"
              subtitle="Nourishing oils for stronger, shinier, and healthier hair."
              viewAllLink={buildPath(country, `/products?category=cosmetics&sub_category=hair-care&sub_sub_category=shampoos-and-conditioners`)}
              viewAllText="Shop All Hair Care"
            />
          </div>
        </section>
      </div>


    </div>
  );
}

'use client';

import { createPortal } from 'react-dom';

import { useRouter, useParams, useSearchParams } from 'next/navigation';
import { useAuth } from '@/context/AuthContext';
import { useWishlist } from '@/context/WishlistContext';
import { useCart } from '@/context/CartContext';
import ProductCard from '@/components/ProductCard';
import {
    getMyOrders, getAddresses, addAddress as apiAddAddress,
    updateAddress as apiUpdateAddress, deleteAddress as apiDeleteAddress,
    getCustomerProfile, updateCustomerProfile, deactivateAccount,
    uploadProfileImage, getProfileImage, removeProfileImage, getOrderById,
    cancelOrder as apiCancelOrder, downloadInvoice,
    getMyEnquiries, replyToEnquiry, changePassword,
    requestEmailChange, verifyEmailChangeProfile,
    requestPhoneChange, verifyPhoneChangeProfile,
    getLoyaltyWallet, getMyNotifications, getUnreadNotificationCount,
    markNotificationAsRead, markAllNotificationsAsRead, deleteNotification,
    lookupPostalCode, getMySupportTickets, replySupportTicket,
    getMyReviews, trackOrder
} from '@/lib/api';
import { trackRefund, EcommerceItem } from '@/lib/analytics/gtag';
import { Order, Address } from '@/types';
import { COUNTRIES } from '@/lib/countries';
import { formatLocal } from '@/lib/currency';
import Select from 'react-select';
import {
    Package, MapPin, Heart, User, Plus, Pencil, Trash2,
    Loader2, ShieldOff, Camera, X, Check, Star, Phone, Calendar, Mail,
    CheckCircle2, AlertCircle, Shield, FileText, MessageSquare, Send, Clock, User2, MessageCircle, Sparkles,
    ChevronRight,
    BadgeCheck, BellRing, Download, Search, ShoppingCart, LayoutGrid, List, Wallet, Eye, EyeOff
} from 'lucide-react';
import { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import toast from 'react-hot-toast';
import PrivacyDashboard from '@/components/account/PrivacyDashboard';
import ReviewForm from '@/components/reviews/ReviewForm';
import NotificationPreferences from '@/components/account/NotificationPreferences';
import ExportOrdersModal from '@/components/account/ExportOrdersModal';
import MyWallet from '@/components/account/MyWallet';
import ConfirmModal from '@/components/ui/ConfirmModal';
import { COUNTRY_CODES } from '@/lib/country-codes';
import { getAddressConfig, getDefaultCountry } from '@/lib/addressConfig';
import { useCurrency } from '@/context/CurrencyContext';

type Tab = 'overview' | 'orders' | 'wishlist' | 'addresses' | 'profile' | 'privacy' | 'support' | 'wallet' | 'notifications';

const VALID_TABS: Tab[] = ['overview', 'orders', 'wishlist', 'addresses', 'profile', 'privacy', 'support', 'wallet', 'notifications'];

export default function AccountPage() {
    const { formatPrice, format } = useCurrency();
    const router = useRouter();
    const params = useParams<{ country: string, tab?: string[] }>();
    const searchParams = useSearchParams();
    const urlOrderId = searchParams.get('orderId');
    const country = params?.country || 'in';
    const { user, isAuthenticated, isLoading, logout, updateUser } = useAuth();
    const { items: wishlistItems, removeItem: removeWishlistItem, loading: wishlistLoading } = useWishlist();
    const { addItem: addCartItem, items: cartItems, getItemInCart, loading: cartLoading } = useCart();

    // Wishlist state

    const [currentPage, setCurrentPage] = useState(1);
    const pageSize = 10;

    const [confirmingIndividualRemove, setConfirmingIndividualRemove] = useState<string | null>(null);

    // Derive active tab from URL path segment, default to 'overview'
    const activeTab: Tab = useMemo(() => {
        const slug = params?.tab?.[0] as Tab | undefined;
        return slug && VALID_TABS.includes(slug) ? slug : 'overview';
    }, [params?.tab]);



    // Orders state
    const [orders, setOrders] = useState<Order[]>([]);
    const [ordersLoading, setOrdersLoading] = useState(false);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [selectedOrderDetails, setSelectedOrderDetails] = useState<any | null>(null);
    const [isOrderLoading, setIsOrderLoading] = useState(false);
    const [isTrackOrderModalOpen, setIsTrackOrderModalOpen] = useState(false);
    const [trackOrderId, setTrackOrderId] = useState<string | null>(null);
    const [trackingData, setTrackingData] = useState<any | null>(null);
    const [isTrackingLoading, setIsTrackingLoading] = useState(false);
    const [trackOrderStatus, setTrackOrderStatus] = useState<string | null>(null);
    const [isDownloadingInvoice, setIsDownloadingInvoice] = useState(false);
    const [buyAgainLoading, setBuyAgainLoading] = useState(false);
    const [reorderingOrderId, setReorderingOrderId] = useState<string | null>(null);

    // Orders Filtering State
    const [orderSearch, setOrderSearch] = useState('');
    const [orderStatusFilter, setOrderStatusFilter] = useState('All');
    const [orderSort, setOrderSort] = useState('newest');

    // Addresses state
    const defaultCountryCode = getDefaultCountry();
    const defaultCountryName = COUNTRIES.find(c => c.code === defaultCountryCode)?.name || '';

    const formatAddressPhone = (phone: string) => {
        if (!phone) return '';
        // Find the matching dial code from our master list
        // Sort by length descending to ensure we match the most specific code (e.g., +91 over +9)
        const sortedCodes = [...COUNTRY_CODES].sort((a, b) => b.dial_code.length - a.dial_code.length);
        const match = sortedCodes.find(c => phone.startsWith(c.dial_code));

        if (match) {
            const dialCode = match.dial_code;
            const rest = phone.slice(dialCode.length);
            return `${dialCode} ${rest}`;
        }

        // Fallback for unexpected formats
        return phone.startsWith('+') ? phone.replace(/^(\+\d{1,3})/, '$1 ') : phone;
    };

    const [addresses, setAddresses] = useState<Address[]>([]);
    const [addressesLoading, setAddressesLoading] = useState(false);
    const [phoneError, setPhoneError] = useState<string | null>(null);
    const [showAddressForm, setShowAddressForm] = useState(false);
    const [editingAddress, setEditingAddress] = useState<Address | null>(null);
    const [addressForm, setAddressForm] = useState({
        address_line1: '', address_line2: '', city: '', state: '', pincode: '',
        country: defaultCountryName, country_code: defaultCountryCode, phone: '', label: '', is_default: false, full_name: '',
    });

    const addressConfig = getAddressConfig(addressForm.country_code || 'IN');
    const addressDialCode = useMemo(() => {
        const match = Array.isArray(COUNTRY_CODES) ? COUNTRY_CODES.find(c => c.code === addressForm.country_code) : null;
        const fallbackMatch = COUNTRY_CODES.find(c => c.code === defaultCountryCode);
        return match ? match.dial_code : (fallbackMatch?.dial_code || '+1');
    }, [addressForm.country_code, defaultCountryCode]);

    const [isLookupLoading, setIsLookupLoading] = useState(false);
    const [manualEdits, setManualEdits] = useState({
        city: false,
        state: false
    });

    const countryOptions = COUNTRIES.map(c => ({
        value: c.code,
        label: `${c.flag} ${c.name}`,
        name: c.name
    }));

    const customSelectStyles = {
        control: (provided: Record<string, unknown>, state: Record<string, unknown>) => ({
            ...provided,
            borderRadius: '12px',
            borderColor: state.isFocused ? '#91c934' : '#e5e7eb',
            boxShadow: 'none',
            '&:hover': {
                borderColor: '#91c934',
            },
            backgroundColor: 'white',
            paddingLeft: '34px',
            minHeight: '44px',
            fontSize: '14px',
        }),
        option: (provided: Record<string, unknown>, state: Record<string, unknown>) => ({
            ...provided,
            backgroundColor: state.isSelected ? '#91c934' : state.isFocused ? '#f3f4f6' : 'white',
            color: state.isSelected ? 'white' : '#111827',
            '&:active': {
                backgroundColor: '#91c934',
            },
            fontSize: '14px',
        }),
        menuList: (provided: Record<string, unknown>) => ({
            ...provided,
            "::-webkit-scrollbar": {
                width: "6px"
            },
            "::-webkit-scrollbar-track": {
                background: "transparent"
            },
            "::-webkit-scrollbar-thumb": {
                background: "#d1d5db",
                borderRadius: "3px"
            },
            "::-webkit-scrollbar-thumb:hover": {
                background: "#91c934"
            }
        }),
    };

    // Global Postal Code Auto-Fill
    useEffect(() => {
        if (addressForm.pincode.length >= 4 && showAddressForm) {
            const timer = setTimeout(async () => {
                setIsLookupLoading(true);
                const res = await lookupPostalCode(addressForm.pincode, addressForm.country_code);
                if (res.success && res.city && res.state) {
                    setAddressForm(prev => ({
                        ...prev,
                        city: manualEdits.city ? prev.city : (res.city || prev.city),
                        state: manualEdits.state ? prev.state : (res.state || prev.state),
                        country: res.country || prev.country
                    }));
                }
                setIsLookupLoading(false);
            }, 300);
            return () => clearTimeout(timer);
        }
    }, [addressForm.pincode, addressForm.country_code, showAddressForm, manualEdits.city, manualEdits.state]);

    // Profile state
    const [orderCount, setOrderCount] = useState(0);
    const [profileEditing, setProfileEditing] = useState(false);
    const [profileSaving, setProfileSaving] = useState(false);
    const [showNotificationModal, setShowNotificationModal] = useState(false);
    const [profileData, setProfileData] = useState({
        full_name: '', email: '', phone: '', date_of_birth: '',
        is_email_verified: false, is_mobile_verified: false, has_password: false,
        created_at: '',
    });
    const [originalEmail, setOriginalEmail] = useState('');
    const [originalPhone, setOriginalPhone] = useState('');
    const defaultDialCode = useMemo(() => {
        const match = COUNTRY_CODES.find(c => c.code === defaultCountryCode);
        return match ? match.dial_code : '+1';
    }, [defaultCountryCode]);
    const [selectedCountryCode, setSelectedCountryCode] = useState(defaultDialCode);

    // Email OTP modal state
    const [showEmailOtpModal, setShowEmailOtpModal] = useState(false);
    const [emailOtpCode, setEmailOtpCode] = useState('');
    const [emailOtpSubmitting, setEmailOtpSubmitting] = useState(false);
    const [emailOtpResendTimer, setEmailOtpResendTimer] = useState(0);

    // Phone OTP modal state
    const [showPhoneOtpModal, setShowPhoneOtpModal] = useState(false);
    const [phoneOtpCode, setPhoneOtpCode] = useState('');
    const [phoneOtpSubmitting, setPhoneOtpSubmitting] = useState(false);
    const [phoneOtpResendTimer, setPhoneOtpResendTimer] = useState(0);

    useEffect(() => {
        let interval: NodeJS.Timeout;
        if (showEmailOtpModal && emailOtpResendTimer > 0) {
            interval = setInterval(() => {
                setEmailOtpResendTimer(prev => prev - 1);
            }, 1000);
        }
        return () => clearInterval(interval);
    }, [showEmailOtpModal, emailOtpResendTimer]);

    useEffect(() => {
        let interval: NodeJS.Timeout;
