                                                        onError={() => {
                                                            if (base64Fallback && profileImageUrl !== base64Fallback) {
                                                                setProfileImageUrl(base64Fallback);
                                                            }
                                                        }}
                                                    />
                                                ) : (
                                                    <span className="text-3xl font-bold text-gray-900">
                                                        {user?.name?.charAt(0).toUpperCase()}
                                                    </span>
                                                )}
