                                                        <div className="sm:col-span-2">
                                                            <label className="block text-[10px] uppercase tracking-wider text-[#6B6B60] font-bold mb-1">Country *</label>
                                                            <div className="relative">
                                                                <Select
                                                                    options={countryOptions}
