                                            {(() => {
                                                if (useNewAddress) return newAddress.phone;
                                                const selAddr = savedAddresses.find(a => a.address_id === selectedAddressId);
                                                return selAddr?.phone;
                                            })() && <>{(() => {
                                                if (useNewAddress) return newAddress.phone;
                                                const selAddr = savedAddresses.find(a => a.address_id === selectedAddressId);
                                                return selAddr?.phone || '';
                                            })()}<br /></>}
