                                <div className="ritual-summary-title">
                                    <div className="w-8 h-8 rounded-full bg-[#F5F4F0] flex items-center justify-center mr-2 border border-[#E8E4DC]">
                                        <Leaf className="w-4 h-4 text-[#91C934]" />
                                    </div>
                                    Ritual Investment
                                    <span className="ritual-summary-badge">{itemsCount} Item{itemsCount !== 1 ? 's' : ''}</span>
                                </div>

                                <div className="space-y-1 max-h-[250px] overflow-y-auto pr-2 custom-scrollbar mt-4">
                                    {checkoutItems.map(item => {
                                        const price = isBuyNow ? (item as BuyNowItem).unit_price : (item as Record<string, unknown>).price ?? 0;
                                        const originalPrice = isBuyNow ? (item as BuyNowItem).original_price : (item as Record<string, unknown>).original_price ?? price;
                                        
                                        const resolvedSp = resolvePrice(price, (item as Record<string, unknown>).country_prices);
                                        const resolvedMrp = resolveMrp(originalPrice, price, (item as Record<string, unknown>).country_prices);
                                        const lineTotal = resolvedSp * item.quantity;
                                        const lineMrpTotal = resolvedMrp * item.quantity;

                                        return (
                                            <div key={(item as Record<string, unknown>).cart_item_id || item.product_id + (item.variant_id || '')} className="ritual-summary-item pb-3 border-b border-[#E8E4DC] last:border-0 last:pb-0">
                                                <div className="ritual-summary-item-img">
                                                    {item.image_url ? (
                                                        <img src={item.image_url} alt="" />
                                                    ) : (
                                                        <span className="flex items-center justify-center h-full text-sm text-[#1A1A1A]">­ƒî┐</span>
                                                    )}
                                                </div>
                                                <div className="ritual-summary-item-name">
                                                    {item.product_name || 'Product'}
                                                    {(item as Record<string, unknown>).size_label && <p className="text-[#a4a9a4] text-xs">{(item as Record<string, unknown>).size_label}</p>}
                                                    <div className="ritual-summary-item-qty mt-0.5">Qty: {item.quantity}</div>
                                                </div>
                                                <div className="flex flex-col items-end">
                                                    <span className="ritual-summary-item-price">{format(lineTotal)}</span>
                                                    {originalPrice > price && (
                                                        <div className="flex items-center gap-1 mt-0.5">
                                                            <span className="text-[10px] text-red-500 font-bold">
                                                                {Math.round((1 - price / originalPrice) * 100)}% OFF
                                                            </span>
                                                            <span className="text-[10px] text-gray-400 line-through">
                                                                {format(lineMrpTotal)}
                                                            </span>
                                                        </div>
                                                    )}
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>

                                <div className="ritual-summary-divider" />

                                <div className="space-y-2.5">
                                    <div className="ritual-summary-row">
                                        <span className="label font-medium text-gray-900">Total MRP</span>
                                        <span className="value font-medium text-gray-900">{format(totalMrp)}</span>
                                    </div>

                                    {mrpDiscount > 0 && (
                                        <div className="ritual-summary-row">
                                            <span className="label text-gray-600">Discount on MRP</span>
                                            <span className="value text-[#91C934] font-medium">- {format(mrpDiscount)}</span>
                                        </div>
                                    )}

                                    {!isBuyNow && couponDiscount > 0 && (
                                        <div className="ritual-summary-row">
                                            <span className="label text-gray-600 flex items-center gap-1"><Ticket className="w-3 h-3" /> Coupon Discount</span>
                                            <span className="value text-[#91C934] font-medium">- {format(resolvePrice(couponDiscount, null))}</span>
                                        </div>
                                    )}

