            <div className="max-w-7xl mx-auto px-6 py-20">

                {/* Search results header */}
                {searchResults && (
                    <div className="flex items-center justify-between mb-12 animate-in fade-in slide-in-from-top-4">
                        <h2 className="text-3xl font-bold text-[#1a2408]">
                            {searchResults.length > 0
                                ? `${searchResults.length} Wisdom Found for "${searchQuery}"`
                                : 'No results found in the hub'}
                        </h2>
                        <button
                            onClick={() => { setSearchQuery(''); setSearchResults(null); }}
                            className="text-sm font-black uppercase tracking-widest text-[#4A5D23] hover:text-[#3a491b] flex items-center gap-2 cursor-pointer bg-white px-6 py-3 rounded-full border border-[#4A5D23]/5 shadow-sm"
                        >
                            <ChevronLeft className="h-4 w-4" /> Clear Search
                        </button>
                    </div>
                )}

                {/* Category filter pills */}
                {!searchResults && categories.length > 0 && (
                    <div className="flex flex-wrap items-center justify-center gap-4 mb-20">
                        <button
                            onClick={() => {
                                setSelectedCategory('');
                                setExpandedId(null);
                                setLoading(true);
                                getKBArticles().then(a => { setArticles(Array.isArray(a) ? a : []); setLoading(false); });
                            }}
                            className={`px-8 py-3 rounded-[20px] text-sm font-black uppercase tracking-widest transition-all cursor-pointer shadow-sm ${!selectedCategory
                                ? 'bg-[#4A5D23] text-white shadow-[#4A5D23]/30 shadow-lg'
                                : 'bg-white text-[#5B4A31] border border-[#4A5D23]/5 hover:border-[#4A5D23]/30'
                                }`}
                        >
                            All Articles
                        </button>
                        {categories.map((cat: Record<string, unknown>) => (
                            <button
                                key={cat.category_id}
                                onClick={() => handleCategoryClick(cat.slug)}
                                className={`px-8 py-3 rounded-[20px] text-sm font-black uppercase tracking-widest transition-all cursor-pointer shadow-sm ${selectedCategory === cat.slug
                                    ? 'bg-[#4A5D23] text-white shadow-[#4A5D23]/30 shadow-lg'
                                    : 'bg-white text-[#5B4A31] border border-[#4A5D23]/5 hover:border-[#4A5D23]/30'
                                    }`}
                            >
                                {cat.name}
                            </button>
                        ))}
                    </div>
                )}

                {/* Article cards grid */}
                {loading ? (
                    /* Loading skeleton */
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10">
                        {[...Array(6)].map((_, i) => (
                            <div key={i} className="bg-white rounded-[40px] p-10 animate-pulse border border-[#4A5D23]/5 h-[400px]">
                                <div className="flex items-center justify-between mb-8">
                                    <div className="h-6 bg-gray-100 rounded-full w-24" />
                                    <div className="h-4 bg-gray-50 rounded w-16" />
                                </div>
                                <div className="w-16 h-16 bg-gray-100 rounded-2xl mb-8" />
                                <div className="h-8 bg-gray-100 rounded w-3/4 mb-4" />
                                <div className="h-4 bg-gray-50 rounded w-full mb-2" />
                                <div className="h-4 bg-gray-50 rounded w-2/3" />
                            </div>
                        ))}
                    </div>
                ) : displayArticles.length === 0 ? (
                    /* Empty state */
                    <div className="text-center py-32 bg-white rounded-[60px] border border-[#4A5D23]/5 shadow-xl">
                        <div className="w-24 h-24 rounded-[30px] bg-[#4A5D23]/10 flex items-center justify-center mx-auto mb-10">
                            <BookOpen className="h-10 w-10 text-[#4A5D23]" />
                        </div>
                        <h3 className="text-3xl font-bold text-[#1a2408] mb-4">The library is currently silent</h3>
                        <p className="text-lg text-[#5B4A31] max-w-sm mx-auto font-medium">
                            {searchResults ? 'Our archive doesn\'t seem to contain that wisdom. Try adjusting your search.' : 'Our scholars are preparing new guides for you.'}
                        </p>
                    </div>
                ) : (
                    /* Article cards */
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10">
                        {displayArticles.map((article: Record<string, unknown>) => {
                            const Icon = getCategoryIcon(article.category_name);
                            const readTime = estimateReadTime(article.content, article.excerpt);
                            const isExpanded = expandedId === article.article_id;

                            return (
                                <div
                                    key={article.article_id}
                                    className="bg-white rounded-[40px] border border-[#4A5D23]/5 overflow-hidden hover:shadow-[0_32px_64px_-16px_rgba(74,93,35,0.12)] hover:-translate-y-2 transition-all duration-500 group flex flex-col"
                                >
                                    <div className="p-10 flex-1 flex flex-col">
                                        {/* Top meta row */}
                                        <div className="flex items-center justify-between mb-8">
                                            {article.category_name && (
                                                <span className="text-[10px] font-black uppercase tracking-[0.2em] text-[#4A5D23] bg-[#4A5D23]/5 px-4 py-1.5 rounded-full">
                                                    {article.category_name}
                                                </span>
                                            )}
                                            <div className="flex items-center gap-1.5 text-xs font-bold text-[#5B4A31]/50">
                                                <Clock className="h-3.5 w-3.5" />
                                                {readTime} MIN READ
                                            </div>
                                        </div>

                                        {/* Icon */}
                                        <div className="w-16 h-16 rounded-2xl bg-[#4A5D23]/5 flex items-center justify-center mb-8 group-hover:bg-[#4A5D23] transition-all duration-500 shadow-inner">
                                            <Icon className="h-7 w-7 text-[#4A5D23] group-hover:text-white transition-colors duration-500" />
                                        </div>

                                        {/* Title */}
                                        <h3 className="text-xl md:text-2xl font-bold text-[#1a2408] mb-4 leading-snug group-hover:text-[#4A5D23] transition-colors">
                                            {article.title}
                                        </h3>

                                        {/* Excerpt */}
                                        {article.excerpt && (
                                            <p className="text-base text-[#5B4A31] leading-relaxed mb-6 flex-1 line-clamp-3 font-medium">
                                                {article.excerpt}
                                            </p>
                                        )}

                                        {/* Expanded content preview */}
                                        <div className={`overflow-hidden transition-all duration-500 ease-in-out ${isExpanded ? 'max-h-[500px] mb-6' : 'max-h-0'}`}>
                                            <div className="text-sm text-[#5B4A31] leading-relaxed border-t border-[#4A5D23]/10 pt-6 whitespace-pre-line font-medium">
                                                {article.content?.substring(0, 400)}
                                                {article.content && article.content.length > 400 && '...'}
                                            </div>
                                        </div>
                                    </div>

                                    {/* Footer action */}
                                    <div className="px-10 pb-10">
                                        <div className="flex items-center gap-6">
                                            <button
                                                onClick={() => setExpandedId(isExpanded ? null : article.article_id)}
                                                className="inline-flex items-center gap-2 text-xs font-black uppercase tracking-widest text-[#5B4A31] hover:text-[#4A5D23] transition-colors cursor-pointer group/btn"
                                            >
                                                {isExpanded ? 'Collapse' : 'Sneak Peek'}
                                                <ChevronDown className={`h-4 w-4 transition-transform duration-500 ${isExpanded ? 'rotate-180' : ''}`} />
                                            </button>
                                            <Link
                                                href={`/help-center/knowledge-base/${article.slug}`}
                                                className="inline-flex items-center gap-3 bg-[#4A5D23]/5 text-[#4A5D23] px-6 py-3 rounded-2xl text-xs font-black uppercase tracking-widest hover:bg-[#4A5D23] hover:text-white transition-all ml-auto hover:shadow-lg"
                                            >
                                                Open Article
                                                <ArrowRight className="h-4 w-4" />
                                            </Link>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                )}

                {/* Back + Help footer */}
                <div className="mt-32 flex flex-col sm:flex-row items-center justify-between gap-8 border-t border-[#4A5D23]/10 pt-16">
                    <Link
                        href="/help-center"
                        className="inline-flex items-center gap-4 text-lg font-bold text-[#5B4A31] hover:text-[#4A5D23] transition-all group"
                    >
                        <div className="w-14 h-14 rounded-2xl bg-white shadow-xl flex items-center justify-center group-hover:bg-[#4A5D23] group-hover:text-white transition-all">
                            <ChevronLeft className="h-7 w-7" />
                        </div>
                        Help Center Home
                    </Link>
                    <Link
                        href="/help-center/support"
                        className="inline-flex items-center gap-4 bg-[#4A5D23] text-white px-10 py-5 rounded-2xl text-lg font-black uppercase tracking-widest hover:bg-[#3a491b] transition-all shadow-2xl hover:-translate-y-1"
                    >
                        <HeadphonesIcon className="h-6 w-6" />
                        Request Support
                    </Link>
                </div>
            </div>
        </div>

    );
}

'use client';

import { useState, useEffect } from 'react';
import Link from 'next/link';
import { useParams } from 'next/navigation';
import { Search, MessageSquare, HelpCircle, BookOpen, FileText, ChevronRight, Send } from 'lucide-react';
import { getFaqs, getHelpArticles, searchFaqs, searchHelpArticles, searchKBArticles } from '@/lib/api';

export default function HelpCenterPage() {
    const params = useParams();
    const country = params?.country || 'in';
    const [searchQuery, setSearchQuery] = useState('');
    const [searchResults, setSearchResults] = useState<Record<string, unknown>[]>([]);
    const [searching, setSearching] = useState(false);
    const [popularFaqs, setPopularFaqs] = useState<Record<string, unknown>[]>([]);

    useEffect(() => {
        getFaqs().then((data: Record<string, unknown>) => {
            const faqs = data?.faqs || [];
            setPopularFaqs(faqs.slice(0, 5));
        });
    }, []);

    const handleSearch = async () => {
        if (!searchQuery.trim()) return;
        setSearching(true);
        try {
            const [faqResults, helpResults, kbResults] = await Promise.all([
                searchFaqs(searchQuery),
                searchHelpArticles(searchQuery),
                searchKBArticles(searchQuery),
            ]);
            const combined = [
                ...(Array.isArray(faqResults) ? faqResults.map((f: Record<string, unknown>) => ({ ...f, _type: 'faq' })) : []),
                ...(Array.isArray(helpResults) ? helpResults.map((a: Record<string, unknown>) => ({ ...a, _type: 'help' })) : []),
                ...(Array.isArray(kbResults) ? kbResults.map((a: Record<string, unknown>) => ({ ...a, _type: 'kb' })) : []),
            ];
            setSearchResults(combined);
        } catch {
            setSearchResults([]);
        } finally {
            setSearching(false);
        }
    };

    const sections = [
        {
            title: 'FAQs',
            desc: 'Find quick answers to common questions about orders, payments, and more.',
            icon: HelpCircle,
            href: `/${country}/help-center/faq`,
            color: '#722F37',
        },
        {
            title: 'Knowledge Base',
            desc: 'Browse detailed guides, tutorials, and documentation.',
            icon: BookOpen,
            href: `/${country}/help-center/knowledge-base`,
            color: '#8B4513',
        },
        {
            title: 'Support Tickets',
            desc: 'Submit a support request or track your existing tickets.',
            icon: MessageSquare,
            href: `/${country}/help-center/support`,
            color: '#4b0f1a',
        },
        {
            title: 'Customer Enquiry',
            desc: 'Share your thoughts, report an issue or contact us.',
            icon: Send,
            href: `/${country}/help-center/customer-enquiry`,
            color: '#5B3A29',
        },
    ];

    return (
        <div className="min-h-screen bg-[#FDFBF7]">
            {/* Hero Section */}
            <section className="relative py-24 px-6 overflow-hidden">
                {/* Ayurvedic Texture Background */}
                <div 
                    className="absolute inset-0 z-0 opacity-40 bg-repeat bg-center"
                    style={{ 
                        backgroundImage: "url('/ayurvedic-texture.png')",
                        backgroundSize: '400px',
                        filter: 'sepia(0.2) contrast(1.1)'
                    }}
                ></div>
                
                {/* Decorative Elements */}
                <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-b from-[#4A5D23]/10 to-transparent z-0"></div>
                
                <div className="max-w-4xl mx-auto text-center relative z-10">
                    <span className="inline-block px-4 py-1.5 rounded-full bg-[#4A5D23]/50 text-[#2D3A15] text-xs font-bold tracking-widest uppercase mb-6">
                        Vedic Support
                    </span>
                    <h1 className="text-4xl md:text-6xl font-bold text-[#1a2408] mb-6 leading-tight">
                        How can we <span className="text-[#4A5D23]">help you?</span>
                    </h1>
                    <p className="text-[#5B4A31] text-lg mb-8 max-w-2xl mx-auto font-bold leading-relaxed">
                        Find guidance, answers, and support for your Ayurvedic journey.
                    </p>
                    <div className="relative max-w-2xl mx-auto group">
                        <div className="absolute -inset-1 bg-gradient-to-r from-[#4A5D23]/20 to-[#8B4513]/20 rounded-2xl blur opacity-25 group-hover:opacity-50 transition duration-1000 group-hover:duration-200"></div>
                        <div className="relative">
                            <input
                                type="text"
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                                onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
                                placeholder="Search for help articles, FAQs, guides..."
                                className="w-full pl-14 pr-32 py-5 rounded-2xl bg-white/90 backdrop-blur-sm text-gray-900 placeholder-gray-400 text-lg border border-[#4A5D23]/10 focus:outline-none focus:ring-2 focus:ring-[#4A5D23] shadow-2xl transition-all"
                            />
                            <Search className="absolute left-5 top-1/2 -translate-y-1/2 h-6 w-6 text-[#4A5D23]" />
                            <button
                                onClick={handleSearch}
                                className="absolute right-2.5 top-1/2 -translate-y-1/2 bg-[#4A5D23] text-white px-8 py-3 rounded-xl text-base font-semibold hover:bg-[#3a491b] transition-all shadow-lg active:scale-95"
                            >
                                Search
                            </button>
                        </div>
                    </div>
                </div>
            </section>

            {/* Search Results */}
            {(searchResults.length > 0 || searching) && (
                <section className="max-w-4xl mx-auto px-6 py-8">
                    <h2 className="text-xl font-bold text-[#1a2408] mb-6 flex items-center gap-2">
                        <div className="w-2 h-8 bg-[#4A5D23] rounded-full"></div>
                        {searching ? 'Finding answers...' : `${searchResults.length} result${searchResults.length !== 1 ? 's' : ''} found`}
                    </h2>
                    {!searching && (
                        <div className="grid gap-4">
                            {searchResults.map((item, i) => (
                                <Link
                                    key={i}
                                    href={
                                        item._type === 'faq'
                                            ? `/${country}/help-center/faq`
                                            : item._type === 'help'
                                                ? `/${country}/help-center/${item.slug || ''}`
                                                : `/${country}/help-center/knowledge-base/${item.slug || ''}`
                                    }
                                    className="block bg-white/60 backdrop-blur-sm rounded-2xl p-5 border border-[#4A5D23]/5 hover:border-[#4A5D23]/30 hover:shadow-xl hover:-translate-y-0.5 transition-all duration-300 group"
                                >
                                    <div className="flex items-start gap-4">
                                        <div className="bg-[#4A5D23]/10 p-2 rounded-lg group-hover:bg-[#4A5D23] transition-colors">
                                            <FileText className="h-5 w-5 text-[#4A5D23] group-hover:text-white" />
                                        </div>
                                        <div>
                                            <div className="flex items-center gap-3 mb-1">
                                                <h3 className="font-bold text-[#1a2408] group-hover:text-[#4A5D23] transition-colors">
                                                    {item.question || item.title}
                                                </h3>
                                                <span className="text-[10px] uppercase tracking-widest font-black px-2 py-0.5 rounded-md bg-[#4A5D23]/10 text-[#4A5D23]">
                                                    {item._type === 'faq' ? 'FAQ' : item._type === 'help' ? 'Help' : 'Guide'}
                                                </span>
                                            </div>
                                            <p className="text-sm text-[#5B4A31] line-clamp-2">
                                                {item.answer || item.excerpt || item.content?.substring(0, 150) + '...'}
                                            </p>
                                        </div>
                                    </div>
                                </Link>
                            ))}
                        </div>
                    )}
                </section>
            )}

            {/* Quick-access Cards */}
            <section className="max-w-6xl mx-auto px-6 -mt-10 relative z-10 mb-20">
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                    {sections.map((section) => {
                        const Icon = section.icon;
                        const herbalColors = [
                            { bg: '#E8EDDF', text: '#4A5D23' },
                            { bg: '#F2E8CF', text: '#8B4513' },
                            { bg: '#E9F5F2', text: '#2E5A50' },
                            { bg: '#F9F1E7', text: '#A67C52' }
                        ];
                        const colorIdx = sections.indexOf(section) % herbalColors.length;
                        const theme = herbalColors[colorIdx];

                        return (
                            <Link
                                key={section.title}
                                href={section.href}
                                className="group relative bg-white rounded-3xl p-8 border border-[#4A5D23]/5 hover:border-[#4A5D23]/20 shadow-sm hover:shadow-2xl transition-all duration-500 overflow-hidden"
                            >
                                <div className="absolute top-0 right-0 w-24 h-24 bg-gradient-to-br from-[#4A5D23]/5 to-transparent rounded-bl-[100px] -mr-4 -mt-4 group-hover:w-32 group-hover:h-32 transition-all duration-500"></div>
                                
                                <div
                                    className="w-16 h-16 rounded-2xl flex items-center justify-center mb-6 transition-all duration-500 group-hover:rotate-6 group-hover:scale-110 shadow-inner"
                                    style={{ backgroundColor: theme.bg }}
                                >
                                    <Icon className="h-8 w-8" style={{ color: theme.text }} />
                                </div>
                                <h3 className="text-xl font-bold text-[#1a2408] mb-3">{section.title}</h3>
                                <p className="text-sm text-[#5B4A31] leading-relaxed mb-6">{section.desc}</p>
                                <div 
                                    className="inline-flex items-center gap-2 text-sm font-bold tracking-wide transition-all duration-300 group-hover:gap-3"
                                    style={{ color: theme.text }}
                                >
                                    Explore More <ChevronRight className="h-4 w-4" />
                                </div>
                            </Link>
                        );
                    })}
                </div>
            </section>

            {/* Popular FAQs */}
            {popularFaqs.length > 0 && (
                <section className="max-w-5xl mx-auto px-6 py-20 bg-[#FDFBF7] rounded-[50px] mb-20 border border-[#4A5D23]/5">
                    <div className="text-center mb-12">
                        <h2 className="text-3xl md:text-4xl font-bold text-[#1a2408] mb-4">Common Questions</h2>
                        <div className="w-24 h-1 bg-[#4A5D23] mx-auto rounded-full opacity-30"></div>
                    </div>
                    <div className="grid md:grid-cols-1 gap-4 max-w-3xl mx-auto">
                        {popularFaqs.map((faq: Record<string, unknown>) => (
                            <Link
                                key={faq.faq_id}
                                href={`/${country}/help-center/faq`}
                                className="flex items-center justify-between bg-white rounded-2xl p-6 border border-[#4A5D23]/5 hover:border-[#4A5D23]/20 hover:shadow-md transition-all group"
                            >
                                <div className="flex items-center gap-4">
                                    <div className="w-10 h-10 rounded-full bg-[#4A5D23]/5 flex items-center justify-center group-hover:bg-[#4A5D23] transition-colors">
                                        <HelpCircle className="h-5 w-5 text-[#4A5D23] group-hover:text-white" />
                                    </div>
                                    <span className="text-base font-semibold text-[#1a2408]">{faq.question}</span>
                                </div>
                                <div className="p-2 rounded-lg bg-gray-50 group-hover:bg-[#4A5D23]/10 transition-colors">
                                    <ChevronRight className="h-5 w-5 text-[#4A5D23]" />
                                </div>
                            </Link>
                        ))}
                    </div>
                    <div className="text-center mt-10">
                        <Link
                            href={`/${country}/help-center/faq`}
                            className="inline-flex items-center gap-2 py-3 px-8 rounded-full border-2 border-[#4A5D23] text-[#4A5D23] font-bold hover:bg-[#4A5D23] hover:text-white transition-all"
                        >
                            View all FAQs
                        </Link>
                    </div>
                </section>
            )}

            {/* Contact CTA */}
            <section className="max-w-5xl mx-auto px-6 pb-24">
                <div className="relative overflow-hidden bg-[#1a2408] rounded-[40px] p-10 md:p-16 text-center">
                    {/* Background Pattern */}
                    <div className="absolute inset-0 opacity-10 pointer-events-none">
                        <div className="absolute inset-0 bg-[url('/ayurvedic-texture.png')] bg-repeat opacity-20"></div>
                    </div>
                    
                    <div className="relative z-10">
                        <h2 className="text-3xl md:text-5xl font-bold text-[#F2E8CF] mb-4">
                            Didn&apos;t find what you need?
                        </h2>
                        <p className="text-[#A6BF8F] mb-10 text-lg max-w-xl mx-auto font-medium">
                            Our Ayurvedic experts and support team are just a message away.
                        </p>
                        <div className="flex flex-col sm:flex-row gap-5 justify-center">
                            <Link
                                href={`/${country}/help-center/support`}
                                className="inline-flex items-center justify-center gap-3 bg-[#4A5D23] text-white px-10 py-5 rounded-2xl font-bold text-lg hover:bg-[#3a491b] hover:shadow-2xl hover:-translate-y-1 transition-all"
                            >
                                <MessageSquare className="h-6 w-6" />
                                Submit a Ticket
                            </Link>
                            <Link
                                href={`/${country}/contact`}
                                className="inline-flex items-center justify-center gap-3 border-2 border-[#F2E8CF]/30 text-[#F2E8CF] px-10 py-5 rounded-2xl font-bold text-lg hover:bg-[#F2E8CF]/10 transition-all"
                            >
                                Contact Us
                            </Link>
                        </div>
                    </div>
                </div>
            </section>
        </div>
    );
}

'use client';

import { useState, useEffect, useRef } from 'react';
import Link from 'next/link';
import { useParams } from 'next/navigation';
import { useAuth } from '@/context/AuthContext';
import {
    ChevronLeft, Send, User, Shield, Clock,
    MessageSquare, AlertCircle, Zap
} from 'lucide-react';
import { getSupportTicketDetail, replySupportTicket } from '@/lib/api';
import toast from 'react-hot-toast';

const STATUS_CONFIG: Record<string, { label: string; bg: string; text: string; dot: string }> = {
    open: { label: 'Open', bg: 'bg-[#4A5D23]/10', text: 'text-[#4A5D23]', dot: 'bg-[#4A5D23]' },
    in_progress: { label: 'In Progress', bg: 'bg-[#8B4513]/10', text: 'text-[#8B4513]', dot: 'bg-[#8B4513]' },
    resolved: { label: 'Resolved', bg: 'bg-[#2E5A50]/10', text: 'text-[#2E5A50]', dot: 'bg-[#2E5A50]' },
    closed: { label: 'Closed', bg: 'bg-[#1a2408]/10', text: 'text-[#1a2408]', dot: 'bg-[#1a2408]' },
};

const PRIORITY_CONFIG: Record<string, { label: string; color: string; icon: string }> = {
    low: { label: 'Low', color: 'text-gray-400', icon: 'Ôùï' },
    medium: { label: 'Medium', color: 'text-amber-600', icon: 'ÔùÅ' },
    high: { label: 'High', color: 'text-[#4A5D23]', icon: 'ÔùÅ' },
    urgent: { label: 'Urgent', color: 'text-red-600', icon: 'Ôû▓' },
};

function formatTime(date: string) {
    return new Date(date).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
}

function formatDate(date: string) {
    return new Date(date).toLocaleDateString([], { weekday: 'long', month: 'long', day: 'numeric' });
}

export default function TicketDetailPage() {
    const params = useParams();
    const ticketId = params.ticketId as string;
    const { isAuthenticated } = useAuth();
    const [data, setData] = useState<Record<string, unknown>>(null);
    const [loading, setLoading] = useState(true);
    const [replyText, setReplyText] = useState('');
    const [sending, setSending] = useState(false);
    const messagesEndRef = useRef<HTMLDivElement>(null);

    const loadTicket = async () => {
        const result = await getSupportTicketDetail(ticketId);
        setData(result);
        setLoading(false);
    };

    useEffect(() => {
        if (isAuthenticated && ticketId) loadTicket();
        else setLoading(false);
    }, [isAuthenticated, ticketId]);

    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [data?.messages]);

    const handleReply = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!replyText.trim()) return;
        setSending(true);
        try {
            const result = await replySupportTicket(ticketId, replyText);
            if (result.success) {
                setReplyText('');
                await loadTicket();
                toast.success('Your scroll has been sent');
            } else {
                toast.error(result.message || 'Failed to send reply');
            }
        } catch {
            toast.error('Network error');
        } finally {
            setSending(false);
        }
    };

    /* ÔöÇÔöÇ Loading state ÔöÇÔöÇ */
    if (loading) {
        return (
            <div className="min-h-screen bg-[#FDFBF7]">
                <div className="max-w-4xl mx-auto px-6 py-20">
                    <div className="animate-pulse space-y-12">
                        <div className="h-4 bg-gray-100 rounded-full w-32" />
                        <div className="h-10 bg-gray-200 rounded-2xl w-3/4" />
                        <div className="flex gap-4">
                            <div className="h-8 bg-gray-100 rounded-full w-24" />
                            <div className="h-8 bg-gray-100 rounded-full w-24" />
                        </div>
                        <div className="space-y-6 mt-12 bg-white rounded-[40px] h-[400px] border border-[#4A5D23]/5 shadow-sm"></div>
                    </div>
                </div>
            </div>
        );
    }

    /* ÔöÇÔöÇ Not found ÔöÇÔöÇ */
    if (!data?.ticket) {
        return (
            <div className="min-h-screen bg-[#FDFBF7] flex items-center justify-center p-6">
                <div className="text-center bg-white rounded-[60px] p-16 border border-[#4A5D23]/5 shadow-2xl max-w-lg w-full">
                    <div className="w-24 h-24 rounded-[30px] bg-[#4A5D23]/10 flex items-center justify-center mx-auto mb-10">
                        <MessageSquare className="h-10 w-10 text-[#4A5D23]" />
                    </div>
                    <h2 className="text-3xl font-bold text-[#1a2408] mb-4">Inquiry Not Found</h2>
                    <p className="text-[#5B4A31] mb-10 font-medium">This scroll seems to have vanished from our records.</p>
                    <Link href="/help-center/support" className="inline-flex items-center gap-3 bg-[#4A5D23] text-white px-10 py-5 rounded-[20px] font-black uppercase tracking-widest text-sm hover:bg-[#3a491b] transition-all shadow-xl">
                        <ChevronLeft className="h-5 w-5" /> Back to Tickets
                    </Link>
                </div>
            </div>
        );
    }

    const { ticket, messages = [] } = data;
    const isClosed = ticket.status === 'closed' || ticket.status === 'resolved';
    const status = STATUS_CONFIG[ticket.status] || STATUS_CONFIG.open;
    const priority = PRIORITY_CONFIG[ticket.priority] || PRIORITY_CONFIG.medium;

    /* ÔöÇÔöÇ Group messages by date ÔöÇÔöÇ */
    const groupedMessages: { date: string; items: Record<string, unknown>[] }[] = [];
    messages.forEach((msg: Record<string, unknown>) => {
        const dateStr = formatDate(msg.created_at);
        const last = groupedMessages[groupedMessages.length - 1];
        if (last && last.date === dateStr) {
            last.items.push(msg);
        } else {
            groupedMessages.push({ date: dateStr, items: [msg] });
        }
    });

    return (
        <div className="min-h-screen bg-[#FDFBF7] flex flex-col">
            {/* ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ TICKET HEADER ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ */}
            <div className="bg-white/80 backdrop-blur-md border-b border-[#4A5D23]/5 relative z-20">
                {/* Ayurvedic Texture Overlay (Very subtle) */}
                <div className="absolute inset-0 opacity-5 bg-repeat pointer-events-none" style={{ backgroundImage: "url('/ayurvedic-texture.png')", backgroundSize: '300px' }}></div>
                
                <div className="max-w-4xl mx-auto px-6 py-10 relative z-10">
                    <Link
                        href="/help-center/support"
                        className="inline-flex items-center gap-3 text-xs font-black uppercase tracking-widest text-[#5B4A31]/60 hover:text-[#4A5D23] transition-all mb-8 group"
                    >
                        <ChevronLeft className="h-4 w-4 group-hover:-translate-x-1 transition-transform" />
                        My Support Tickets
                    </Link>

                    <h1 className="text-3xl md:text-4xl font-bold text-[#1a2408] mb-6 leading-tight">
                        {ticket.subject}
                    </h1>

                    <div className="flex flex-wrap items-center gap-4">
                        {/* Status badge */}
                        <span className={`inline-flex items-center gap-2 text-[10px] font-black uppercase tracking-widest px-4 py-2 rounded-full border border-transparent shadow-sm ${status.bg} ${status.text}`}>
                            <span className={`w-1.5 h-1.5 rounded-full ${status.dot}`} />
                            {status.label}
                        </span>

                        {/* Priority badge */}
                        <span className={`inline-flex items-center gap-2 text-[10px] font-black uppercase tracking-widest px-4 py-2 rounded-full bg-gray-50 border border-gray-100 ${priority.color}`}>
                            {priority.icon} {priority.label} Priority
                        </span>

                        {/* Ticket number */}
                        <span className="text-[10px] font-black font-mono text-gray-400 bg-gray-50 uppercase tracking-widest px-4 py-2 rounded-full border border-gray-100">
                            INQUIRY #{ticket.ticket_number}
                        </span>

                        {/* Meta info */}
                        <span className="text-xs font-bold text-[#5B4A31]/40 flex items-center gap-2 ml-auto">
                            <Clock className="h-4 w-4" />
                            CREATED {new Date(ticket.created_at).toLocaleDateString()}
                        </span>
                    </div>
                </div>
            </div>

            {/* ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ CHAT AREA ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ */}
            <div className="flex-1 relative">
                <div className="max-w-4xl mx-auto px-6 py-12 md:py-20">
                    {/* Chat Container */}
                    <div className="bg-white rounded-[40px] border border-[#4A5D23]/5 overflow-hidden shadow-[0_32px_64px_-16px_rgba(74,93,35,0.08)] flex flex-col min-h-[600px]">
                        <div className="flex items-center justify-between px-10 py-6 border-b border-gray-50 bg-[#FDFBF7]/30">
                            <div className="flex items-center gap-3">
                                <div className="w-2.5 h-2.5 rounded-full bg-[#4A5D23] animate-pulse" />
                                <span className="text-xs font-black uppercase tracking-widest text-[#1a2408]">Live Correspondence</span>
                            </div>
                            <span className="text-[10px] font-black uppercase tracking-[0.2em] text-[#5B4A31]/40">
                                {messages.length} MESSAGE{messages.length !== 1 ? 'S' : ''}
                            </span>
                        </div>

                        {/* Messages */}
                        <div className="flex-1 px-6 md:px-10 py-10 overflow-y-auto space-y-10 scrollbar-hide">
                            {messages.length === 0 ? (
                                <div className="text-center py-20">
                                    <div className="w-20 h-20 bg-gray-50 rounded-[30px] flex items-center justify-center mx-auto mb-6">
                                        <MessageSquare className="h-8 w-8 text-gray-200" />
                                    </div>
                                    <p className="text-lg font-medium text-[#5B4A31]/60">Answering your call to nature soon...</p>
                                </div>
                            ) : (
                                <div className="space-y-12">
                                    {groupedMessages.map((group) => (
                                        <div key={group.date}>
                                            {/* Date divider */}
                                            <div className="flex items-center gap-6 mb-10">
                                                <div className="flex-1 h-px bg-gray-100" />
                                                <span className="text-[10px] font-black uppercase tracking-[0.3em] text-[#5B4A31]/30">
                                                    {group.date}
                                                </span>
                                                <div className="flex-1 h-px bg-gray-100" />
                                            </div>

                                            {group.items.map((msg: Record<string, unknown>) => {
                                                const isAdmin = msg.sender_type === 'admin';
                                                return (
                                                    <div
                                                        key={msg.message_id}
                                                        className={`flex gap-4 md:gap-6 mb-8 ${isAdmin ? '' : 'flex-row-reverse'}`}
                                                    >
                                                        {/* Avatar */}
                                                        <div
                                                            className={`w-12 h-12 rounded-2xl flex items-center justify-center flex-shrink-0 shadow-inner transition-transform hover:scale-105 duration-300 ${isAdmin
                                                                ? 'bg-[#4A5D23] text-white'
                                                                : 'bg-[#FDFBF7] border border-gray-100 text-[#5B4A31]'
                                                                }`}
                                                        >
                                                            {isAdmin ? (
                                                                <Shield className="h-6 w-6" />
                                                            ) : (
                                                                <User className="h-6 w-6" />
                                                            )}
                                                        </div>

                                                        <div className={`max-w-[85%] md:max-w-[70%] ${isAdmin ? '' : 'text-right'}`}>
                                                            {/* Sender name + time */}
                                                            <div className={`flex items-center gap-3 mb-2 ${isAdmin ? '' : 'justify-end'}`}>
                                                                <span className="text-xs font-black uppercase tracking-widest text-[#1a2408]">
                                                                    {isAdmin ? (msg.sender_name ? `${msg.sender_name} (Support)` : 'Vedic Guard') : msg.sender_name || 'Seeker'}
                                                                </span>
                                                                <span className="text-[10px] font-bold text-[#5B4A31]/30">
                                                                    {formatTime(msg.created_at)}
                                                                </span>
                                                            </div>

                                                            {/* Message bubble */}
                                                            <div
                                                                className={`rounded-[24px] px-6 py-4 text-base leading-relaxed whitespace-pre-line shadow-sm transition-all hover:shadow-md ${isAdmin
                                                                    ? 'bg-[#4A5D23] text-white rounded-tl-md'
                                                                    : 'bg-[#FDFBF7] text-[#1a2408] border border-[#4A5D23]/5 rounded-tr-md text-left'
                                                                    }`}
                                                            >
                                                                {msg.body}
                                                            </div>
                                                        </div>
                                                    </div>
                                                );
                                            })}
                                        </div>
                                    ))}
                                </div>
                            )}
                            <div ref={messagesEndRef} />
                        </div>

                        {/* Reply input */}
                        {!isClosed ? (
                            <form onSubmit={handleReply} className="p-8 md:p-10 border-t border-gray-50 bg-[#FDFBF7]/30">
                                <div className="bg-white rounded-[30px] border border-[#4A5D23]/10 p-2 shadow-2xl focus-within:ring-2 focus-within:ring-[#4A5D23]/20 transition-all">
                                    <textarea
                                        value={replyText}
                                        onChange={(e) => setReplyText(e.target.value)}
                                        onKeyDown={(e) => {
                                            if (e.key === 'Enter' && !e.shiftKey) {
                                                e.preventDefault();
                                                if (replyText.trim()) handleReply(e);
                                            }
                                        }}
                                        placeholder="Add your message to the scroll..."
                                        rows={3}
                                        className="w-full px-6 py-4 text-base text-[#1a2408] placeholder-[#5B4A31]/30 bg-transparent border-none focus:outline-none focus:ring-0 resize-none font-medium"
                                    />
                                    <div className="flex items-center justify-between px-6 pb-4">
                                        <div className="flex items-center gap-3 text-[10px] font-black uppercase tracking-widest text-[#5B4A31]/30">
                                            <Zap className="h-3.5 w-3.5" />
                                            Press Enter to Send
                                        </div>
                                        <button
                                            type="submit"
                                            disabled={sending || !replyText.trim()}
                                            className="inline-flex items-center gap-3 bg-[#4A5D23] text-white px-8 py-3 rounded-2xl text-xs font-black uppercase tracking-widest hover:bg-[#3a491b] transition-all disabled:opacity-50 cursor-pointer shadow-lg hover:-translate-y-1"
                                        >
                                            Send Scroll
                                            <Send className="h-4 w-4" />
                                        </button>
                                    </div>
                                </div>
                            </form>
                        ) : (
                            <div className="p-10 border-t border-gray-50 bg-gray-50/20">
                                <div className="text-center max-w-sm mx-auto">
                                    <div className="w-12 h-12 rounded-2xl bg-gray-100 flex items-center justify-center mx-auto mb-6">
                                        <Shield className="h-6 w-6 text-gray-400" />
                                    </div>
                                    <p className="text-base font-bold text-[#1a2408] mb-1">
                                        This scroll has been completed.
                                    </p>
                                    <p className="text-sm text-[#5B4A31]/60 font-medium">
                                        If further wisdom is needed, please{' '}
                                        <Link href="/help-center/support" className="text-[#4A5D23] font-black hover:underline">
                                            create a new inquiry
                                        </Link>.
                                    </p>
                                </div>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect, Suspense } from 'react';
import Link from 'next/link';
import { useRouter, useSearchParams, useParams } from 'next/navigation';
import { useAuth } from '@/context/AuthContext';
import {
    ChevronLeft, Plus, MessageSquare, Clock, AlertCircle,
    X, Search, Ticket, Send, ChevronDown,
    ArrowUpRight, Filter, MoreHorizontal, Leaf, Sparkles
} from 'lucide-react';
import { createSupportTicket, getMySupportTickets } from '@/lib/api';
import toast from 'react-hot-toast';

const CATEGORIES = ['Orders', 'Payments', 'Shipping & Delivery', 'Product Issues', 'Returns & Refunds', 'Account Support', 'Other'];
const PRIORITIES = ['low', 'medium', 'high', 'urgent'] as const;

const STATUS_CONFIG: Record<string, { label: string; bg: string; text: string; dot: string }> = {
    open: { label: 'Open', bg: 'bg-[#4A5D23]/10', text: 'text-[#4A5D23]', dot: 'bg-[#4A5D23]' },
    in_progress: { label: 'In Progress', bg: 'bg-[#8B4513]/10', text: 'text-[#8B4513]', dot: 'bg-[#8B4513]' },
    resolved: { label: 'Resolved', bg: 'bg-[#1a2408]/10', text: 'text-[#1a2408]', dot: 'bg-[#1a2408]' },
    closed: { label: 'Closed', bg: 'bg-gray-100', text: 'text-gray-500', dot: 'bg-gray-400' },
};

const PRIORITY_CONFIG: Record<string, { label: string; color: string; icon: string }> = {
    low: { label: 'Low', color: 'text-gray-400', icon: 'Ôåô' },
    medium: { label: 'Medium', color: 'text-[#8B4513]', icon: 'ÔåÆ' },
    high: { label: 'High', color: 'text-[#4A5D23]', icon: 'Ôåæ' },
    urgent: { label: 'Urgent', color: 'text-red-500', icon: 'ÔÜí' },
};

function timeAgo(date: string) {
    const seconds = Math.floor((Date.now() - new Date(date).getTime()) / 1000);
    if (seconds < 60) return 'just now';
    const minutes = Math.floor(seconds / 60);
    if (minutes < 60) return `${minutes} min${minutes > 1 ? 's' : ''} ago`;
    const hours = Math.floor(minutes / 60);
    if (hours < 24) return `${hours} hour${hours > 1 ? 's' : ''} ago`;
    const days = Math.floor(hours / 24);
    if (days < 7) return `${days} day${days > 1 ? 's' : ''} ago`;
    return new Date(date).toLocaleDateString();
}

export default function SupportPage() {
    return (
        <Suspense fallback={<div className="p-12 text-center text-[#5B4A31]">Loading support...</div>}>
            <SupportContent />
        </Suspense>
    );
}

function SupportContent() {
    const params = useParams();
    const country = params?.country || 'in';
    const { isAuthenticated, user } = useAuth();
    const searchParams = useSearchParams();
    const urlOrderId = searchParams.get('orderId');

    const [tickets, setTickets] = useState<Record<string, unknown>[]>([]);
    const [loading, setLoading] = useState(true);
    const [view, setView] = useState<'list' | 'create'>(urlOrderId ? 'create' : 'list');
    const [submitting, setSubmitting] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');
    const [statusFilter, setStatusFilter] = useState<string>('');
    const [form, setForm] = useState({
        subject: '', category: 'Orders', description: '', order_id: urlOrderId || '', priority: 'medium',
    });

    useEffect(() => {
        if (urlOrderId) {
            setView('create');
            setForm(prev => ({ ...prev, order_id: urlOrderId, category: 'Orders' }));
        }
    }, [urlOrderId]);

    useEffect(() => {
        if (isAuthenticated) {
            getMySupportTickets().then((data: Record<string, unknown>) => {
                setTickets(Array.isArray(data) ? data : []);
                setLoading(false);
            });
        } else {
            setLoading(false);
        }
    }, [isAuthenticated]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!form.subject.trim() || !form.description.trim()) {
            toast.error('Subject and description are required');
            return;
        }
        setSubmitting(true);
        try {
            const result = await createSupportTicket({
                subject: form.subject,
                category: form.category,
                description: form.description,
                order_id: form.order_id || undefined,
                priority: form.priority,
            });
            if (result.success) {
                toast.success('Ticket created successfully!');
                setView('list');
                setForm({ subject: '', category: 'Other', description: '', order_id: '', priority: 'medium' });
                const refreshed = await getMySupportTickets();
                setTickets(Array.isArray(refreshed) ? refreshed : []);
            } else {
                toast.error(result.message || 'Failed to create ticket');
            }
        } catch {
            toast.error('Network error. Please try again.');
        } finally {
            setSubmitting(false);
        }
    };

    /* ÔöÇÔöÇ Derived data ÔöÇÔöÇ */
    const filteredTickets = tickets.filter((t) => {
        if (statusFilter && t.status !== statusFilter) return false;
        if (searchQuery) {
            const q = searchQuery.toLowerCase();
            return (
                t.subject?.toLowerCase().includes(q) ||
                t.ticket_number?.toLowerCase().includes(q) ||
                t.category?.toLowerCase().includes(q)
            );
        }
        return true;
    });

    const stats = {
        total: tickets.length,
        open: tickets.filter((t) => t.status === 'open').length,
        inProgress: tickets.filter((t) => t.status === 'in_progress').length,
        resolved: tickets.filter((t) => t.status === 'resolved' || t.status === 'closed').length,
    };

    return (
        <div className="min-h-screen bg-[#FDFBF7]">
            {/* ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ AUTH GATE ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ */}
            {!isAuthenticated ? (
                <section className="relative min-h-[60vh] flex items-center justify-center overflow-hidden py-24 px-6">
                    {/* Ayurvedic Texture Background */}
                    <div 
                        className="absolute inset-0 z-0 opacity-40 bg-repeat bg-center"
                        style={{ 
                            backgroundImage: "url('/ayurvedic-texture.png')",
                            backgroundSize: '400px',
                            filter: 'sepia(0.2) contrast(1.1)'
                        }}
                    ></div>
                    
                    {/* Decorative Elements */}
                    <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-b from-[#4A5D23]/10 via-transparent to-[#4A5D23]/5 z-0"></div>
                    
                    <div className="max-w-xl mx-auto text-center relative z-10">
                        <div className="w-24 h-24 rounded-[30px] bg-[#4A5D23]/10 backdrop-blur-sm border border-[#4A5D23]/20 flex items-center justify-center mx-auto mb-8 shadow-2xl">
                            <AlertCircle className="h-12 w-12 text-[#4A5D23]" />
                        </div>
                        <h1 className="text-4xl md:text-5xl font-bold text-[#1a2408] mb-6 leading-tight">
                            Sign in to access <span className="text-[#4A5D23]">support</span>
                        </h1>
                        <p className="text-[#5B4A31] text-lg mb-10 font-medium max-w-sm mx-auto">
                            You need to be logged in to submit and track your support tickets.
                        </p>
                        <Link 
                            href={`/${country}/login`} 
                            className="inline-flex items-center gap-3 bg-[#4A5D23] text-white px-10 py-4 rounded-[20px] font-bold text-lg hover:bg-[#3a491b] hover:shadow-2xl hover:-translate-y-1 transition-all shadow-xl"
                        >
                            Sign In Now
                        </Link>
                    </div>
                </section>
            ) : view === 'create' ? (
                /* ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ CREATE TICKET VIEW ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ */
                <>
                    {/* Breadcrumb bar */}
                    <div className="bg-white/80 backdrop-blur-md border-b border-[#4A5D23]/5 sticky top-0 z-50">
                        <div className="max-w-4xl mx-auto px-6 py-5">
                            <nav className="flex items-center gap-3 text-sm font-bold tracking-wide">
                                <Link href={`/${country}/help-center`} className="text-[#5B4A31] hover:text-[#4A5D23] transition-colors">Help & Support</Link>
                                <ChevronDown className="h-4 w-4 text-gray-300 -rotate-90" />
                                <Link href={`/${country}/help-center/support`} onClick={(e) => { e.preventDefault(); setView('list'); }} className="text-[#5B4A31] hover:text-[#4A5D23] transition-colors cursor-pointer">Support Tickets</Link>
                                <ChevronDown className="h-4 w-4 text-gray-300 -rotate-90" />
                                <span className="text-[#4A5D23] font-black uppercase text-xs">Create Ticket</span>
                            </nav>
                        </div>
                    </div>

                    <div className="max-w-4xl mx-auto px-6 py-12 md:py-16">
                        <form onSubmit={handleSubmit} className="bg-white rounded-[40px] border border-[#4A5D23]/5 shadow-2xl overflow-hidden animate-in fade-in slide-in-from-bottom-5 duration-700">
                            <div className="p-10 md:p-14">
                                <div className="flex items-center justify-between mb-10">
                                    <div>
                                        <h2 className="text-3xl md:text-4xl font-bold text-[#1a2408] mb-2">Create New Ticket</h2>
                                        <div className="w-16 h-1 bg-[#4A5D23] rounded-full opacity-30"></div>
                                    </div>
                                    <MessageSquare className="h-10 w-10 text-[#4A5D23]/20" />
                                </div>
                                <p className="text-lg text-[#5B4A31] mb-12 font-medium leading-relaxed">
                                    Fill out the details below and our support engineers will get back to you shortly.
                                </p>

                                {/* Subject */}
                                <div className="mb-10 group">
                                    <label className="block text-sm font-black text-[#1a2408] uppercase tracking-widest mb-3">Subject</label>
                                    <div className="relative">
                                        <input
                                            type="text"
                                            value={form.subject}
                                            onChange={(e) => setForm({ ...form, subject: e.target.value })}
                                            placeholder="e.g., Unable to sync order status..."
                                            className="w-full px-6 py-5 rounded-2xl bg-gray-50/50 border border-transparent text-lg focus:outline-none focus:ring-2 focus:ring-[#4A5D23]/20 focus:bg-white focus:border-[#4A5D23]/30 transition-all font-medium"
                                            required
                                        />
                                    </div>
                                    <p className="text-xs text-[#5B4A31]/60 mt-3 font-semibold flex items-center gap-2">
                                        <AlertCircle className="h-4 w-4 text-[#4A5D23]" />
                                        Use a descriptive title for faster investigation.
                                    </p>
                                </div>

                                {/* Category + Priority row */}
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-10 mb-10">
                                    <div className="group">
                                        <label className="block text-sm font-black text-[#1a2408] uppercase tracking-widest mb-3">Category</label>
                                        <div className="relative">
                                            <select
                                                value={form.category}
                                                onChange={(e) => setForm({ ...form, category: e.target.value })}
                                                className="w-full pl-6 pr-12 py-5 rounded-2xl bg-gray-50/50 border border-transparent text-lg focus:outline-none focus:ring-2 focus:ring-[#4A5D23]/20 focus:bg-white focus:border-[#4A5D23]/30 transition-all font-medium appearance-none"
                                            >
                                                {CATEGORIES.map((cat) => <option key={cat} value={cat}>{cat}</option>)}
                                            </select>
                                            <ChevronDown className="absolute right-5 top-1/2 -translate-y-1/2 h-6 w-6 text-gray-400 pointer-events-none" />
                                        </div>
                                    </div>
                                    <div>
                                        <label className="block text-sm font-black text-[#1a2408] uppercase tracking-widest mb-3">Priority</label>
                                        <div className="flex bg-gray-50/50 p-1.5 rounded-2xl gap-1 border border-transparent">
                                            {PRIORITIES.map((p) => (
                                                <button
                                                    key={p}
                                                    type="button"
                                                    onClick={() => setForm({ ...form, priority: p })}
                                                    className={`flex-1 py-4 rounded-xl text-xs font-black uppercase tracking-wider transition-all cursor-pointer ${form.priority === p
                                                        ? 'bg-[#4A5D23] text-white shadow-lg'
                                                        : 'text-[#5B4A31]/60 hover:text-[#4A5D23] hover:bg-white'
                                                        }`}
                                                >
                                                    {p}
                                                </button>
                                            ))}
                                        </div>
                                    </div>
                                </div>

                                {/* Order ID (optional) */}
                                <div className="mb-10">
                                    <label className="block text-sm font-black text-[#1a2408] uppercase tracking-widest mb-3">Order ID <span className="font-normal text-gray-400 lowercase tracking-normal">(optional)</span></label>
                                    <input
                                        type="text"
                                        value={form.order_id}
                                        onChange={(e) => setForm({ ...form, order_id: e.target.value })}
                                        placeholder="Enter order ID if applicable"
                                        className="w-full px-6 py-5 rounded-2xl bg-gray-50/50 border border-transparent text-lg focus:outline-none focus:ring-2 focus:ring-[#4A5D23]/20 focus:bg-white focus:border-[#4A5D23]/30 transition-all font-medium"
                                    />
                                </div>

                                {/* Description */}
                                <div className="mb-10">
                                    <label className="block text-sm font-black text-[#1a2408] uppercase tracking-widest mb-3">Description</label>
                                    <textarea
                                        value={form.description}
                                        onChange={(e) => setForm({ ...form, description: e.target.value })}
                                        placeholder="Describe the issue in detail..."
                                        rows={8}
                                        maxLength={5000}
                                        className="w-full px-6 py-6 rounded-3xl bg-gray-50/50 border border-transparent text-lg focus:outline-none focus:ring-2 focus:ring-[#4A5D23]/20 focus:bg-white focus:border-[#4A5D23]/30 transition-all font-medium resize-none leading-relaxed"
                                        required
                                    />
                                    <div className="flex justify-between mt-4">
                                        <span className="text-xs font-bold text-[#5B4A31]/40 uppercase tracking-widest flex items-center gap-2">
                                            <Leaf className="h-3 w-3" />
                                            Markdown supported
                                        </span>
                                        <span className="text-xs font-bold text-[#5B4A31]/40 tracking-widest">{form.description.length} / 5000</span>
                                    </div>
                                </div>
                            </div>

                            {/* Footer */}
                            <div className="px-10 md:px-14 py-10 bg-[#4A5D23]/5 border-t border-[#4A5D23]/10 flex flex-col sm:flex-row items-center gap-8 justify-between">
                                <button
                                    type="submit"
                                    disabled={submitting}
                                    className="w-full sm:w-auto inline-flex items-center justify-center gap-3 bg-[#4A5D23] text-white px-12 py-5 rounded-2xl font-black text-lg hover:bg-[#3a491b] transition-all disabled:opacity-50 cursor-pointer shadow-xl hover:-translate-y-1"
                                >
                                    <Send className="h-6 w-6" />
                                    {submitting ? 'Creating...' : 'Submit Support Ticket'}
                                </button>
                                <p className="text-sm font-bold text-[#5B4A31]/60 max-w-xs text-center sm:text-right">
                                    By creating a ticket, you agree to our{' '}
                                    <Link href={`/${country}/help-center`} className="underline hover:text-[#4A5D23]">Support Terms</Link>.
                                </p>
                            </div>
                        </form>
                    </div>
                </>
            ) : (
                /* ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ TICKET LIST VIEW ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ */
                <>
                    {/* Header */}
                    <div className="bg-white/80 backdrop-blur-md border-b border-[#4A5D23]/5 sticky top-0 z-50">
                        <div className="max-w-7xl mx-auto px-6 py-8 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-6">
                            <div className="flex items-center gap-6">
                                <div className="w-14 h-14 rounded-2xl bg-[#4A5D23]/10 flex items-center justify-center shadow-inner">
                                    <Ticket className="h-8 w-8 text-[#4A5D23]" />
                                </div>
                                <div>
                                    <h1 className="text-3xl font-bold text-[#1a2408]">Support Tickets</h1>
                                    <p className="text-base text-[#5B4A31] font-medium mt-1">Manage and track your Vedic support inquiries.</p>
                                </div>
                            </div>
                            <button
                                onClick={() => setView('create')}
                                className="inline-flex items-center gap-3 bg-[#4A5D23] text-white px-8 py-4 rounded-2xl font-bold text-lg hover:bg-[#3a491b] transition-all cursor-pointer shadow-xl hover:-translate-y-1"
                            >
                                <Plus className="h-6 w-6" />
                                New Ticket
                            </button>
                        </div>
                    </div>

                    <div className="max-w-7xl mx-auto px-6 py-12">
                        {/* Stats Cards */}
                        <div className="grid grid-cols-2 lg:grid-cols-4 gap-6 mb-12">
                            {[
                                { label: 'Total Tickets', value: stats.total, icon: Ticket, color: '#4A5D23' },
                                { label: 'Open Tickets', value: stats.open, icon: Clock, color: '#8B4513' },
                                { label: 'In Progress', value: stats.inProgress, icon: MessageSquare, color: '#2E5A50' },
                                { label: 'Resolved', value: stats.resolved, icon: ArrowUpRight, color: '#1a2408' },
                            ].map((stat) => {
                                const Icon = stat.icon;
                                return (
                                    <div key={stat.label} className="bg-white rounded-[32px] border border-[#4A5D23]/5 p-8 transition-all hover:shadow-2xl group">
                                        <div className="w-12 h-12 rounded-xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform" style={{ backgroundColor: stat.color + '15' }}>
                                            <Icon className="h-6 w-6" style={{ color: stat.color }} />
                                        </div>
                                        <p className="text-xs font-black text-gray-400 uppercase tracking-widest mb-1">{stat.label}</p>
                                        <p className="text-4xl font-bold text-[#1a2408]">{stat.value}</p>
                                    </div>
                                );
                            })}
                        </div>

                        {/* Search / Filter bar */}
                        <div className="bg-white rounded-[40px] border border-[#4A5D23]/5 overflow-hidden shadow-2xl">
                            <div className="flex flex-col lg:flex-row items-stretch lg:items-center gap-6 p-8 border-b border-gray-100">
                                <div className="relative flex-1">
                                    <input
                                        type="text"
                                        value={searchQuery}
                                        onChange={(e) => setSearchQuery(e.target.value)}
                                        placeholder="Search by ID, subject, or category..."
                                        className="w-full pl-14 pr-6 py-4 rounded-[20px] bg-gray-50 border-transparent text-lg focus:outline-none focus:ring-2 focus:ring-[#4A5D23]/20 focus:bg-white focus:border-[#4A5D23]/30 transition-all font-medium"
                                    />
                                    <Search className="absolute left-5 top-1/2 -translate-y-1/2 h-6 w-6 text-gray-400" />
                                </div>
                                <div className="flex flex-col sm:flex-row gap-4 items-center">
                                    <select
                                        value={statusFilter}
                                        onChange={(e) => setStatusFilter(e.target.value)}
                                        className="w-full sm:w-auto px-6 py-4 rounded-[20px] bg-gray-50 border-transparent text-base font-bold focus:outline-none focus:ring-2 focus:ring-[#4A5D23]/20 cursor-pointer appearance-none min-w-[180px]"
                                    >
                                        <option value="">All Statuses</option>
                                        <option value="open">Open</option>
                                        <option value="in_progress">In Progress</option>
                                        <option value="resolved">Resolved</option>
                                        <option value="closed">Closed</option>
                                    </select>
                                    <span className="text-sm font-bold text-gray-400 uppercase tracking-widest bg-gray-50 px-5 py-2 rounded-full">
                                        {filteredTickets.length} Results
                                    </span>
                                </div>
                            </div>

                            {/* Ticket list container */}
                            <div className="bg-white">
                                {loading ? (
                                    <div className="p-10 space-y-6">
                                        {[...Array(4)].map((_, i) => (
                                            <div key={i} className="flex items-center gap-6 animate-pulse">
                                                <div className="h-4 bg-gray-200 rounded w-24" />
                                                <div className="h-6 bg-gray-200 rounded w-1/2" />
                                                <div className="h-8 bg-gray-200 rounded-full w-24 ml-auto" />
                                            </div>
                                        ))}
                                    </div>
                                ) : filteredTickets.length === 0 ? (
                                    <div className="text-center py-32">
                                        <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-8">
                                            <MessageSquare className="h-10 w-10 text-gray-200" />
                                        </div>
                                        <h3 className="text-2xl font-bold text-[#1a2408] mb-4">
                                            {tickets.length === 0 ? 'No tickets yet' : 'No matching results'}
                                        </h3>
                                        <p className="text-lg text-[#5B4A31] mb-10 max-w-sm mx-auto font-medium">
                                            {tickets.length === 0 ? 'Start your journey by creating your first support ticket.' : 'Try adjusting your search or filters.'}
                                        </p>
                                        {tickets.length === 0 && (
                                            <button
                                                onClick={() => setView('create')}
                                                className="inline-flex items-center gap-3 bg-[#4A5D23] text-white px-10 py-4 rounded-2xl font-bold text-lg hover:bg-[#3a491b] transition-all cursor-pointer shadow-xl hover:-translate-y-1"
                                            >
                                                <Plus className="h-6 w-6" /> Create Ticket
                                            </button>
                                        )}
                                    </div>
                                ) : (
                                    <div className="divide-y divide-gray-50">
                                        {filteredTickets.map((ticket: Record<string, unknown>) => {
                                            const status = STATUS_CONFIG[ticket.status] || STATUS_CONFIG.open;
                                            const priority = PRIORITY_CONFIG[ticket.priority] || PRIORITY_CONFIG.medium;
                                            return (
                                                <Link
                                                    key={ticket.ticket_id}
                                                    href={`/help-center/support/${ticket.ticket_id}`}
                                                    className="block hover:bg-[#4A5D23]/[0.02] transition-colors group p-8 md:px-10"
                                                >
                                                    <div className="flex flex-col md:flex-row md:items-center gap-6 justify-between">
                                                        <div className="flex-1">
                                                            <div className="flex items-center gap-3 mb-2">
                                                                <span className="text-xs font-black font-mono text-gray-400 uppercase tracking-widest">{ticket.ticket_number}</span>
                                                                <span className="text-[10px] font-black uppercase text-[#4A5D23]/40 tracking-[0.2em]">{ticket.category}</span>
                                                            </div>
                                                            <h3 className="text-xl font-bold text-[#1a2408] group-hover:text-[#4A5D23] transition-colors leading-snug">
                                                                {ticket.subject}
                                                            </h3>
                                                            <div className="flex items-center gap-4 mt-4">
                                                                <span className={`inline-flex items-center gap-2 text-xs font-black uppercase tracking-widest px-4 py-1.5 rounded-full ${status.bg} ${status.text}`}>
                                                                    <span className={`w-2 h-2 rounded-full ${status.dot} shadow-[0_0_8px_rgba(0,0,0,0.1)]`} />
                                                                    {status.label}
                                                                </span>
                                                                <span className={`text-xs font-black uppercase tracking-widest flex items-center gap-1.5 ${priority.color} bg-gray-50 px-3 py-1.5 rounded-full`}>
                                                                    {priority.icon} {priority.label}
                                                                </span>
                                                            </div>
                                                        </div>
                                                        <div className="flex items-center justify-between md:flex-col md:items-end gap-2 shrink-0">
                                                            <div className="flex items-center gap-2 text-[#5B4A31]/60 font-bold text-sm">
                                                                <Clock className="h-4 w-4" />
                                                                {timeAgo(ticket.updated_at)}
                                                            </div>
                                                            <div className="p-3 bg-[#4A5D23]/0 group-hover:bg-[#4A5D23] rounded-xl transition-all group-hover:shadow-lg group-hover:-translate-x-2">
                                                                <MoreHorizontal className="h-6 w-6 text-gray-300 group-hover:text-white" />
                                                            </div>
                                                        </div>
                                                    </div>
                                                </Link>
                                            );
                                        })}
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* Footer */}
                        <div className="mt-20 flex justify-center">
                            <Link
                                href={`/${country}/help-center`}
                                className="inline-flex items-center gap-3 text-lg font-bold text-[#5B4A31] hover:text-[#4A5D23] transition-all group"
                            >
                                <div className="w-12 h-12 rounded-2xl bg-white shadow-xl flex items-center justify-center group-hover:bg-[#4A5D23] group-hover:text-white transition-all">
                                    <ChevronLeft className="h-6 w-6" />
                                </div>
                                Help Center Home
                            </Link>
                        </div>
                    </div>
                </>
            )}
        </div>
    );
}

'use client';
import { authFetch, getLegalDocument, API_URL } from '@/lib/api';

import { useState, useEffect, useRef, useCallback, Suspense } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { useAuth } from '@/context/AuthContext';
import Link from 'next/link';
import toast from 'react-hot-toast';
import {
    ShieldCheck, User, Smartphone, ArrowLeft,
    Eye, EyeOff, Mail, Lock, Check, Leaf
} from 'lucide-react';
import SocialLoginButtons from '@/components/SocialLoginButtons';
import LegalModal from '@/components/ui/LegalModal';
import LegalContentRenderer from '@/components/ui/LegalContentRenderer';
import Select from 'react-select';
import { COUNTRY_CODES } from '@/lib/country-codes';
import { getDefaultCountry } from '@/lib/addressConfig';

// API_URL imported from @/lib/api
const TURNSTILE_SITE_KEY = process.env.NEXT_PUBLIC_TURNSTILE_SITE_KEY ?? 'YOUR_SITE_KEY';
const ADMIN_URL = process.env.NEXT_PUBLIC_ADMIN_URL || 'http://localhost:4000';

type AuthMethod = 'email' | 'phone';

function LoginContent() {
    const router = useRouter();
    const { login, register, isAuthenticated, user, logout, loginFromVerification, isLoading } = useAuth();
    const searchParams = useSearchParams();

    useEffect(() => {
        if (searchParams.get('logout') === 'true') {
            logout(); // local Vedashi logout
            router.replace('/login');
        }
    }, [searchParams, logout, router]);

    const [authMethod, setAuthMethod] = useState<AuthMethod>('email');
    const [isRegister, setIsRegister] = useState(false);

    useEffect(() => {
        if (searchParams.get('mode') === 'register') {
            setIsRegister(true);
        } else if (searchParams.get('mode') === 'login') {
            setIsRegister(false);
        }
    }, [searchParams]);
    const [loading, setLoading] = useState(false);
    const [isRedirecting, setIsRedirecting] = useState(false);
    const [form, setForm] = useState({ name: '', email: '', password: '', confirmPassword: '' });
    const [showPassword, setShowPassword] = useState(false);
    const [showConfirmPassword, setShowConfirmPassword] = useState(false);
    const [agreeTerms, setAgreeTerms] = useState(false);
    const [rememberMe, setRememberMe] = useState(true);
    const [capsLockOn, setCapsLockOn] = useState(false);

    const handleKeyEvent = (e: React.KeyboardEvent<HTMLInputElement>) => {
        if (e.getModifierState) {
            setCapsLockOn(e.getModifierState('CapsLock'));
        }
    };

    const [showTermsModal, setShowTermsModal] = useState(false);
    const [showPrivacyModal, setShowPrivacyModal] = useState(false);
    const [legalContent, setLegalContent] = useState<{ [key: string]: { title: string, content: string } }>({});

    useEffect(() => {
        const fetchLegal = async () => {
            const [terms, privacy] = await Promise.all([
                getLegalDocument('terms-of-service'),
                getLegalDocument('privacy-policy')
            ]);
            setLegalContent({
                'terms-of-service': terms ? { title: terms.title, content: terms.content } : { title: 'Terms of Service', content: '' },
                'privacy-policy': privacy ? { title: privacy.title, content: privacy.content } : { title: 'Privacy Policy', content: '' }
            });
        };
        fetchLegal();
    }, []);

    const defaultDialCode = (() => {
        const match = COUNTRY_CODES.find(c => c.code === getDefaultCountry());
        return match ? match.dial_code : '+91';
    })();
    const [phoneDialCode, setPhoneDialCode] = useState(defaultDialCode);
    const [phoneNumber, setPhoneNumber] = useState('');
    const [otpSent, setOtpSent] = useState(false);
    const [otpCode, setOtpCode] = useState('');
    const [cooldown, setCooldown] = useState(0);
    const [isNewPhoneUser, setIsNewPhoneUser] = useState(false);
    const [phoneName, setPhoneName] = useState('');

    const isAdminRedirecting = useRef(false);

    const [turnstileToken, setTurnstileToken] = useState<string | null>(null);
    const [captchaRequired, setCaptchaRequired] = useState(false);
    const turnstileRef = useRef<HTMLDivElement>(null);
    const widgetIdRef = useRef<string | null>(null);

    const renderTurnstile = useCallback(() => {
        if (!turnstileRef.current || !window.turnstile) return;

        // Cleanup existing widget if any
        if (widgetIdRef.current !== null) {
            try { window.turnstile.remove(widgetIdRef.current); } catch { /* noop */ }
            widgetIdRef.current = null;
        }

        // Double check if the container is already "polluted" by a previous render
        // This can happen in React dev mode with strict mode
        if (turnstileRef.current.innerHTML !== '') {
            turnstileRef.current.innerHTML = '';
        }

        try {
            const id = window.turnstile.render(turnstileRef.current, {
                sitekey: TURNSTILE_SITE_KEY,
                callback: (token: string) => setTurnstileToken(token),
                'expired-callback': () => setTurnstileToken(null),
                'error-callback': () => {
                    console.warn('[Turnstile] Widget error ÔÇö CAPTCHA failed to load');
                    setTurnstileToken(null);
                },
                theme: 'light',
            });
            widgetIdRef.current = id;
        } catch (err) {
            // If it still fails with "already rendered", it's usually benign or handled by the innerHTML check
            console.debug('[Turnstile] Render attempt:', err);
        }
    }, []);

    useEffect(() => {
        let isMounted = true;
        let attempts = 0;
        let intervalId: Record<string, unknown> = null;

        const startRendering = () => {
            if (!isMounted) return;
            setTurnstileToken(null);
            // Defer slightly to ensure DOM is ready (especially for conditional renders)
            setTimeout(() => {
                if (isMounted) renderTurnstile();
            }, 50);
        };

        if (window.turnstile) {
            startRendering();
        } else {
            intervalId = setInterval(() => {
                attempts++;
                if (window.turnstile) {
                    clearInterval(intervalId);
                    startRendering();
                }
                if (attempts > 50) clearInterval(intervalId);
            }, 100);
        }

        return () => {
            isMounted = false;
            if (intervalId) clearInterval(intervalId);
            if (widgetIdRef.current !== null) {
                try { window.turnstile?.remove(widgetIdRef.current); } catch { /* noop */ }
                widgetIdRef.current = null;
            }
        };
    }, [isRegister, captchaRequired, renderTurnstile]);

    useEffect(() => {
        if (cooldown <= 0) return;
        const timer = setTimeout(() => setCooldown(c => c - 1), 1000);
        return () => clearTimeout(timer);
    }, [cooldown]);

    const redirectTo = searchParams.get('redirect') || '/account';

    useEffect(() => {
        if (isAdminRedirecting.current) return;
        if (isAuthenticated && user) {
            // If the user is an admin, don't redirect to customer page ÔÇö wait for admin redirect
            const isAdmin = user.role === 'admin' || user.role === 'Super Admin';
            if (isAdmin) return;
            router.push(redirectTo);
        }
    }, [isAuthenticated, user, router, redirectTo]);

    const isAdminUser = user?.role === 'admin' || user?.role === 'Super Admin';

    if (isLoading || (isAuthenticated && !isAdminRedirecting.current && !isAdminUser) || isRedirecting) {
        return (
            <div className="fixed inset-0 z-50 flex flex-col items-center justify-center bg-[#FFFFFF]/95 backdrop-blur-md">
                <div className="relative flex h-24 w-24 items-center justify-center">
                    <div className="absolute inset-0 rounded-full border-4 border-transparent border-t-[#91C934] border-r-[#91C934]/50 animate-spin" />
                    <div className="flex h-16 w-16 items-center justify-center rounded-full bg-[#91C934]/20 animate-pulse">
                        <Leaf className="h-8 w-8 text-[#91C934]" />
                    </div>
                </div>
                <div className="mt-8 flex flex-col items-center space-y-2">
                    <h2 className="text-2xl font-bold text-black tracking-tight drop-shadow-sm">
                        Securing your session
                    </h2>
                    <p className="text-sm font-medium text-[#91C934] animate-pulse">
                        Please wait while we prepare your account...
                    </p>
                </div>
            </div>
        );
    }

    // ÔöÇÔöÇ Phone OTP handlers ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
    const handleSendPhoneOTP = async () => {
        if (!phoneNumber || phoneNumber.length < 10) {
            toast.error('Please enter a valid phone number');
            return;
        }
        setLoading(true);
        try {
            const res = await authFetch(`${API_URL}/api/auth/phone-login/send-otp`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ phone: `${phoneDialCode}${phoneNumber}` }),
            });
            const json = await res.json();
            if (res.ok && json.success) {
                setOtpSent(true);
                setCooldown(60);
                setIsNewPhoneUser(!!json.data?.is_new_user);
                toast.success('OTP sent to your phone via SMS!');
            } else {
                toast.error(json.message || 'Failed to send OTP');
            }
        } catch {
            toast.error('Network error. Please try again.');
        } finally {
            setLoading(false);
        }
    };

    const handleVerifyPhoneOTP = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!otpCode || otpCode.length < 4) {
            toast.error('Please enter the OTP');
            return;
        }
        setLoading(true);
        try {
            const res = await authFetch(`${API_URL}/api/auth/phone-login/verify-otp`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                credentials: 'include',
                body: JSON.stringify({ phone: `${phoneDialCode}${phoneNumber}`, otp_code: otpCode, full_name: phoneName || undefined }),
            });
            const json = await res.json();
            if (res.ok && json.success && json.data?.customer) {
                toast.success('Welcome back!');
                loginFromVerification(json.data.customer);
                setIsRedirecting(true);
                router.push(redirectTo);
            } else {
                toast.error(json.message || 'Invalid OTP. Please try again.');
            }
        } catch {
            toast.error('Network error. Please try again.');
        } finally {
            setLoading(false);
        }
    };

    // ÔöÇÔöÇ Email/Password Submit ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (isRegister && !agreeTerms) {
            toast.error('You must agree to the Terms of Service and Privacy Policy to continue.');
            return;
        }
        setLoading(true);
        try {
            // Only block submission if CAPTCHA was explicitly required (registration or backend demanded it)
            if ((isRegister || captchaRequired) && !turnstileToken) {
                toast.error('Please complete the CAPTCHA verification.');
                setLoading(false);
                return;
            }
            if (isRegister) {
                if (form.password !== form.confirmPassword) {
                    toast.error('Passwords do not match');
                    setLoading(false);
                    return;
                }
                const result = await register(form.name, form.email, form.password, turnstileToken || undefined);
                if (result?.success) {
                    toast.success('Please verify your email to complete registration.');
                    setIsRedirecting(true);
                    setTimeout(() => {
                        router.push(`/verify-email?registered=true&email=${encodeURIComponent(form.email)}`);
                    }, 1500);
                } else {
                    if (result?.requireCaptcha) {
                        setCaptchaRequired(true);
                    }
                    toast.error(result?.error || 'Something went wrong');
                }
            } else {
                // Login: pass rememberMe and turnstile token (may be null if widget hasn't been solved yet)
                const result = await login(form.email, form.password, rememberMe, turnstileToken || undefined);
                if (result?.success) {
                    const isAdmin = ['admin', 'Super Admin', 'owner'].includes(result.role || '');
                    if (isAdmin) {
                        isAdminRedirecting.current = true;
                        toast.success('Welcome, Admin! Redirecting to dashboard...');
                        let userName = form.email.split('@')[0];
                        let userId = '';
                        try {
                            const stored = localStorage.getItem('vedashi_user');
                            if (stored) {
                                try {
                                    const userData = JSON.parse(stored);
                                    userName = userData.name || userName;
                                    userId = userData.id || '';
                                } catch (e) {
                                    console.error('Failed to parse vedashi_user in login:', e);
                                    localStorage.removeItem('vedashi_user');
                                }
                            }
                        } catch { /* noop */ }
                        // SECURITY: Do not pass raw JWT in URL params ÔÇö use cookie-only auth
                        const params = new URLSearchParams({
                            email: form.email,
                            name: userName,
                            id: userId,
                        });
                        window.location.href = `${ADMIN_URL}/auto-login?${params.toString()}`;
                        return;
                    }
                    toast.success('Welcome back!');
                    setIsRedirecting(true);
                    router.push(redirectTo);
                } else {
                    // Handle security-related responses
                    if (result?.requireCaptcha) {
                        setCaptchaRequired(true);
                    }

                    if (result?.blocked) {
                        const minutes = result.retryAfter ? Math.ceil(result.retryAfter / 60) : 15;
                        toast.error(`Too many failed attempts. Please try again in ${minutes} minute${minutes !== 1 ? 's' : ''}.`);
                    } else if (result?.requireCaptcha && !turnstileToken) {
                        toast.error('Please complete the CAPTCHA verification to continue.');
                        // Re-render Turnstile to ensure widget is visible
                        renderTurnstile();
                    } else {
                        toast.error(result?.error || 'Login failed. Please check your credentials.');
                    }
                }
            }
        } catch (error) {
            console.error('Auth error:', error);
            toast.error('Server error. Please try again.');
        } finally {
            setLoading(false);
            setTurnstileToken(null);
            renderTurnstile();
        }
    };

    const features = [
        'Personalized Ayurvedic Routines',
        'Sustainable Organic Ingredients',
        'Vedic Wellness Community Access',
    ];

    const avatarColors = ['#5a8c5a', '#3d6b3d', '#7aad7a', '#2d4d2d'];

    // ÔöÇÔöÇ Phone OTP View ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
    const PhoneOTPCard = () => (
        <div className="bg-white rounded-2xl shadow-xl p-8 border border-gray-100 w-full">
            {/* Logo */}
            <div className="flex justify-center mb-6">
                <Link href="/">
                    <img src="/vedashi-logo.png" alt="Vedashi" className="h-12 w-auto object-contain" />
                </Link>
            </div>
            <div className="flex flex-col items-center mb-4">
                <div className="w-12 h-12 rounded-2xl bg-[#91C934] flex items-center justify-center mb-4 shadow-lg">
                    <Smartphone className="w-6 h-6 text-white" />
                </div>
                <h2 className="text-2xl font-bold text-[#1a1a1a] tracking-tight">
                    {otpSent ? 'Enter Your Code' : 'Sign in with Phone'}
                </h2>
                <p className="text-sm text-[#6b7b6b] mt-1">
                    {otpSent
                        ? `Code sent to ${phoneDialCode} ${phoneNumber}`
                        : "We'll send a verification code via SMS"}
                </p>
            </div>

            {!otpSent ? (
                <div>
                    <label className="block text-xs font-semibold text-[#3d3d3d] uppercase tracking-wider mb-2">
                        Phone Number
                    </label>
                    <div className="flex gap-2 mb-5">
                        <Select
                            options={COUNTRY_CODES.map(c => ({ value: c.dial_code, label: `${c.flag} ${c.dial_code}`, name: c.name }))}
                            value={{ value: phoneDialCode, label: `${COUNTRY_CODES.find(c => c.dial_code === phoneDialCode)?.flag || ''} ${phoneDialCode}` }}
                            onChange={(opt: Record<string, unknown>) => setPhoneDialCode(opt.value)}
                            className="w-[130px]"
                            styles={{
                                control: (provided: Record<string, unknown>, state: Record<string, unknown>) => ({
                                    ...provided,
                                    borderRadius: '12px',
                                    border: state.isFocused ? '1px solid #91C934' : '1px solid #e5e7eb',
                                    backgroundColor: '#fafafa',
                                    minHeight: '44px',
                                    boxShadow: 'none',
                                    cursor: 'pointer',
                                    '&:hover': {
                                        borderColor: '#91C934',
                                    },
                                }),
                                menu: (provided: Record<string, unknown>) => ({
                                    ...provided,
                                    zIndex: 50,
                                    borderRadius: '12px',
                                    boxShadow: '0 8px 30px rgba(0,0,0,0.12)',
                                    border: '1px solid #d4e4d4',
                                    overflow: 'hidden',
                                }),
                                menuList: (provided: Record<string, unknown>) => ({
                                    ...provided,
                                    padding: '4px',
                                    maxHeight: '200px',
                                }),
                                option: (provided: Record<string, unknown>, state: Record<string, unknown>) => ({
                                    ...provided,
                                    backgroundColor: state.isSelected ? '#1e3d1e' : state.isFocused ? '#f4f9f4' : 'white',
                                    color: state.isSelected ? 'white' : '#1a1a1a',
                                    cursor: 'pointer',
                                    borderRadius: '8px',
                                    fontSize: '13px',
                                    padding: '8px 10px',
                                    margin: '1px 0',
                                }),
                            }}
                            isSearchable
                            filterOption={(option: Record<string, unknown>, input: string) => {
                                if (!input) return true;
                                const q = input.toLowerCase();
                                return option.data.name?.toLowerCase().includes(q) || option.value.includes(q);
                            }}
                            components={{ IndicatorSeparator: () => null }}
                            menuPortalTarget={typeof document !== 'undefined' ? document.body : null}
                            menuPosition="fixed"
                        />
                        <input
                            type="tel"
                            value={phoneNumber}
                            onChange={e => setPhoneNumber(e.target.value.replace(/\D/g, '').slice(0, 10))}
                            className="flex-1 rounded-xl border border-gray-200 bg-gray-50/50 px-4 py-3 text-sm text-[#1a2a1a] placeholder-gray-400 focus:border-[#91C934] focus:ring-2 focus:ring-[#91C934]/10 focus:outline-none transition-all"
                            placeholder="Enter 10-digit mobile number"
                            maxLength={10}
                            autoFocus
                        />
                    </div>
                    <button
                        type="button"
                        onClick={handleSendPhoneOTP}
                        disabled={loading || phoneNumber.length < 10}
                        className="w-full rounded-xl py-3.5 text-sm font-semibold text-white bg-[#91C934] hover:bg-[#82B52F] transition-all disabled:opacity-50 shadow-lg shadow-[#91C934]/20 flex items-center justify-center gap-2 cursor-pointer disabled:cursor-not-allowed"
                    >
                        {loading ? (
                            <><span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" /> Sending...</>
                        ) : 'Send OTP'}
                    </button>
                </div>
            ) : (
                <form onSubmit={handleVerifyPhoneOTP}>
                    {isNewPhoneUser && (
                        <div className="mb-4">
                            <label className="block text-xs font-semibold text-[#3d3d3d] uppercase tracking-wider mb-2">Your Name</label>
                            <input
                                type="text"
                                value={phoneName}
                                onChange={e => setPhoneName(e.target.value)}
                                className="w-full rounded-xl border border-gray-200 bg-gray-50/50 px-4 py-3 text-sm text-[#1a2a1a] placeholder-gray-400 focus:border-[#91C934] focus:outline-none transition-all"
                                placeholder="Enter your name"
                            />
                            <p className="text-xs text-[#6b7b6b] mt-1">We&apos;ll create an account for you</p>
                        </div>
                    )}
                    <label className="block text-xs font-semibold text-[#3d3d3d] uppercase tracking-wider mb-2">Enter OTP</label>
                    <input
                        type="text"
                        inputMode="numeric"
                        value={otpCode}
                        onChange={e => setOtpCode(e.target.value.replace(/\D/g, '').slice(0, 6))}
                        className="w-full rounded-xl border border-gray-200 bg-gray-50/50 px-4 py-3 text-center text-xl tracking-[0.6em] font-mono text-[#1a2a1a] focus:border-[#91C934] focus:ring-2 focus:ring-[#91C934]/10 focus:outline-none transition-all mb-5"
                        placeholder="ÔùÅ ÔùÅ ÔùÅ ÔùÅ ÔùÅ ÔùÅ"
                        maxLength={6}
                        autoFocus
                    />
                    <button
                        type="submit"
                        disabled={loading || otpCode.length < 4}
                        className="w-full rounded-xl py-3.5 text-sm font-semibold text-white bg-[#91C934] hover:bg-[#82B52F] transition-all disabled:opacity-50 shadow-lg shadow-[#91C934]/20 flex items-center justify-center gap-2 cursor-pointer disabled:cursor-not-allowed"
                    >
                        {loading ? (
                            <><span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" /> Verifying...</>
                        ) : 'Verify & Sign In ÔåÆ'}
                    </button>
                    <div className="mt-4 text-center space-y-2">
                        {cooldown > 0 ? (
                            <p className="text-xs text-[#6b7b6b]">Resend OTP in <span className="font-semibold text-[#91C934]">{cooldown}s</span></p>
                        ) : (
                            <button type="button" onClick={handleSendPhoneOTP} disabled={loading} className="text-xs font-semibold text-[#91C934] hover:underline cursor-pointer disabled:cursor-not-allowed">
                                Resend OTP
                            </button>
                        )}
                        <div>
                            <button type="button" onClick={() => { setOtpSent(false); setOtpCode(''); }} className="text-xs text-[#6b7b6b] hover:text-[#91C934] hover:underline cursor-pointer">
                                Change phone number
                            </button>
                        </div>
                    </div>
                </form>
            )}

            <div className="mt-6 pt-5 border-t border-[#e8f0e8] flex flex-col items-center gap-3">
                <button
                    type="button"
                    onClick={() => { setAuthMethod('email'); setOtpSent(false); setOtpCode(''); setCaptchaRequired(false); setTurnstileToken(null); }}
                    className="flex items-center gap-1.5 text-xs font-semibold text-[#91C934] hover:text-[#82B52F] transition-colors cursor-pointer"
                >
                    <ArrowLeft className="w-3.5 h-3.5" />
                    Back to email login
                </button>
                <p className="text-sm text-[#6b7b6b]">
                    Don&apos;t have an account?{' '}
                    <button type="button" onClick={() => { setIsRegister(true); setAuthMethod('email'); setCaptchaRequired(false); setTurnstileToken(null); }}
                        className="font-semibold text-[#91C934] hover:underline cursor-pointer">Create Account</button>
                </p>
                <Link href="/" className="text-sm font-semibold text-[#91C934] hover:underline cursor-pointer">Continue as Guest</Link>
            </div>
        </div>
    );

    const cardTitle = isRegister
        ? 'CREATE ACCOUNT'
        : 'WELCOME BACK!';

    const cardSubtitle = isRegister
        ? 'Join the Vedashi family'
        : 'Sign in to your account';

    return (
        <div className="min-h-screen flex items-center justify-center bg-[#f7f9f7] relative overflow-hidden py-12 px-4 sm:px-6 lg:px-8">
            {/* Background Decoration */}
            <div className="absolute top-0 left-0 w-full h-1 bg-[#8EC433]" />
            <div className="absolute top-[-10%] right-[-10%] w-[40%] h-[40%] bg-[#8EC433]/5 rounded-full blur-3xl" />
            <div className="absolute bottom-[-10%] left-[-10%] w-[40%] h-[40%] bg-[#8EC433]/5 rounded-full blur-3xl" />

            {/* Skip / Back Button */}
            <button
                onClick={() => router.back()}
                className="absolute top-6 right-6 lg:top-10 lg:right-10 flex items-center gap-2 text-[13px] font-bold text-[#91C934] hover:text-[#82B52F] transition-all cursor-pointer group z-20"
            >
                Back
            </button>

            {/* ÔöÇÔöÇ Single Panel: Login Form ÔöÇÔöÇ */}
            <div className="w-full max-w-md flex flex-col relative z-10">
                <div className="w-full">

                    {/* Phone OTP View */}
                    {authMethod === 'phone' && !isRegister ? (
                        <PhoneOTPCard />
                    ) : (
                        /* Main Login / Register Form */
                        <div className="bg-white rounded-2xl shadow-xl p-8 border border-gray-100">
                            {/* Logo */}
                            <div className="flex justify-center mb-6">
                                <Link href="/">
                                    <img src="/vedashi-logo.png" alt="Vedashi" className="h-12 w-auto object-contain" />
                                </Link>
                            </div>

                            {/* Card header */}
                            <div className="flex flex-col items-center mb-4">
                                <h2 className="text-2xl font-bold text-[#1a1a1a] tracking-tight">{cardTitle}</h2>
                                <div className="w-12 h-0.5 bg-gradient-to-r from-transparent via-[#2d5a2d]/40 to-transparent mt-2" />
                                <p className="text-sm text-[#6b7b6b] mt-2">{cardSubtitle}</p>
                            </div>

                            {/* Session expired banner */}
                            {searchParams.get('session_expired') === '1' && (
                                <div id="session-expired-banner" className="mb-4 rounded-xl border border-amber-300 bg-amber-50 px-4 py-3 flex items-start gap-3">
                                    <ShieldCheck className="w-5 h-5 text-amber-600 mt-0.5 flex-shrink-0" />
                                    <div className="flex-1">
                                        <p className="text-sm font-semibold text-amber-800">Session expired</p>
                                        <p className="text-xs text-amber-700 mt-0.5">Your session expired due to inactivity. Please log in again.</p>
                                    </div>
                                </div>
                            )}
                            <form onSubmit={handleSubmit} className="space-y-0 mt-6">

                                {/* Name field (register) */}
                                {isRegister && (
                                    <div className="mb-4">
                                        <label className="block text-xs font-semibold text-[#3d3d3d] uppercase tracking-wider mb-2">
                                            Full Name
                                        </label>
                                        <input
                                            type="text"
                                            value={form.name}
                                            onChange={e => setForm({ ...form, name: e.target.value })}
                                            className="w-full rounded-xl border border-gray-200 bg-gray-50/50 px-4 py-3 text-sm text-[#1a2a1a] placeholder-gray-400 focus:border-[#91C934] focus:ring-2 focus:ring-[#91C934]/10 focus:outline-none transition-all"
                                            placeholder="Your full name"
                                            required
                                        />
                                    </div>
                                )}



                                {/* Email */}
                                <div className="mb-3">
                                    <label className="block text-xs font-semibold text-[#3d3d3d] uppercase tracking-wider mb-2">
                                        Email Address
                                    </label>
                                    <div className="relative">
                                        <Mail className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                                        <input
                                            type="email"
                                            value={form.email}
                                            onChange={e => setForm({ ...form, email: e.target.value })}
                                            className="w-full rounded-xl border border-gray-200 bg-gray-50/50 pl-10 pr-4 py-2.5 text-sm text-[#1a2a1a] placeholder-gray-400 focus:border-[#91C934] focus:ring-2 focus:ring-[#91C934]/10 focus:outline-none transition-all"
                                            placeholder="you@example.com"
                                            required
                                        />
                                    </div>
                                </div>

                                {/* Password */}
                                <div className="mb-3">
                                    <div className="mb-2">
                                        <label className="block text-xs font-semibold text-[#3d3d3d] uppercase tracking-wider">
                                            Password
                                        </label>
                                    </div>
                                    <div className="relative">
                                        <Lock className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                                        <input
                                            type={showPassword ? 'text' : 'password'}
                                            value={form.password}
                                            onChange={e => setForm({ ...form, password: e.target.value })}
                                            onKeyDown={handleKeyEvent}
                                            onKeyUp={handleKeyEvent}
                                            className="w-full rounded-xl border border-gray-200 bg-gray-50/50 pl-10 pr-11 py-2.5 text-sm text-[#1a2a1a] placeholder-gray-400 focus:border-[#91C934] focus:ring-2 focus:ring-[#91C934]/10 focus:outline-none transition-all"
                                            placeholder="ÔÇóÔÇóÔÇóÔÇóÔÇóÔÇóÔÇóÔÇó"
                                            required
                                            minLength={3}
                                        />
                                        <button
                                            type="button"
                                            onClick={() => setShowPassword(!showPassword)}
                                            className="absolute right-3.5 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600 transition-colors cursor-pointer"
                                            tabIndex={-1}
                                        >
                                            {showPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
