                    {/* Bottom contact card inside document */}
                    <div className="mt-16 pt-10 border-t border-border-subtle">
                        <div className="bg-page-bg/50 rounded-2xl p-6 sm:p-8 border border-border-subtle flex flex-col sm:flex-row items-center justify-between gap-6 text-center sm:text-left transition-all hover:border-gold/30 hover:bg-page-bg hover:shadow-lg">
                            <div>
                                <h3 className="font-serif text-xl font-bold text-text-primary mb-2">Have questions about your privacy?</h3>
                                <p className="text-text-secondary text-sm">We are committed to protecting your data. Reach out if you need clarification.</p>
                            </div>
                            <Link href="/contact" className="shrink-0 flex items-center gap-2 bg-emerald-700 text-white px-8 py-3.5 rounded-xl font-bold text-sm transition-all hover:scale-105 hover:bg-emerald-800 shadow-xl shadow-emerald-700/20">
                                <Mail className="h-4 w-4" />
                                Contact Privacy Team
                            </Link>
                        </div>
                    </div>
                </article>

                {/* Back to Home */}
                <div className="mt-12 text-center animate-fade-in-up" style={{ animationDelay: '100ms' }}>
                    <Link href="/" className="inline-flex items-center gap-2 text-text-muted hover:text-gold transition-colors font-medium">
                        <ArrowLeft className="h-4 w-4" />
                        Return to Storefront
                    </Link>
                </div>

            </main>
        </div>
    );
}

import React from 'react';
import Link from 'next/link';
import { getLegalDocument } from '@/lib/api';
import LegalContentRenderer from '@/components/ui/LegalContentRenderer';
import RuLegalPage from '@/components/RuLegalPage';
import { privacyPolicy } from '@/lib/ru-legal-content';
import type { Metadata } from 'next';

type Props = { params: Promise<{ country: string }> };

export async function generateMetadata({ params }: Props): Promise<Metadata> {
    const { country } = await params;
    if (country === 'ru') {
        return {
            title: privacyPolicy.metaTitle,
            description: privacyPolicy.metaDescription,
        };
    }
    return {
        title: 'Privacy Policy | Vedashi',
        description: 'Privacy Policy for Vedashi.',
    };
}

export default async function PrivacyPage({ params }: Props) {
    const { country } = await params;

    // ÔöÇÔöÇÔöÇ Russia: show Russian privacy policy ÔöÇÔöÇÔöÇ
    if (country === 'ru') {
        return <RuLegalPage doc={privacyPolicy} />;
    }

    // ÔöÇÔöÇÔöÇ Default: CMS-driven content ÔöÇÔöÇÔöÇ
    const doc = await getLegalDocument('privacy-policy');

    return (
        <div className="min-h-screen bg-white py-20 px-4">
            <div className="max-w-4xl mx-auto bg-white rounded-3xl shadow-sm border border-gray-100 p-8 md:p-16">
                <div className="mb-12 border-b border-gray-100 pb-8 cursor-pointer">
                    <Link href="/">
                        <img src="/vedashi-logo.png" alt="Vedashi" className="h-16 w-auto object-contain mb-8" />
                    </Link>
                    <h1 className="text-4xl lg:text-5xl font-bold text-gray-900 tracking-tight mb-4">
                        {doc?.title || 'Privacy Policy'}
                    </h1>
                    {doc?.published_at && (
                        <p className="text-gray-500">Last Updated: {new Date(doc.published_at).toLocaleDateString()}</p>
                    )}
                </div>

                <LegalContentRenderer content={doc?.content || ''} />
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect, Suspense, useCallback, useRef, useMemo } from 'react';
import { useSearchParams } from 'next/navigation';
import { getCategories, getFilterOptions, getBestSellers, getNewArrivals, getFilteredProducts, subscribeNewsletter, getFormEnumOptions, getSpecialityEnumOptions } from '@/lib/api';
import { useCurrency } from '@/context/CurrencyContext';
import { FilteredProduct, FilterMeta, Category } from '@/types';
import ProductCard from '@/components/ProductCard';
import { getValidPrices } from '@/utils/discount';
import { SkeletonProductGrid } from '@/components/Skeleton';
import SearchBar from '@/components/SearchBar';
import {
    SlidersHorizontal, X, Leaf, Loader2,
    LayoutGrid, List, ChevronDown
} from 'lucide-react';
import { useFilters } from '@/hooks/useFilters';
import { FILTER_CONFIGS, SORT_OPTIONS } from '@/lib/filterConfig';
import { trackEcommerce, EcommerceItem } from '@/lib/analytics/gtag';

// Filter components
import FilterSection from '@/components/filters/FilterSection';
import CheckboxGroup from '@/components/filters/CheckboxGroup';
import RangeSlider from '@/components/filters/RangeSlider';
import ToggleSwitch from '@/components/filters/ToggleSwitch';
import SortDropdown from '@/components/filters/SortDropdown';
import ActiveFilterChips from '@/components/filters/ActiveFilterChips';
import CountryDropdown from '@/components/filters/CountryDropdown';
import { COUNTRIES } from '@/lib/countries';
import Link from 'next/link';
import { toast } from 'react-hot-toast';

interface FilterAttribute {
    attribute_id: string;
    attribute_name: string;
    attribute_slug: string;
    values: { value_name: string; value_slug: string }[];
}

const ITEMS_PER_PAGE = 24;

function ProductsContent() {
    const { formatPrice, format, resolvePrice, countryCode } = useCurrency();
    const {
        filters,
        activeChips,
        setSearch,
        setCategory,
        setSubCategory,
        setSubSubCategory,
        setBrands,
        setCountry,
        setForm,
        setSpecialities,
        setRatings,
        setPriceRange,

        setInStock,
        setBestSellers,
        setNewArrivals,
        setSort,
        setDiscountMin,
        setAttribute,
        removeFilter,
        clearAll,
    } = useFilters(format);

    const searchParams = useSearchParams();

    const gridRef = useRef<HTMLDivElement>(null);
    // Sentinel ref for IntersectionObserver (infinite scroll trigger)
    const sentinelRef = useRef<HTMLDivElement>(null);

    // Lazy-load / infinite scroll state
    const [products, setProducts] = useState<FilteredProduct[]>([]);
    const [meta, setMeta] = useState<FilterMeta | null>(null);
    // loading = true during the FIRST page fetch (shows full skeleton)
    const [loading, setLoading] = useState(true);
    // loadingMore = true while fetching subsequent pages (shows bottom spinner)
    const [loadingMore, setLoadingMore] = useState(false);
    const [currentPage, setCurrentPage] = useState(1);
    const [hasMore, setHasMore] = useState(true);
    const [mobileOpen, setMobileOpen] = useState(false);
    const [sortOpen, setSortOpen] = useState(false);
    const [activeFilterTab, setActiveFilterTab] = useState('Category');
    const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
    const [isMounted, setIsMounted] = useState(false);

    // Newsletter State
    const [newsletterEmail, setNewsletterEmail] = useState('');
    const [isSubscribing, setIsSubscribing] = useState(false);

    useEffect(() => {
        setIsMounted(true);
        // Ensure page starts at top when hero is removed
        window.scrollTo(0, 0);

        if (typeof window !== 'undefined') {
            const saved = localStorage.getItem('vedashi_view_mode') as 'grid' | 'list';
            if (saved === 'grid' || saved === 'list') {
                setViewMode(saved);
            }
        }
    }, []);

    // Dynamic filter options (loaded from API)
    const [brandOptions, setBrandOptions] = useState<string[]>([]);
    const [countryOptions, setCountryOptions] = useState<string[]>([]);
    const [priceMax, setPriceMax] = useState<number>(5000);
    const [categories, setCategories] = useState<Category[]>([]);
    const [filterAttributes, setFilterAttributes] = useState<FilterAttribute[]>([]);
    const [formFilterOptions, setFormFilterOptions] = useState<string[]>([]);
    const [specialityFilterOptions, setSpecialityFilterOptions] = useState<string[]>([]);

    // Resolve slug values ÔåÆ real display names for category/sub_category chips
    const resolvedChips = useMemo(() =>
        activeChips.map(chip => {
            if (chip.key === 'category') {
                const cat = categories.find(c => c.slug === chip.value);
                return cat ? { ...chip, value: cat.name } : chip;
            }
            if (chip.key === 'sub_category') {
                const subCat = categories
                    .flatMap(c => (c as Record<string, unknown>).children || [])
                    .find((s: Record<string, unknown>) => s.slug === chip.value);
                return subCat ? { ...chip, value: subCat.name } : chip;
            }
            if (chip.key === 'sub_sub_category') {
                const subSubCat = categories
                    .flatMap(c => (c as Record<string, unknown>).children || [])
                    .flatMap((c: Record<string, unknown>) => c.children || [])
                    .find((s: Record<string, unknown>) => s.slug === chip.value);
                return subSubCat ? { ...chip, value: subSubCat.name } : chip;
            }
            return chip;
        }),
        [activeChips, categories]
    );

    const displayCountryOptions = Array.from(
        new Set([...COUNTRIES.map(c => c.name), ...countryOptions])
    ).sort();

    const filtersKey = JSON.stringify(filters);

    useEffect(() => {
        getFilterOptions().then(opts => {
            setBrandOptions(opts.brands);
            setCountryOptions(opts.countries);
            // NOTE: priceMax is now set dynamically by the scope-aware effect below
            if (opts.categories) setCategories(opts.categories);
            if (opts.attributes) setFilterAttributes(opts.attributes);
        });
        // Fetch dynamic form & speciality filter options
        getFormEnumOptions().then(setFormFilterOptions);
        getSpecialityEnumOptions().then(setSpecialityFilterOptions);
    }, []);


    const buildParams = useCallback((page: number) => {
        const params: Record<string, string | number | boolean | string[]> = {
            page,
            limit: ITEMS_PER_PAGE,
        };

        if (filters.search) params.search = filters.search;
        if (filters.sort) params.sort = filters.sort;
        if (filters.category) params.category = filters.category;
        if (filters.sub_category) params.sub_category = filters.sub_category;
        if (filters.sub_sub_category) params.sub_sub_category = filters.sub_sub_category;
        if (filters.brands.length > 0) params.brand = filters.brands.join(',');
        if (filters.priceRange[0] !== 0) params.min_price = filters.priceRange[0];
        if (filters.priceRange[1] !== Infinity) params.max_price = filters.priceRange[1];
        params.storefront_country = countryCode;
        if (filters.country) params.country = filters.country;
        if (filters.form.length > 0) params.form = filters.form.join(',');
        if (filters.specialities.length > 0) params.specialities = filters.specialities.join(',');
        if (filters.ratings.length > 0) {
            const ratingValues = filters.ratings.map(r => parseInt(r)).filter(n => !isNaN(n));
            if (ratingValues.length > 0) params.min_rating = Math.min(...ratingValues);
        }
        if (filters.inStock) params.inStock = true;
        if (filters.bestSellers) params.bestSeller = true;
        if (filters.newArrivals) params.newArrival = true;
        if (filters.discountMin) params.discount_min = filters.discountMin;
        if (Object.keys(filters.attributes).length > 0) params.attributes = JSON.stringify(filters.attributes);
        return params;
    }, [filters, countryCode]);

    // Fetch page ÔÇö appends to list for page > 1, resets for page 1
    const fetchPage = useCallback(async (
        page: number,
        cancelled: { value: boolean },
        isFirstPage: boolean
    ) => {
        if (isFirstPage) {
            setLoading(true);
            setProducts([]);
        } else {
            setLoadingMore(true);
        }

        const params = buildParams(page);
        const result = await getFilteredProducts(params);

        if (!cancelled.value) {

            const incoming = result.data ?? [];
            const totalCount = result.meta?.total_count ?? incoming.length;
            const loadedSoFar = isFirstPage ? incoming.length : (currentPage - 1) * ITEMS_PER_PAGE + incoming.length;

            setProducts(prev => isFirstPage ? incoming : [...prev, ...incoming]);
            setMeta(result.meta);
            setHasMore(incoming.length === ITEMS_PER_PAGE && loadedSoFar < totalCount);

            if (isFirstPage) setLoading(false);
            else setLoadingMore(false);
        }
    }, [buildParams, currentPage]);

    const handleSubscribe = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newsletterEmail || !newsletterEmail.includes('@')) {
            toast.error('Please enter a valid email.');
            return;
        }
        setIsSubscribing(true);
        try {
            const res = await subscribeNewsletter(newsletterEmail);
            if (res.success) {
                toast.success(res.message || 'Successfully subscribed!');
                setNewsletterEmail('');
            } else {
                toast.error(res.message || 'Failed to subscribe.');
            }
        } catch (error) {
            toast.error('An error occurred. Please try again.');
        } finally {
            setIsSubscribing(false);
        }
    };

    // Reset to page 1 whenever filters change
    useEffect(() => {
        window.scrollTo({ top: 0, behavior: 'smooth' });
        const cancelled = { value: false };
        setCurrentPage(1);
        setHasMore(true);
        fetchPage(1, cancelled, true);
        return () => { cancelled.value = true; };
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [filtersKey]);

    // GA4: view_item_list
    // Fire whenever products change, deduplicated by hash
    const viewListHashRef = useRef<string>('');
    useEffect(() => {
        if (products.length > 0) {
            const currentHash = products.map(p => p.product_id).join(',');
            if (viewListHashRef.current === currentHash) return;
            viewListHashRef.current = currentHash;

            const gaItems: EcommerceItem[] = products.slice(0, 24).map((item, index) => {
                const { displayPrice } = getValidPrices(item.price, item.original_price ?? item.price);
                return {
                    item_id: item.product_id,
                    item_name: item.product_name,
                    price: displayPrice,
                    quantity: 1,
                    index: index + 1,
                    item_list_name: 'Shop All Products Grid',
                    item_category: item.category,
                    item_brand: item.brand
                };
            });
            trackEcommerce('view_item_list', {
                currency: 'INR',
                value: gaItems.reduce((acc, curr) => acc + curr.price, 0),
                items: gaItems
            });
        }
    }, [products]);

    // Infinite scroll: load next page when sentinel enters viewport
    useEffect(() => {
        if (!sentinelRef.current) return;
        const observer = new IntersectionObserver(
            (entries) => {
                const entry = entries[0];
                if (entry.isIntersecting && hasMore && !loadingMore && !loading) {
                    const nextPage = currentPage + 1;
                    const cancelled = { value: false };
                    setCurrentPage(nextPage);
                    fetchPage(nextPage, cancelled, false);
                }
            },
            // Trigger 300 px before the sentinel actually enters the screen
            { rootMargin: '300px' }
        );
        observer.observe(sentinelRef.current);
        return () => observer.disconnect();
    }, [hasMore, loadingMore, loading, currentPage, fetchPage]);

    const totalCount = meta?.total_count ?? products.length;
    const loadedCount = products.length;

    useEffect(() => {
        const handleEsc = (e: KeyboardEvent) => {
            if (e.key === 'Escape') setMobileOpen(false);
        };
        document.addEventListener('keydown', handleEsc);
        return () => document.removeEventListener('keydown', handleEsc);
    }, []);

    useEffect(() => {
        document.body.style.overflow = (mobileOpen || sortOpen) ? 'hidden' : '';
        return () => { document.body.style.overflow = ''; };
    }, [mobileOpen, sortOpen]);

    /* ÔöÇÔöÇÔöÇ Search bar state ÔöÇÔöÇÔöÇ */
    // (managed inside SearchBar component; we just call setSearch)

    /* ÔöÇÔöÇÔöÇ Sidebar content (shared between desktop & mobile) ÔöÇÔöÇÔöÇ */
    // Compute the slider max from LOADED products using the exact same
    // resolvePrice(price, country_prices) logic the product cards use.
    // This guarantees the slider matches the highest visible price for ANY country.
    //   ÔÇó US  ÔåÆ resolvePrice uses product_variants.price directly
    //   ÔÇó RU/KR ÔåÆ resolvePrice uses admin-set product_country_prices.price_inr
    const lastKnownMaxRef = useRef<number>(0);

    const localPriceMax = useMemo(() => {
        // We only want to re-evaluate the maximum boundary if the user isn't currently filtering by price.
        // If they are filtering by price, we lock the boundary so they don't get trapped.
        const isPriceFilterActive = filters.priceRange && (filters.priceRange[0] !== 0 || filters.priceRange[1] !== Infinity);

        if (products.length > 0 && !isPriceFilterActive) {
            let max = 0;
            for (const p of products) {
                const localPrice = resolvePrice(p.price, (p as Record<string, unknown>).country_prices);
                if (localPrice > max) max = localPrice;
            }
            if (max > 0) {
                // Round up nicely to give the slider some breathing room
                let rounded = Math.ceil(max / 1000) * 1000;
                if (max <= 100) rounded = Math.ceil(max / 10) * 10;
                else if (max <= 1000) rounded = Math.ceil(max / 100) * 100;
                else if (max <= 5000) rounded = Math.ceil(max / 500) * 500;
                
                lastKnownMaxRef.current = rounded;
                return rounded;
            }
        }
        
        // If filters yield 0 products, OR if a price filter is currently active, 
        // retain the last known max price so the slider doesn't collapse!
        if (lastKnownMaxRef.current > 0) {
            return lastKnownMaxRef.current;
        }

        // Ultimate fallback before any products have ever loaded
        return Math.max(resolvePrice(priceMax), 1);
    }, [products, resolvePrice, priceMax, filters.priceRange]);
    const localStep = useMemo(() => localPriceMax / 100, [localPriceMax]);

    const priceButtons = useMemo(() => {
        const getNiceNumber = (num: number) => {
            if (num <= 10) return Number(num.toFixed(1));
            if (num <= 100) return Math.round(num / 5) * 5;
            if (num <= 1000) return Math.round(num / 50) * 50;
            if (num <= 10000) return Math.round(num / 500) * 500;
            return Math.round(num / 1000) * 1000;
        };
        const q1 = Math.max(getNiceNumber(localPriceMax * 0.25), 0.1);
        const q2 = Math.max(getNiceNumber(localPriceMax * 0.5), q1 + 0.1);
        const q3 = Math.max(getNiceNumber(localPriceMax * 0.75), q2 + 0.1);
        return [
            { label: `Under ${format(q1)}`, range: [0, q1] as [number, number] },
            { label: `${format(q1)} ÔÇô ${format(q2)}`, range: [q1, q2] as [number, number] },
            { label: `${format(q2)} ÔÇô ${format(q3)}`, range: [q2, q3] as [number, number] },
            { label: `${format(q3)}+`, range: [q3, Infinity] as [number, number] },
        ];
    }, [localPriceMax, format]);

    const sidebarContent = (
        <div className="space-y-0">
            {categories.length > 0 && (
                <FilterSection title="Category" defaultOpen={true}>
                    <div className="space-y-3 pt-1">
                        <select
                            className="w-full rounded-xl border border-gray-200 px-3.5 py-2.5 text-[13px] font-medium focus:border-gray-300 focus:outline-none focus:ring-1 focus:ring-gray-300 text-gray-700 bg-white hover:bg-gray-50 transition-colors cursor-pointer"
                            value={filters.category}
                            onChange={(e) => {
                                setCategory(e.target.value);
                            }}
                        >
                            <option value="">All Categories</option>
                            {categories.map((cat: Category) => (
                                <option key={cat.category_id} value={cat.slug}>{cat.name}</option>
                            ))}
                        </select>

                        {/* Subcategory */}
                        {filters.category && (categories.find((c: Record<string, unknown>) => c.slug === filters.category)?.children?.length ?? 0) > 0 && (
                            <select
                                className="w-full rounded-xl border border-gray-200 px-3.5 py-2.5 text-[13px] font-medium focus:border-gray-300 focus:outline-none focus:ring-1 focus:ring-gray-300 text-gray-700 bg-white hover:bg-gray-50 transition-colors cursor-pointer"
                                value={filters.sub_category}
                                onChange={(e) => setSubCategory(e.target.value)}
                            >
                                <option value="">All Subcategories</option>
                                {categories.find((c: Category) => c.slug === filters.category)?.children?.map((sub: Category) => (
                                    <option key={sub.category_id} value={sub.slug}>{sub.name}</option>
                                ))}
                            </select>
                        )}
                        
                        {/* Sub Subcategory */}
                        {filters.sub_category && (categories.find((c: Record<string, unknown>) => c.slug === filters.category)?.children?.find((s: Record<string, unknown>) => s.slug === filters.sub_category)?.children?.length ?? 0) > 0 && (
                            <select
                                className="w-full rounded-xl border border-gray-200 px-3.5 py-2.5 text-[13px] font-medium focus:border-gray-300 focus:outline-none focus:ring-1 focus:ring-gray-300 text-gray-700 bg-white hover:bg-gray-50 transition-colors cursor-pointer"
                                value={filters.sub_sub_category}
                                onChange={(e) => setSubSubCategory(e.target.value)}
                            >
                                <option value="">All Types</option>
                                {categories.find((c: Record<string, unknown>) => c.slug === filters.category)?.children?.find((s: Record<string, unknown>) => s.slug === filters.sub_category)?.children?.map((sub: Category) => (
                                    <option key={sub.category_id} value={sub.slug}>{sub.name}</option>
                                ))}
                            </select>
                        )}
                    </div>
                </FilterSection>
            )}

            {brandOptions.length > 0 && (
                <FilterSection title="Brand" scrollable scrollHeight="220px">
                    <CheckboxGroup
                        options={brandOptions}
                        selected={filters.brands}
                        onChange={setBrands}
                        maxVisible={brandOptions.length}
                        searchable={true}
                        placeholder="Search brands..."
                    />
                </FilterSection>
            )}

            <FilterSection title="Price Range">
                <div className="mb-5 flex flex-wrap gap-2 text-xs">
                    {priceButtons.map(p => (
                        <button
                            key={p.label}
                            onClick={() => setPriceRange(p.range, localPriceMax)}
                            className={`rounded-full border px-3 py-1.5 transition-colors cursor-pointer ${(filters.priceRange[0] === p.range[0] && filters.priceRange[1] === p.range[1])
                                ? 'bg-gray-800 text-white border-gray-800 shadow-sm'
                                : 'border-gray-200 bg-white text-gray-500 hover:border-gray-400 hover:text-gray-800'
                                }`}
                        >
                            {p.label}
                        </button>
                    ))}
                </div>
                <RangeSlider
                    min={0}
                    max={localPriceMax}
                    step={localStep}
                    value={[filters.priceRange[0] ?? 0, filters.priceRange[1] === Infinity ? localPriceMax : filters.priceRange[1]]}
                    onChange={(val) => setPriceRange(val, localPriceMax)}
                    formatLabel={v => format(v)}
                />
            </FilterSection>

            <CountryDropdown
                options={displayCountryOptions}
                selected={filters.country}
                onChange={setCountry}
            />

            <FilterSection title="Rating" defaultOpen={false}>
                <CheckboxGroup
                    options={FILTER_CONFIGS.find(f => f.key === 'rating')?.staticOptions ?? []}
                    selected={filters.ratings}
                    onChange={setRatings}
                />
            </FilterSection>

            <FilterSection title="Discount" defaultOpen={false}>
                <div className="flex flex-col gap-2 text-sm text-gray-700">
                    {[10, 20, 30, 40, 50].map(pct => (
                        <label key={pct} className="flex items-center gap-2 cursor-pointer group">
                            <input
                                type="radio"
                                name="discount"
                                className="h-[15px] w-[15px] rounded-full border-gray-300 text-gray-800 focus:ring-gray-800 cursor-pointer"
                                checked={filters.discountMin === pct}
                                onChange={() => {
                                    if (filters.discountMin === pct) {
                                        removeFilter('discount_min', '');
                                    } else {
                                        setDiscountMin(pct);
                                    }
                                }}
                            />
                            <span className="group-hover:text-gray-900 transition-colors">{pct}% and above</span>
                        </label>
                    ))}
                </div>
            </FilterSection>

            <FilterSection title="Form" defaultOpen={false}>
                <CheckboxGroup
                    options={formFilterOptions}
                    selected={filters.form}
                    onChange={setForm}
                />
            </FilterSection>

            <FilterSection title="Specialities" defaultOpen={false}>
                <CheckboxGroup
                    options={specialityFilterOptions}
                    selected={filters.specialities}
                    onChange={setSpecialities}
                />
            </FilterSection>

            {filterAttributes.map((attr: FilterAttribute) => (
                <FilterSection key={attr.attribute_id} title={attr.attribute_name} defaultOpen={false}>
                    <CheckboxGroup
                        options={attr.values.map((v) => v.value_name)}
                        selected={filters.attributes[attr.attribute_slug] ? filters.attributes[attr.attribute_slug].map(slug => attr.values.find((v) => v.value_slug === slug)?.value_name || slug) : []}
                        onChange={(selectedNames) => {
                            const selectedSlugs = selectedNames.map(name => attr.values.find((v) => v.value_name === name)?.value_slug || name);
                            // @ts-ignore - useFilters hook exports setAttribute
                            setAttribute(attr.attribute_slug, selectedSlugs);
                        }}
                    />
                </FilterSection>
            ))}

            <FilterSection title="Availability">
                <div className="space-y-3">
                    <ToggleSwitch
                        label="In Stock Only"
                        checked={filters.inStock}
                        onChange={setInStock}
                    />
                    <ToggleSwitch
                        label="Best Sellers"
                        checked={filters.bestSellers}
                        onChange={setBestSellers}
                    />
                    <ToggleSwitch
                        label="New Arrivals"
                        checked={filters.newArrivals}
                        onChange={setNewArrivals}
                    />
                </div>
            </FilterSection>

            {activeChips.length > 0 && (
                <div className="pt-4 border-t border-gray-100">
                    <button
                        onClick={clearAll}
                        className="w-full rounded-xl border border-gray-200 py-2.5 text-sm font-semibold text-gray-600 hover:bg-gray-50 hover:text-gray-900 transition-colors cursor-pointer shadow-sm"
                    >
                        Clear All Filters
                    </button>
                </div>
            )}
        </div>
    );

    return (
        <div className="min-h-screen bg-white">


            {/* ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ MAIN CONTENT ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ */}
            <div className="w-full max-w-[1500px] mx-auto px-4 sm:px-6 lg:px-8 py-8 pt-2 sm:pt-4 relative z-10">


                <div className="lg:grid lg:grid-cols-[280px_1fr] lg:gap-10">
                    {/* ÔöÇÔöÇÔöÇ Desktop Sidebar ÔöÇÔöÇÔöÇ */}
                    <aside className="hidden lg:block relative">
                        <div className="sticky top-32 h-[calc(100vh-120px)] rounded-none border border-gray-100 border-l-0 bg-white shadow-[8px_0_30px_rgba(0,0,0,0.03)] overflow-hidden">
                            <div className="h-full overflow-y-auto overscroll-auto px-7 pt-6 no-scrollbar pb-24">
                                <h2 className="text-2xl font-serif font-black text-gray-900 mb-3 tracking-wide pl-1">Filters</h2>
                                {sidebarContent}
                            </div>
                        </div>
                    </aside>

                    {/* ÔöÇÔöÇÔöÇ Mobile Drawer ÔöÇÔöÇÔöÇ */}
                    {mobileOpen && (
                        <div className="fixed top-[100px] bottom-0 left-0 right-0 z-[100] lg:hidden">
                            <div
                                className="absolute inset-0 bg-black/40"
                                onClick={() => setMobileOpen(false)}
                            />
                            <div className="absolute inset-0 w-full bg-white flex flex-col overflow-hidden animate-in fade-in duration-300">
                                <div className="flex-none flex items-center justify-between border-b border-gray-100 px-5 py-4 bg-white relative z-[110]">
                                    <h2 className="text-xl font-bold text-gray-900">Filters</h2>
                                    <div className="flex items-center gap-4">
                                        <button
                                            onClick={clearAll}
                                            className="text-[13px] font-bold text-[#91C934] hover:underline cursor-pointer"
                                        >
                                            Clear All
                                        </button>
                                        <button
                                            onClick={() => setMobileOpen(false)}
                                            className="rounded-full p-1 hover:bg-gray-100 transition-colors cursor-pointer"
                                        >
                                            <X className="h-6 w-6 text-gray-500" />
                                        </button>
                                    </div>
                                </div>

                                <div className="flex-1 flex overflow-hidden">
                                    {/* Left Sidebar: Headings */}
                                    <div className="w-[120px] bg-gray-50 border-r border-gray-100 overflow-y-auto no-scrollbar">
                                        {[
                                            'Category', 'Brand', 'Price Range', 'Country', 'Rating', 'Discount', 'Form', 'Specialities',
                                            ...filterAttributes.map(a => a.attribute_name),
                                            'Availability'
                                        ].map(tab => (
                                            <button
                                                key={tab}
                                                onClick={() => setActiveFilterTab(tab)}
                                                className={`w-full px-4 py-4 text-left text-[13px] font-bold transition-all border-l-4 ${activeFilterTab === tab
                                                    ? 'bg-white text-[#91C934] border-[#91C934]'
                                                    : 'text-gray-500 border-transparent hover:bg-gray-100'
                                                    }`}
                                            >
                                                {tab}
                                            </button>
                                        ))}
                                    </div>

                                    {/* Right Content: Filter Options */}
                                    <div className="flex-1 overflow-y-auto px-5 py-4 no-scrollbar bg-white">
                                        {activeFilterTab === 'Category' && (
                                            <div className="space-y-4">
                                                <h3 className="text-sm font-bold text-gray-900">Category</h3>
                                                <div className="space-y-3">
                                                    <select
                                                        className="w-full rounded-xl border border-gray-200 px-3.5 py-2.5 text-[13px] font-medium focus:border-gray-300 focus:outline-none focus:ring-1 focus:ring-gray-300 text-gray-700 bg-white hover:bg-gray-50 transition-colors cursor-pointer"
                                                        value={filters.category}
                                                        onChange={(e) => setCategory(e.target.value)}
                                                    >
                                                        <option value="">All Categories</option>
                                                        {categories.map((cat: Category) => (
                                                            <option key={cat.category_id} value={cat.slug}>{cat.name}</option>
                                                        ))}
                                                    </select>
                                                    {filters.category && (categories.find((c: Record<string, unknown>) => c.slug === filters.category)?.children?.length ?? 0) > 0 && (
                                                        <select
                                                            className="w-full rounded-xl border border-gray-200 px-3.5 py-2.5 text-[13px] font-medium focus:border-gray-300 focus:outline-none focus:ring-1 focus:ring-gray-300 text-gray-700 bg-white hover:bg-gray-50 transition-colors cursor-pointer"
                                                            value={filters.sub_category}
                                                            onChange={(e) => setSubCategory(e.target.value)}
                                                        >
                                                            <option value="">All Subcategories</option>
                                                            {categories.find((c: Category) => c.slug === filters.category)?.children?.map((sub: Category) => (
                                                                <option key={sub.category_id} value={sub.slug}>{sub.name}</option>
                                                            ))}
                                                        </select>
                                                    )}
                                                    {filters.sub_category && (categories.find((c: Record<string, unknown>) => c.slug === filters.category)?.children?.find((s: Record<string, unknown>) => s.slug === filters.sub_category)?.children?.length ?? 0) > 0 && (
                                                        <select
                                                            className="w-full rounded-xl border border-gray-200 px-3.5 py-2.5 text-[13px] font-medium focus:border-gray-300 focus:outline-none focus:ring-1 focus:ring-gray-300 text-gray-700 bg-white hover:bg-gray-50 transition-colors cursor-pointer"
                                                            value={filters.sub_sub_category}
                                                            onChange={(e) => setSubSubCategory(e.target.value)}
                                                        >
                                                            <option value="">All Types</option>
                                                            {categories.find((c: Record<string, unknown>) => c.slug === filters.category)?.children?.find((s: Record<string, unknown>) => s.slug === filters.sub_category)?.children?.map((sub: Category) => (
                                                                <option key={sub.category_id} value={sub.slug}>{sub.name}</option>
                                                            ))}
                                                        </select>
                                                    )}
                                                </div>
                                            </div>
                                        )}
                                        {activeFilterTab === 'Brand' && (
                                            <div className="space-y-4">
                                                <h3 className="text-sm font-bold text-gray-900">Brand</h3>
                                                <CheckboxGroup
                                                    options={brandOptions}
                                                    selected={filters.brands}
                                                    onChange={setBrands}
                                                    maxVisible={brandOptions.length}
                                                    searchable={true}
                                                    placeholder="Search brands..."
                                                />
                                            </div>
                                        )}
                                        {activeFilterTab === 'Price Range' && (
                                            <div className="space-y-6">
                                                <h3 className="text-sm font-bold text-gray-900">Price Range</h3>
                                                <div className="flex flex-wrap gap-2 text-xs">
                                                    {priceButtons.map(p => (
                                                        <button
                                                            key={p.label}
                                                            onClick={() => setPriceRange(p.range, localPriceMax)}
                                                            className={`rounded-full border px-3 py-1.5 transition-colors cursor-pointer ${(filters.priceRange[0] === p.range[0] && filters.priceRange[1] === p.range[1])
                                                                ? 'bg-gray-800 text-white border-gray-800 shadow-sm'
                                                                : 'border-gray-200 bg-white text-gray-500 hover:border-gray-400 hover:text-gray-800'
                                                                }`}
                                                        >
                                                            {p.label}
                                                        </button>
                                                    ))}
                                                </div>
                                                <RangeSlider
                                                    min={0}
                                                    max={localPriceMax}
                                                    step={localStep}
                                                    value={[filters.priceRange[0] ?? 0, filters.priceRange[1] === Infinity ? localPriceMax : filters.priceRange[1]]}
                                                    onChange={(val) => setPriceRange(val, localPriceMax)}
                                                    formatLabel={v => format(v)}
                                                />
                                            </div>
                                        )}
                                        {activeFilterTab === 'Country' && (
                                            <div className="space-y-4">
                                                <h3 className="text-sm font-bold text-gray-900">Country</h3>
                                                <div className="space-y-3">
                                                    {displayCountryOptions.map((opt) => (
                                                        <label key={opt} className="flex items-center gap-3 cursor-pointer group">
                                                            <input
                                                                type="radio"
                                                                name="mobile-country"
                                                                className="h-4 w-4 rounded-full border-gray-300 text-[#3d5c3a] focus:ring-[#3d5c3a] cursor-pointer"
                                                                checked={filters.country === opt}
                                                                onChange={() => setCountry(opt)}
                                                            />
                                                            <span className="text-[13px] text-gray-700 group-hover:text-gray-900 transition-colors">{opt}</span>
                                                        </label>
                                                    ))}
                                                </div>
                                            </div>
                                        )}
                                        {activeFilterTab === 'Rating' && (
                                            <div className="space-y-4">
                                                <h3 className="text-sm font-bold text-gray-900">Rating</h3>
                                                <CheckboxGroup
                                                    options={FILTER_CONFIGS.find(f => f.key === 'rating')?.staticOptions ?? []}
                                                    selected={filters.ratings}
                                                    onChange={setRatings}
                                                />
                                            </div>
                                        )}
                                        {activeFilterTab === 'Discount' && (
                                            <div className="space-y-4">
                                                <h3 className="text-sm font-bold text-gray-900">Discount</h3>
                                                <div className="flex flex-col gap-3 text-[13px] text-gray-700">
                                                    {[10, 20, 30, 40, 50].map(pct => (
                                                        <label key={pct} className="flex items-center gap-3 cursor-pointer group">
                                                            <input
                                                                type="radio"
                                                                name="mobile-discount"
                                                                className="h-4 w-4 rounded-full border-gray-300 text-[#3d5c3a] focus:ring-[#3d5c3a] cursor-pointer"
                                                                checked={filters.discountMin === pct}
                                                                onChange={() => setDiscountMin(pct)}
                                                            />
                                                            <span className="group-hover:text-gray-900 transition-colors">{pct}% and above</span>
                                                        </label>
                                                    ))}
                                                </div>
                                            </div>
                                        )}
                                        {activeFilterTab === 'Form' && (
                                            <div className="space-y-4">
                                                <h3 className="text-sm font-bold text-gray-900">Form</h3>
                                                <CheckboxGroup
                                                    options={formFilterOptions}
                                                    selected={filters.form}
                                                    onChange={setForm}
                                                />
                                            </div>
                                        )}
                                        {activeFilterTab === 'Specialities' && (
                                            <div className="space-y-4">
                                                <h3 className="text-sm font-bold text-gray-900">Specialities</h3>
                                                <CheckboxGroup
                                                    options={specialityFilterOptions}
                                                    selected={filters.specialities}
                                                    onChange={setSpecialities}
                                                />
                                            </div>
                                        )}
                                        {filterAttributes.map((attr) => activeFilterTab === attr.attribute_name && (
                                            <div key={attr.attribute_id} className="space-y-4">
                                                <h3 className="text-sm font-bold text-gray-900">{attr.attribute_name}</h3>
                                                <CheckboxGroup
                                                    options={attr.values.map((v) => v.value_name)}
                                                    selected={filters.attributes[attr.attribute_slug] ? filters.attributes[attr.attribute_slug].map(slug => attr.values.find((v) => v.value_slug === slug)?.value_name || slug) : []}
                                                    onChange={(selectedNames) => {
                                                        const selectedSlugs = selectedNames.map(name => attr.values.find((v) => v.value_name === name)?.value_slug || name);
                                                        // @ts-ignore
                                                        setAttribute(attr.attribute_slug, selectedSlugs);
                                                    }}
                                                />
                                            </div>
                                        ))}
                                        {activeFilterTab === 'Availability' && (
                                            <div className="space-y-4">
                                                <h3 className="text-sm font-bold text-gray-900">Availability</h3>
                                                <div className="space-y-4">
                                                    <ToggleSwitch
                                                        label="In Stock Only"
                                                        checked={filters.inStock}
                                                        onChange={setInStock}
                                                    />
                                                    <ToggleSwitch
                                                        label="Best Sellers"
                                                        checked={filters.bestSellers}
                                                        onChange={setBestSellers}
                                                    />
                                                    <ToggleSwitch
                                                        label="New Arrivals"
                                                        checked={filters.newArrivals}
                                                        onChange={setNewArrivals}
                                                    />
                                                </div>
                                            </div>
                                        )}
                                    </div>
                                </div>

                                {/* Bottom Buttons */}
                                <div className="flex-none border-t border-gray-100 flex bg-white pb-safe">
                                    <button
                                        onClick={() => setMobileOpen(false)}
                                        className="flex-1 h-14 flex items-center justify-center text-[14px] font-bold text-gray-800 border-r border-gray-100 active:bg-gray-50 transition-colors"
                                    >
                                        Cancel
                                    </button>
                                    <button
                                        onClick={() => setMobileOpen(false)}
                                        className="flex-1 h-14 flex items-center justify-center text-[14px] font-bold text-[#91C934] active:bg-gray-50 transition-colors"
                                    >
                                        Apply Filters
                                    </button>
                                </div>
                            </div>
                        </div>
                    )}

                    {/* ÔöÇÔöÇÔöÇ Product Grid ÔöÇÔöÇÔöÇ */}
                    <div className="min-w-0">
                        {/* Sort bar + count (Desktop only) */}
                        <div className="mb-4 hidden lg:flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
                            <p className="text-sm text-gray-500 flex items-center gap-2">
                                <span className={`transition-opacity ${loading ? 'opacity-50' : 'opacity-100'}`}>
                                    {totalCount === 0 ? 'No products' : (
                                        <>Showing <span className="font-semibold text-gray-900">{loadedCount}</span> of{' '}
                                            <span className="font-semibold text-gray-900">{totalCount}</span> products</>
                                    )}
                                </span>
                                {(loading || loadingMore) && <Loader2 className="h-4 w-4 animate-spin text-[#3d5c3a]" />}
                            </p>
                            <div className="flex items-center gap-3">
                                <div className="flex items-center rounded-lg border border-gray-200 bg-white shadow-sm overflow-hidden">
                                    <button
                                        onClick={() => { setViewMode('grid'); localStorage.setItem('vedashi_view_mode', 'grid'); }}
                                        className={`p-2 transition-colors cursor-pointer ${viewMode === 'grid' ? 'bg-[#91C934] text-white' : 'text-gray-400 hover:text-gray-600'}`}
                                        aria-label="Grid view"
                                        title="Grid view"
                                    >
                                        <LayoutGrid className="h-4 w-4" />
                                    </button>
                                    <button
                                        onClick={() => { setViewMode('list'); localStorage.setItem('vedashi_view_mode', 'list'); }}
                                        className={`p-2 transition-colors cursor-pointer ${viewMode === 'list' ? 'bg-[#91C934] text-white' : 'text-gray-400 hover:text-gray-600'}`}
                                        aria-label="List view"
                                        title="List view"
                                    >
                                        <List className="h-4 w-4" />
                                    </button>
                                </div>
                                <SortDropdown
                                    value={filters.sort || SORT_OPTIONS[0].value}
                                    onChange={setSort}
                                    options={SORT_OPTIONS}
                                />
                            </div>
                        </div>

                        {/* Mobile Count */}
                        <div className="lg:hidden mb-4 flex items-center justify-between">
                            <p className="text-[13px] text-gray-500 flex items-center gap-2">
                                <span className={`transition-opacity ${loading ? 'opacity-50' : 'opacity-100'}`}>
                                    {totalCount === 0 ? 'No products' : (
                                        <>Showing <span className="font-bold text-gray-900">{loadedCount}</span> of <span className="font-bold text-gray-900">{totalCount}</span></>
                                    )}
                                </span>
                                {(loading || loadingMore) && <Loader2 className="h-3.5 w-3.5 animate-spin text-[#3d5c3a]" />}
                            </p>
                        </div>

                        <ActiveFilterChips
                            chips={resolvedChips}
                            onRemove={removeFilter}
                            onClearAll={clearAll}
                        />

                        {loading ? (
                            <SkeletonProductGrid count={8} />
                        ) : products.length > 0 ? (
                            <>
                                <div ref={gridRef} className={viewMode === 'grid' ? 'grid grid-cols-2 gap-3 sm:gap-5 lg:grid-cols-3 xl:grid-cols-4' : 'flex flex-col gap-4'}>
                                    {products.map((product, i) => (
                                        <div
                                            key={`${product.product_id}-${i}`}
                                            className="animate-fade-in-up"
                                            style={{ animationDelay: `${Math.min(i % 24, 7) * 50}ms`, animationFillMode: 'both' }}
                                        >
                                            <ProductCard
                                                product={product}
                                                priority={i < 4}
                                                layout={viewMode}
                                                listName="Shop All Products Grid"
                                                listIndex={i + 1}
                                            />
                                        </div>
                                    ))}
                                </div>

                                {/* ÔöÇÔöÇ Infinite Scroll Sentinel + Loading State ÔöÇÔöÇ */}
                                <div ref={sentinelRef} className="mt-10 flex flex-col items-center gap-3 pb-6">
                                    {loadingMore && (
                                        <div className="flex flex-col items-center gap-2">
                                            <Loader2 className="h-6 w-6 animate-spin text-[#3d5c3a]" />
                                            <p className="text-xs text-gray-400 font-medium">Loading more productsÔÇª</p>
                                        </div>
                                    )}
                                    {!hasMore && !loadingMore && (
                                        <div className="flex flex-col items-center gap-1.5">
                                            <div className="flex items-center gap-3 w-full max-w-xs">
                                                <div className="flex-1 h-px bg-gray-100" />
                                                <span className="text-[11px] font-semibold text-gray-300 uppercase tracking-widest whitespace-nowrap">All caught up</span>
                                                <div className="flex-1 h-px bg-gray-100" />
                                            </div>
                                            <p className="text-xs text-gray-400">
                                                Showing all <span className="font-bold text-gray-600">{loadedCount}</span> products
                                            </p>
                                        </div>
                                    )}
                                </div>
                            </>
                        ) : (
                            <div className="rounded-2xl border border-gray-100 bg-white py-20 text-center shadow-sm">
                                <div className="h-16 w-16 mx-auto mb-4 rounded-full bg-gray-100 flex items-center justify-center">
                                    <span className="text-3xl">­ƒî┐</span>
                                </div>
                                <p className="text-xl text-gray-700">No products found</p>
                                <p className="mt-2 text-sm text-gray-400">Try adjusting your filters or search
                                    {filters.search && <> for &ldquo;<strong>{filters.search}</strong>&rdquo;</>}
                                </p>
                                {activeChips.length > 0 && (
                                    <button
                                        onClick={clearAll}
                                        className="mt-5 rounded-xl bg-[#91C934] px-6 py-2.5 text-sm font-bold text-white hover:bg-[#2d4a2a] transition-colors cursor-pointer"
                                    >
                                        Clear All Filters
                                    </button>
                                )}
                            </div>
                        )}
                    </div>
                </div>
            </div>



            {/* ÔöÇÔöÇ Mobile Bottom Sticky Bar ÔöÇÔöÇ */}
            {!mobileOpen && (
                <div className="fixed bottom-0 left-0 right-0 z-50 lg:hidden bg-white border-t border-gray-200 shadow-[0_-10px_30px_rgba(0,0,0,0.08)] pb-safe animate-in fade-in slide-in-from-bottom-5 duration-300">
                    <div className="flex h-14">
                        <button
                            onClick={() => setMobileOpen(true)}
                            className="flex-1 flex items-center justify-center gap-2.5 text-[14px] font-bold text-gray-800 border-r border-gray-100 active:bg-gray-50 transition-colors"
                        >
                            <SlidersHorizontal className="h-4 w-4 text-[#91C934]" />
                            Filters
                            {activeChips.length > 0 && (
                                <span className="flex h-5 w-5 items-center justify-center rounded-full bg-[#91C934] text-[10px] font-black text-white shadow-sm">
                                    {activeChips.length}
                                </span>
                            )}
                        </button>
                        <button
                            onClick={() => setSortOpen(true)}
                            className="flex-1 flex items-center justify-center gap-2.5 text-[14px] font-bold text-gray-800 active:bg-gray-50 transition-colors"
                        >
                            <div className="flex flex-col items-start leading-none">
                                <span className="text-[10px] text-gray-400 uppercase tracking-widest mb-0.5">Sort by</span>
                                <span className="truncate max-w-[120px]">
                                    {SORT_OPTIONS.find(o => o.value === (filters.sort || SORT_OPTIONS[0].value))?.label}
                                </span>
                            </div>
                            <ChevronDown className="h-3.5 w-3.5 text-gray-400" />
                        </button>
                    </div>
                </div>
            )}

            {/* ÔöÇÔöÇ Mobile Sort Bottom Sheet ÔöÇÔöÇ */}
            {sortOpen && (
                <div className="fixed inset-0 z-[1000] lg:hidden">
                    <div
                        className="absolute inset-0 bg-black/60 animate-in fade-in duration-300"
                        onClick={() => setSortOpen(false)}
                    />
                    <div className="absolute bottom-0 left-0 right-0 bg-white overflow-hidden animate-in slide-in-from-bottom duration-500 ease-out shadow-2xl">
                        <div className="w-12 h-1.5 bg-gray-200 rounded-full mx-auto mt-3 mb-1" />
                        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-50">
                            <h3 className="text-xl font-black text-gray-900 tracking-tight">Sort By</h3>
                            <button
                                onClick={() => setSortOpen(false)}
                                className="p-2 hover:bg-gray-100 rounded-full transition-colors"
                            >
                                <X className="h-5 w-5 text-gray-500" />
                            </button>
                        </div>
                        <div className="px-3 py-4 space-y-1">
                            {SORT_OPTIONS.map((option) => {
                                const isSelected = (filters.sort || SORT_OPTIONS[0].value) === option.value;
                                return (
                                    <button
                                        key={option.value}
                                        onClick={() => {
                                            setSort(option.value);
                                            setSortOpen(false);
                                        }}
                                        className={`w-full flex items-center justify-between px-5 py-4 rounded-2xl text-[15px] font-bold transition-all ${isSelected
                                            ? 'bg-[#91C934]/5 text-[#91C934]'
                                            : 'text-gray-600 hover:bg-gray-50'
                                            }`}
                                    >
                                        {option.label}
                                        {isSelected && (
                                            <div className="h-5 w-5 rounded-full bg-[#91C934] flex items-center justify-center shadow-md">
                                                <div className="h-2 w-2 rounded-full bg-white" />
                                            </div>
                                        )}
                                    </button>
                                );
                            })}
                        </div>
                        <div className="h-10 bg-white" /> {/* Extra padding for home indicator */}
                    </div>
                </div>
            )}

        </div>
    );
}

export default function ProductsClientPage() {
    return (
        <Suspense fallback={<div className="min-h-screen bg-white p-8 pt-24"><SkeletonProductGrid count={8} /></div>}>
            <ProductsContent />
        </Suspense>
    );
}

'use client';

import { useState, useEffect, use, useCallback, Suspense } from 'react';
import Link from 'next/link';
import dynamic from 'next/dynamic';
import { getProduct, getProductDetails, getBestSellers, trackProductView, requestRestockNotification, getRatingSummary } from '@/lib/api';
import { trackEcommerce } from '@/lib/analytics/gtag';

import { useCurrency } from '@/context/CurrencyContext';
import { Product, ProductWithDetails, ProductVariant } from '@/types';
import { useCart } from '@/context/CartContext';
import { useAuth } from '@/context/AuthContext';
import { useWishlist } from '@/context/WishlistContext';
import ProductCard from '@/components/ProductCard';
import { SkeletonLine, SkeletonReviewSection, SkeletonProductRow } from '@/components/Skeleton';
import { Heart, ShoppingCart, Minus, Plus, Star, Truck, RotateCcw, ChevronRight, AlertTriangle, Sparkles, Info, Package, Award, BadgeCheck, Clock, Globe, Trash2, Share2, Tag } from 'lucide-react';
import ProductImageGallery from '@/components/gallery/ProductImageGallery';
import LazySection from '@/components/lazy/LazySection';
import toast from 'react-hot-toast';
import { getValidPrices } from '@/utils/discount';
import { useRouter, useSearchParams, notFound } from 'next/navigation';
import { CheckCircle2, FlaskConical, Leaf as LeafIcon, ShieldCheck } from 'lucide-react';
import { useRecentlyViewed } from '@/hooks/useRecentlyViewed';
import { buildPath, getCountryFromPathname } from '@/lib/currency';


// Dynamic imports for below-fold sections
const ReviewSection = dynamic(
    () => import('@/components/reviews/ReviewSection'),
    { ssr: false }
);

const ProductReel = dynamic(
    () => import('@/components/ProductReel'),
    { ssr: false }
);

const RecentlyViewedProducts = dynamic(
    () => import('@/components/RecentlyViewedProducts'),
    { ssr: false }
);

const SimilarProducts = dynamic(
    () => import('@/components/SimilarProducts'),
    { ssr: false }
);



interface Props {
    id: string;
    country: string;
    initialProduct: ProductWithDetails | null;
}



/** Lazy-loaded best sellers section with deferred API call */
function LazyBestSellers({ title, icon }: {
    title: string;
    icon?: React.ReactNode;
}) {
    const [products, setProducts] = useState<Product[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        let cancelled = false;
        getBestSellers({ limit: 12 }).then(res => {
            if (!cancelled) {
                if (res && res.data) {
                    setProducts(res.data as Product[]);
                } else if (Array.isArray(res)) {
                    setProducts(res as Product[]);
                }
                setLoading(false);
            }
        }).catch(() => {
            if (!cancelled) setLoading(false);
        });
        return () => { cancelled = true; };
    }, []);

    return (
        <ProductReel
            title={title}
            products={products}
            loading={loading}
        />
    );
}


function ProductDetailContent({ id, country, initialProduct }: Props) {
    const { formatPrice, formatMrp } = useCurrency();
    const [product, setProduct] = useState<ProductWithDetails | null>(initialProduct);
    const [loading, setLoading] = useState(!initialProduct);
    const [pageQuantity, setPageQuantity] = useState(1);

    // Ô£à Variant state
    const [variants, setVariants] = useState<ProductVariant[]>([]);
    const [selectedVariant, setSelectedVariant] = useState<ProductVariant | null>(null);
    const [selectedWeight, setSelectedWeight] = useState<number | null>(null);
    const [selectedStrength, setSelectedStrength] = useState<string | null>(null);
    const [selectedVolume, setSelectedVolume] = useState<number | null>(null);
    const [selectedCount, setSelectedCount] = useState<string | null>(null);
    const [selectedFlavor, setSelectedFlavor] = useState<string | null>(null);
    const [selectedPack, setSelectedPack] = useState<number | null>(null);
    const [isDescriptionExpanded, setIsDescriptionExpanded] = useState(false);
    const [ratingSummary, setRatingSummary] = useState<Record<string, unknown>>(null);
    const [activeInfoTab, setActiveInfoTab] = useState<'description' | 'howToUse' | 'specifications'>('description');
    const router = useRouter();
    const searchParams = useSearchParams();
    const { isAuthenticated } = useAuth();

    const { addItem, items, updateQuantity, removeItem, loading: cartLoading } = useCart();
    const { isInWishlist, toggleItem } = useWishlist();
    const { addProduct: trackRecentlyViewed } = useRecentlyViewed();

    // Restock Notification
    const [restockEmail, setRestockEmail] = useState('');
    const [isRestockNotifying, setIsRestockNotifying] = useState(false);

    const handleRestockNotify = async () => {
        if (!restockEmail || !/\S+@\S+\.\S+/.test(restockEmail)) {
            toast.error('Please enter a valid email address');
            return;
        }
        setIsRestockNotifying(true);
        try {
            const res = await requestRestockNotification(
                product?.product_id as string,
                restockEmail,
                selectedVariant?.variant_id
            );

            if (res.success) {
                toast.success('You will be notified when this is back in stock!');
                setRestockEmail('');
            } else {
                toast.error(res.message || 'Failed to set notification.');
            }
        } catch {
            toast.error('Failed to set notification. Please try again.');
        } finally {
            setIsRestockNotifying(false);
        }
    };

    const handleToggleWishlist = (e: React.MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();
        if (product) {
            toggleItem(product);
        }
    };

    const handleShare = () => {
        const shareData = {
            title: product?.product_name || 'Vedashi Wellness',
            text: `Check out ${product?.product_name} on Vedashi ÔÇö Premium Ayurvedic Wellness.`,
            url: window.location.href,
        };

        if (navigator.share && navigator.canShare && navigator.canShare(shareData)) {
            navigator.share(shareData).catch((err) => {
                console.log('Share failed:', err);
            });
        } else {
            navigator.clipboard.writeText(window.location.href);
            toast.success('Link copied to clipboard!');
        }
    };

    // Only fetch product details and variants (above-fold data)
    // Related products and reviews are deferred to their lazy sections
    useEffect(() => {
        window.scrollTo(0, 0);
        // Also scroll on next tick just in case
        setTimeout(() => window.scrollTo(0, 0), 0);
        const load = async () => {
            if (!initialProduct) {
                setLoading(true);

                let data = await getProductDetails(id);
                if (!data) {
                    const simple = await getProduct(id);
                    if (simple) data = simple as ProductWithDetails;
                }

                setProduct(data);
                initializeVariants(data);
            } else {
                initializeVariants(initialProduct);
            }
        };

        const initializeVariants = (data: Record<string, unknown>) => {

            // Ô£à store variants with size/pack defaults
            if (data?.variants?.length) {
                const vs = data.variants.map((v: Record<string, unknown>) => {
                    let opts: Record<string, unknown> = {};
                    if (typeof v.options === 'string') {
                        try { opts = JSON.parse(v.options); } catch (e) { }
                    } else if (typeof v.options === 'object' && v.options !== null) {
                        opts = v.options;
                    }
                    return {
                        ...v,
                        options: opts,
                        weight_g: v.weight_g ?? (opts['Weight'] ? parseFloat(opts['Weight']) : null),
                        volume_ml: v.volume_ml ?? (opts['Volume'] ? parseFloat(opts['Volume']) : null),
                        units_count: v.units_count ?? (opts['Count'] ? parseInt(opts['Count'], 10) : null),
                        strength: v.strength ?? (opts['Strength'] || null),
                        flavor: v.flavor ?? (opts['Flavor'] || null),
                        pack_quantity: v.pack_quantity ?? (opts['Pack'] && String(opts['Pack']).toLowerCase() !== 'single' ? parseInt(opts['Pack'].replace(/\D/g, '') || '1', 10) : 1),
                    };
                });
                setVariants(vs);

                const requestedVariantId = searchParams.get('variant');
                const matchedVariant = requestedVariantId
                    ? vs.find((v: ProductVariant) => v.variant_id === requestedVariantId)
                    : null;

                // Pick requested variant, or default (is_default=true), falling back to first
                const targetV = matchedVariant || vs.find((v: ProductVariant) => v.is_default === true) || vs[0];
                setSelectedWeight(targetV?.weight_g ?? null);
                setSelectedStrength(targetV?.strength ? `${targetV.strength} ${targetV.strength_unit || ''}`.trim() : null);
                setSelectedVolume(targetV?.volume_ml ?? null);
                setSelectedCount(targetV?.units_count ? `${targetV.units_count} ${targetV.form_factor || 'Units'}` : null);
                setSelectedFlavor(targetV?.flavor ?? null);
                setSelectedPack(targetV?.pack_quantity ?? 1);
                setSelectedVariant(targetV);
            }

            // Set initial active tab based on availability
            if (data) {
                if (data.description) {
                    setActiveInfoTab('description');
                } else if (data.intended_use) {
                    setActiveInfoTab('howToUse');
                } else {
                    setActiveInfoTab('specifications');
                }
            }

            setLoading(false);

            // Track this product as recently viewed
            if (data) {
                trackRecentlyViewed(id);
                trackProductView(data.product_id);

                // GA4: view_item event
                const viewPrice = Number(data.variants?.find((v: ProductVariant) => v.is_default)?.price ?? data.price ?? 0);
                trackEcommerce('view_item', {
                    currency: 'INR',
                    value: viewPrice,
                    items: [{
                        item_id: data.product_id,
                        item_name: data.product_name,
                        price: viewPrice,
                        quantity: 1,
                        item_category: data.category || undefined,
                        item_brand: data.brand || undefined,
                    }],
                });
            }
        };

        load();
    }, [id]);

    useEffect(() => {
        if (product?.product_id) {
            getRatingSummary(product.product_id).then(res => {
                if (res.success && res.data) {
                    setRatingSummary(res.data);
                }
            });
        }
    }, [product?.product_id]);

    // ÔöÇÔöÇ Express checkout: auto-trigger Buy Now after login redirect ÔöÇÔöÇ
    useEffect(() => {
        if (searchParams.get('buyNow') === 'true' && isAuthenticated && product && !loading) {
            // Clear the buyNow param from URL without reload
            const url = new URL(window.location.href);
            url.searchParams.delete('buyNow');
            window.history.replaceState({}, '', url.pathname);

            // Store the Buy Now item and redirect to checkout
            const timer = setTimeout(() => {
                const buyNowItem = {
                    product_id: product.product_id,
                    product_name: product.product_name,
                    variant_id: selectedVariant?.variant_id || null,
                    size_label: selectedVariant?.size_label || '',
                    quantity: 1, // Default to 1 on express redirect
                    unit_price: Number(selectedVariant?.price ?? product.price ?? 0),
                    image_url: product.thumbnail_url || '',
                };
                sessionStorage.setItem('ksp_buy_now_item', JSON.stringify(buyNowItem));
                router.push(buildPath(country, `/checkout?buyNow=true`));
            }, 300);
            return () => clearTimeout(timer);
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [searchParams, isAuthenticated, product, loading]);

    if (loading) {
        return (

            <div className="min-h-screen bg-[#FDFCFB]">
                <div className="mx-auto max-w-7xl px-4 py-8">
                    <div className="grid gap-10 lg:grid-cols-2">
                        <div className="aspect-square rounded-2xl animate-shimmer" />
                        <div className="space-y-4">
                            <SkeletonLine className="h-6 w-1/3" />
                            <SkeletonLine className="h-8 w-2/3" />
                            <SkeletonLine className="h-6 w-1/4" />
                            <SkeletonLine className="h-20 w-full" />
                            <SkeletonLine className="h-12 w-full" />
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    if (!loading && !product) return notFound();
    if (!product) return null;

    const wishlisted = isInWishlist(product.product_id);

    const { displayPrice, originalPrice } = getValidPrices(
        selectedVariant?.price ?? product.price,
        selectedVariant?.sale_price ?? selectedVariant?.original_price ?? product.original_price ?? selectedVariant?.price ?? product.price
    );
    const isOnSale = selectedVariant?.is_on_sale ?? product.is_on_sale ?? false;
    const isDiscounted = originalPrice > displayPrice;
    const calculatedDiscountPercent = isDiscounted ? Math.round((1 - displayPrice / originalPrice) * 100) : 0;
    const discountPercent = calculatedDiscountPercent > 0 ? calculatedDiscountPercent : (selectedVariant?.discount_percentage ?? product.discount_percentage ?? 0);

    // Variant Activity
    const isVariantInactive = selectedVariant?.status === 'Inactive' || selectedVariant?.is_active === false;

    // Stock availability
    const stockQty = selectedVariant?.stock_quantity ?? product.stock_quantity ?? null;
    const isOutOfStock = stockQty !== null && stockQty <= 0;

    // Account for items already in cart for this product/variant
    const existingCartItem = items.find(i =>
        selectedVariant
            ? String(i.variant_id) === String(selectedVariant.variant_id)
            : String(i.product_id) === String(product.product_id)
    );
    const existingCartQty = existingCartItem?.quantity ?? 0;
    const effectiveMaxQty = stockQty !== null && stockQty > 0 ? Math.max(1, stockQty - existingCartQty) : 99;
    const maxQty = stockQty !== null && stockQty > 0 ? stockQty : 99;

    // Scheduled availability
    const isComingSoon = product.is_coming_soon ?? false;
    const isExpired = product.is_availability_expired ?? false;
    const isUnavailable = isComingSoon || isExpired || isOutOfStock || isVariantInactive;

    const handleMinus = () => {
        setPageQuantity(prev => Math.max(1, prev - 1));
    };

    const handlePlus = () => {
        if (pageQuantity >= effectiveMaxQty) {
            toast('Maximum stock reached', { icon: 'ÔÜá´©Å' });
            return;
        }
        setPageQuantity(prev => Math.min(effectiveMaxQty, prev + 1));
    };

    const handleAddToCart = async (e: React.MouseEvent<HTMLButtonElement>) => {
        if (!product || isOutOfStock) return;


        await addItem(
            product.product_id,
            selectedVariant?.variant_id || null,
            pageQuantity
        );
        toast.success(`Added ${pageQuantity} x ${product.product_name} to cart!`);
        setPageQuantity(1); // Reset counter to 1 after process
    };

    const handleBuyNow = async () => {
        if (!product || isUnavailable) return;

        // If user is NOT signed in, redirect to login with a return URL
        if (!isAuthenticated) {
            const returnUrl = buildPath(country, `/products/${product.slug || product.product_id}?buyNow=true`);
            router.push(buildPath(country, `/login?redirect=${encodeURIComponent(returnUrl)}`));
            return;
        }

        // User IS signed in ÔÇö store the single item and go straight to checkout
        const buyNowItem = {
            product_id: product.product_id,
            product_name: product.product_name,
            variant_id: selectedVariant?.variant_id || null,
            size_label: selectedVariant?.size_label || '',
            quantity: pageQuantity,
            unit_price: displayPrice,
            original_price: originalPrice,
            image_url: product.thumbnail_url || '',
        };
        sessionStorage.setItem('ksp_buy_now_item', JSON.stringify(buyNowItem));
        sessionStorage.removeItem('vedashi_checkout_draft');
        router.push(buildPath(country, `/checkout?buyNow=true`));
    };

    return (
        <div className="min-h-screen bg-[#FFFFFF] pb-16">
            {/* Breadcrumb */}
            <div className="border-b border-light-border bg-white py-1">
                <div className="mx-auto max-w-[1440px] px-4 py-1">
                    <nav className="flex items-center gap-2 text-sm text-gray-500">
                        <Link href={buildPath(country, '/')}>Home</Link>
                        <ChevronRight className="h-3 w-3" />
                        <Link href={buildPath(country, `/products`)}>Shop</Link>
                        <ChevronRight className="h-3 w-3" />
                        {product.category && (
                            <>
                                <Link href={buildPath(country, `/products?category=${encodeURIComponent(product.category.toLowerCase().replace(/\s+/g, '-'))}`)} className="hover:text-gray-900 transition-colors">
                                    {product.category}
                                </Link>
                                <ChevronRight className="h-3 w-3" />
                            </>
                        )}
                        <span className="text-gray-900 font-medium">{product.product_name}</span>
                    </nav>
                </div>
            </div>

            <div className="mx-auto max-w-[1420px] px-4 py-4">
                {/* ÔòÉÔòÉÔòÉ ABOVE THE FOLD ÔÇö loads immediately ÔòÉÔòÉÔòÉ */}
                <div className="grid gap-2 lg:grid-cols-[50%_1fr] items-start">
                    {/* IMAGE GALLERY */}
                    <div className="w-full max-w-[700px] mx-auto lg:mx-0">
                        <ProductImageGallery
                            assets={product.assets}
                            productName={product.product_name}
                            variantId={selectedVariant?.variant_id}
                            defaultVariantId={product.variants?.find((v: ProductVariant) => v.is_default)?.variant_id || product.variants?.[0]?.variant_id}
                            fallbackImages={product.images}
                            brand={product.brand || undefined}
                            category={product.category || undefined}
                        />
                    </div>

                    {/* DETAILS */}
                    <div className="space-y-1.5 pt-0 pr-0 lg:pr-4">
                        {/* Product Badges */}
                        <div className="flex flex-wrap gap-2">
                            {product.is_best_seller && (
                                <span className="inline-flex items-center justify-center bg-[#91C934] text-white text-[10px] font-extrabold px-3 py-1 rounded-md uppercase tracking-wider leading-none">
                                    Bestseller
                                </span>
                            )}
                            {product.is_new_arrival && (
                                <span className="inline-flex items-center justify-center bg-[#FF0000] text-white text-[10px] font-extrabold px-3 py-1 rounded-md uppercase tracking-wider leading-none">
                                    New Arrival
                                </span>
                            )}
                        </div>

                        {/* Title + Share */}
                        <div className="flex justify-between items-start gap-3">
                            <div className="flex-1">
                                <h1 className="text-2xl lg:text-[28px] font-bold !font-sans text-black leading-snug">
                                    {selectedVariant?.variant_name ?? variants?.[0]?.variant_name ?? product.product_name}
                                </h1>
                                {product.brand && (
                                    <div className="mt-1">
                                        <Link
                                            href={buildPath(country, `/products?brand=${encodeURIComponent(product.brand)}`)}
                                            className="text-sm font-semibold underline text-gray-500 hover:text-gray-700 transition-all"
                                        >
                                            {product.brand}
                                        </Link>
                                    </div>
                                )}
                            </div>
                            <div className="flex flex-col gap-2 mt-1 flex-shrink-0">
                                <button
                                    onClick={handleToggleWishlist}
                                    className={`p-2.5 rounded-full border transition-all group ${wishlisted ? 'border-[#91C934] bg-[#91C934]/10' : 'border-gray-200 bg-white hover:border-[#91C934]/30 hover:bg-gray-50'} hover:shadow-md cursor-pointer`}
                                    title={wishlisted ? "Remove from wishlist" : "Add to wishlist"}
                                >
                                    <Heart size={18} className={`transition-transform group-hover:scale-110 ${wishlisted ? 'fill-[#91C934] text-[#91C934]' : 'text-gray-400 group-hover:text-[#91C934]'}`} />
                                </button>
                                <button
                                    onClick={handleShare}
                                    className="p-2.5 rounded-full border border-gray-200 bg-white text-gray-400 hover:text-[#91C934] hover:border-[#91C934]/30 hover:bg-gray-50 hover:shadow-md transition-all group cursor-pointer"
                                    title="Share product"
                                >
                                    <Share2 size={18} className="group-hover:scale-110 transition-transform" />
                                </button>
                            </div>
                        </div>

                        {/* Short description under title */}
                        {product.short_description && (
                            <p className="text-sm text-gray-500 leading-relaxed -mt-1">
                                {product.short_description}
                            </p>
                        )}

                        {/* Rating + Reviews row */}
                        {(Number(ratingSummary?.average_rating || product.avg_rating || 0) > 0 || (Number(ratingSummary?.total_reviews || product.review_count || 0) > 0)) ? (
                            <div className="flex items-center gap-2 flex-wrap">
                                <div className="flex items-center gap-1">
                                    <div className="flex">
                                        {[...Array(5)].map((_, i) => {
                                            const rating = Number(ratingSummary?.average_rating || product.avg_rating || 0);
                                            const fill = Math.min(1, Math.max(0, rating - i));
                                            return (
                                                <svg key={i} className="w-4 h-4" viewBox="0 0 24 24">
                                                    <defs>
                                                        <linearGradient id={`star-fill-${i}`}>
                                                            <stop offset={`${fill * 100}%`} stopColor="#FFD801" />
                                                            <stop offset={`${fill * 100}%`} stopColor="#E5E7EB" />
                                                        </linearGradient>
                                                    </defs>
                                                    <path fill={`url(#star-fill-${i})`} d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z" />
                                                </svg>
                                            );
                                        })}
                                    </div>
                                    <span className="text-sm font-semibold text-gray-800 ml-1">{Number(ratingSummary?.average_rating || product.avg_rating || 0).toFixed(1)}</span>
                                </div>
                                {(ratingSummary?.total_reviews || Number(product.review_count || 0)) > 0 && (
                                    <span className="text-sm text-gray-500">({Number(ratingSummary?.total_reviews || product.review_count || 0).toLocaleString()} review{(ratingSummary?.total_reviews || Number(product.review_count || 0)) !== 1 ? 's' : ''})</span>
                                )}
                                {Number((product as Record<string, unknown>).total_sold || 0) > 0 && (
                                    <span className="text-sm text-gray-500 flex items-center gap-1">
                                        <span className="text-green-600">ÔùÅ</span> {(product as Record<string, unknown>).total_sold}+ bought this month
                                    </span>
                                )}
                            </div>
                        ) : (
                            <p className="text-sm text-gray-400 italic">No reviews yet</p>
                        )}


                        {/* Divider */}
                        <hr className="border-gray-100" />



                        {/* PRICE BLOCK */}
                        <div className="p-4 rounded-xl bg-white shadow-[inset_0_0_0_1px_#E9ECEF] space-y-1">
                            <div className="flex flex-col gap-1">
                                {isDiscounted && (
                                    <>
                                        <div className="text-[#1e3a8a] text-[13px] leading-none mb-1">
                                            <span className="font-black">WOW!</span> <span className="font-semibold">Limited Time Offer</span>
                                        </div>
                                        <div className="flex items-center gap-3">
                                            <span className="bg-[#C1262D] text-white text-xs font-bold px-2 py-0.5 rounded-sm">
                                                {discountPercent}% OFF
                                            </span>
                                            <div className="flex items-center gap-1.5 text-sm">
                                                <span className="text-gray-500">MRP</span>
                                                <span className="text-gray-400 line-through">
                                                    {formatMrp(originalPrice, displayPrice, (selectedVariant as Record<string, unknown>)?.country_prices || (product as Record<string, unknown>).country_prices)}
                                                </span>
                                            </div>
                                        </div>
                                    </>
                                )}
                                <div className="flex items-baseline gap-2">
                                    <p className="text-3xl font-extrabold text-[#C1262D]">
                                        {formatPrice(displayPrice, (selectedVariant as Record<string, unknown>)?.country_prices || (product as Record<string, unknown>).country_prices)}
                                    </p>
                                    <span className="text-sm text-gray-500">
                                        {selectedVariant?.size_label && selectedVariant.size_label.toLowerCase() !== 'standard'
                                            ? `(${selectedVariant.size_label})`
                                            : 'Inclusive of all taxes'}
                                    </span>
                                </div>
                            </div>
                            {selectedVariant?.size_label && selectedVariant.size_label.toLowerCase() !== 'standard' && (
                                <p className="text-sm text-gray-500">Inclusive of all taxes</p>
                            )}
                            <hr className="border-gray-200" />
                            <div className="pt-2">
                                <p className="text-[11px] text-gray-400 uppercase tracking-tight leading-none mb-1">MRP</p>
                                <div className="flex items-baseline gap-1.5">
                                    <span className="text-xl font-bold text-black">
                                        {formatMrp(originalPrice, displayPrice, (selectedVariant as Record<string, unknown>)?.country_prices || (product as Record<string, unknown>).country_prices)}
                                    </span>
                                    <span className="text-[12px] text-gray-400">(Inclusive of all taxes)</span>
                                </div>
                            </div>
                        </div>

                        {/* COUPON ROW */}
                        <div className="flex items-center justify-between border border-dashed border-gray-300 bg-[#FFFFFF] rounded-xl p-1 transition-all">
                            <div className="flex items-center gap-3">
                                <div className="flex h-9 w-9 items-center justify-center rounded-full bg-white shadow-sm text-[#91C934]">
                                    <Tag size={18} />
                                </div>
                                <div className="flex flex-col sm:flex-row sm:items-center sm:gap-2">
                                    <span className="text-[15px] font-bold text-gray-800">Extra 10% OFF</span>
                                    <span className="text-sm text-gray-500">Only for New Users.</span>
                                </div>
                            </div>
                            <div className="bg-white px-3 py-1 rounded-lg border border-gray-200 shadow-sm">
                                <span className="text-[13px] text-[#91C934] font-bold tracking-wider">Code : NEWUSER</span>
                            </div>
                        </div>

                        {/* GUARANTEED DELIVERY ROW */}
                        <div className="border border-dashed border-gray-300 rounded-lg p-2">
                            <div className="flex items-start gap-3">
                                <Truck className="h-5 w-5 text-gray-400 mt-0.5" />
                                <div className="flex-1">
                                    <p className="text-sm text-gray-800">
                                        Guaranteed delivery within <span className="font-bold text-[#91C934]">14 days </span>of ordering.
                                    </p>

                                </div>
                            </div>
                        </div>


                        {/* Divider */}
                        <hr className="border-gray-100" />


                        {/* Ô£à VARIANT SELECTORS: Weight, Strength, Volume, Count, Flavor, Pack */}
                        <div className="min-h-[20px]">
                            {variants.length > 0 && (() => {
                                const uniqueWeights = [...new Set(variants.map((v: ProductVariant) => v.weight_g as number))].filter(Boolean).sort((a, b) => a - b);
                                const uniqueStrengths = [...new Set(variants.map((v: ProductVariant) => v.strength ? `${v.strength} ${v.strength_unit || ''}`.trim() : null))].filter(Boolean);
                                const uniqueVolumes = [...new Set(variants.map((v: ProductVariant) => v.volume_ml as number))].filter(Boolean).sort((a, b) => a - b);
                                const uniqueCounts = [...new Set(variants.map((v: ProductVariant) => v.units_count ? `${v.units_count} ${v.form_factor || 'Units'}` : null))].filter(Boolean);
                                const uniqueFlavors = [...new Set(variants.map((v: ProductVariant) => v.flavor as string))].filter(Boolean);
                                const uniquePacks = [...new Set(variants.map((v: ProductVariant) => (v.pack_quantity ?? 1) as number))].filter(Boolean).sort((a, b) => a - b);

                                const formatVolume = (ml: number) => {
                                    return ml >= 999 ? `${(ml / 1000).toFixed(ml % 1000 === 0 ? 0 : 1)} L` : `${ml} ml`;
                                };

                                const formatWeight = (g: number) => {
                                    return g >= 1000 ? `${(g / 1000).toFixed(g % 1000 === 0 ? 0 : g % 100 === 0 ? 1 : 2)} kg` : `${Math.round(g)} g`;
                                };

                                const updateSelection = (updates: Record<string, unknown>) => {
                                    const newW = updates.weight !== undefined ? updates.weight : selectedWeight;
                                    const newS = updates.strength !== undefined ? updates.strength : selectedStrength;
                                    const newV = updates.volume !== undefined ? updates.volume : selectedVolume;
                                    const newC = updates.count !== undefined ? updates.count : selectedCount;
                                    const newF = updates.flavor !== undefined ? updates.flavor : selectedFlavor;
                                    const newP = updates.pack !== undefined ? updates.pack : selectedPack;

                                    // Try to find an exact match first
                                    let match = variants.find((v: Record<string, unknown>) =>
                                        (v.weight_g || null) === newW &&
                                        (v.strength ? `${v.strength} ${v.strength_unit || ''}`.trim() : null) === newS &&
                                        (v.volume_ml || null) === newV &&
                                        (v.units_count ? `${v.units_count} ${v.form_factor || 'Units'}` : null) === newC &&
                                        (v.flavor || null) === newF &&
                                        (v.pack_quantity ?? 1) === newP
                                    );

                                    // If no exact match, fallback to finding the first variant that matches the MOST RECENTLY updated dimension
                                    if (!match) {
                                        if (updates.weight !== undefined) match = variants.find((v: Record<string, unknown>) => v.weight_g === newW);
                                        else if (updates.strength !== undefined) match = variants.find((v: Record<string, unknown>) => (v.strength ? `${v.strength} ${v.strength_unit || ''}`.trim() : null) === newS);
                                        else if (updates.volume !== undefined) match = variants.find((v: Record<string, unknown>) => v.volume_ml === newV);
                                        else if (updates.count !== undefined) match = variants.find((v: Record<string, unknown>) => (v.units_count ? `${v.units_count} ${v.form_factor || 'Units'}` : null) === newC);
                                        else if (updates.flavor !== undefined) match = variants.find((v: Record<string, unknown>) => v.flavor === newF);
                                        else if (updates.pack !== undefined) match = variants.find((v: Record<string, unknown>) => (v.pack_quantity ?? 1) === newP);
                                    }

                                    if (match) {
                                        setSelectedWeight(match.weight_g || null);
                                        setSelectedStrength(match.strength ? `${match.strength} ${match.strength_unit || ''}`.trim() : null);
                                        setSelectedVolume(match.volume_ml || null);
                                        setSelectedCount(match.units_count ? `${match.units_count} ${match.form_factor || 'Units'}` : null);
                                        setSelectedFlavor(match.flavor || null);
                                        setSelectedPack(match.pack_quantity ?? 1);
                                        setSelectedVariant(match);
                                    } else {
                                        // Update state anyway to show what user clicked, but wait... variant must exist. 
                                        // With the above fallback, we always find at least some variant.
                                    }
                                };

                                const checkAvailable = (dimension: string, value: Record<string, unknown>) => {
                                    return variants.some((v: Record<string, unknown>) => {
                                        // A variant is "available" for a dimension/value if it matches everything ELSE currently selected
                                        const matchesWeight = dimension === 'weight' || !selectedWeight || v.weight_g === selectedWeight;
                                        const matchesStrength = dimension === 'strength' || !selectedStrength || (v.strength ? `${v.strength} ${v.strength_unit || ''}`.trim() : null) === selectedStrength;
                                        const matchesVolume = dimension === 'volume' || !selectedVolume || v.volume_ml === selectedVolume;
                                        const matchesCount = dimension === 'count' || !selectedCount || (v.units_count ? `${v.units_count} ${v.form_factor || 'Units'}` : null) === selectedCount;
                                        const matchesFlavor = dimension === 'flavor' || !selectedFlavor || v.flavor === selectedFlavor;
                                        const matchesPack = dimension === 'pack' || !selectedPack || (v.pack_quantity ?? 1) === selectedPack;

                                        let matchVal = false;
                                        if (dimension === 'weight') matchVal = v.weight_g === value;
                                        else if (dimension === 'strength') matchVal = (v.strength ? `${v.strength} ${v.strength_unit || ''}`.trim() : null) === value;
                                        else if (dimension === 'volume') matchVal = v.volume_ml === value;
                                        else if (dimension === 'count') matchVal = (v.units_count ? `${v.units_count} ${v.form_factor || 'Units'}` : null) === value;
                                        else if (dimension === 'flavor') matchVal = v.flavor === value;
                                        else if (dimension === 'pack') matchVal = (v.pack_quantity ?? 1) === value;

                                        return matchVal && matchesWeight && matchesStrength && matchesVolume && matchesCount && matchesFlavor && matchesPack && v.status !== 'Inactive' && v.is_active !== false;
                                    });
                                };

                                const isOptionActive = (dimension: string, value: Record<string, unknown>) => {
                                    return variants.some((v: Record<string, unknown>) => {
                                        let match = false;
                                        if (dimension === 'weight') match = v.weight_g === value;
                                        if (dimension === 'strength') match = (v.strength ? `${v.strength} ${v.strength_unit || ''}`.trim() : null) === value;
                                        if (dimension === 'volume') match = v.volume_ml === value;
                                        if (dimension === 'count') match = (v.units_count ? `${v.units_count} ${v.form_factor || 'Units'}` : null) === value;
                                        if (dimension === 'flavor') match = v.flavor === value;
                                        if (dimension === 'pack') match = (v.pack_quantity ?? 1) === value;

                                        return match && v.status !== 'Inactive' && v.is_active !== false;
                                    });
                                };

                                const hasSingleWeight = uniqueWeights.length === 1;
                                const hasSingleStrength = uniqueStrengths.length === 1;
                                const hasSingleVolume = uniqueVolumes.length === 1;
                                const hasSingleCount = uniqueCounts.length === 1;
                                const hasSingleFlavor = uniqueFlavors.length === 1;
                                const hasSinglePack = uniquePacks.length === 1 && uniquePacks[0] > 1; // Only show single pack if it's not a generic size of 1

                                return (
                                    <div className="space-y-4">
                                        {/* Ô£à SINGLE-ATTRIBUTES AS KEY-VALUE PAIRS */}
                                        {(hasSingleWeight || hasSingleStrength || hasSingleVolume || hasSingleCount || hasSingleFlavor || hasSinglePack) && (
                                            <div className="flex flex-wrap items-center gap-x-6 gap-y-2 mb-6 pb-4 border-b border-gray-100">
                                                {hasSingleWeight && (
                                                    <div className="flex items-baseline">
                                                        <span className="text-sm text-gray-900 mr-2 font-medium">Weight:</span>
                                                        <span className="text-sm font-medium text-gray-900">{formatWeight(uniqueWeights[0])}</span>
                                                    </div>
                                                )}
                                                {hasSingleStrength && (
                                                    <div className="flex items-baseline">
                                                        <span className="text-sm text-gray-900 mr-2 font-medium">Strength:</span>
                                                        <span className="text-sm font-medium text-gray-900">{uniqueStrengths[0]}</span>
                                                    </div>
                                                )}
                                                {hasSingleVolume && (
                                                    <div className="flex items-baseline">
                                                        <span className="text-sm text-gray-900 mr-2 font-medium">Volume:</span>
                                                        <span className="text-sm font-medium text-gray-900">{formatVolume(uniqueVolumes[0])}</span>
                                                    </div>
                                                )}
                                                {hasSingleCount && (
                                                    <div className="flex items-baseline">
                                                        <span className="text-sm text-gray-900 mr-2 font-medium">Count:</span>
                                                        <span className="text-sm font-medium text-gray-900">{uniqueCounts[0]}</span>
                                                    </div>
                                                )}
                                                {hasSingleFlavor && (
                                                    <div className="flex items-baseline">
                                                        <span className="text-sm text-gray-900 mr-2 font-medium">Flavour:</span>
                                                        <span className="text-sm font-medium text-gray-900 capitalize">{uniqueFlavors[0]}</span>
                                                    </div>
                                                )}
                                                {hasSinglePack && (
                                                    <div className="flex items-baseline">
                                                        <span className="text-sm text-gray-900 mr-2 font-medium">Pack:</span>
                                                        <span className="text-sm font-medium text-gray-900">Pack of {uniquePacks[0]}</span>
                                                    </div>
                                                )}
                                            </div>
                                        )}

                                        {/* Choose Weight / Size */}
                                        {uniqueWeights.length > 1 && (
                                            <div className="flex items-start gap-3">
                                                <p className="text-sm font-bold text-gray-900 w-[65px] pt-2.5 flex-shrink-0">Size</p>
                                                <div className="flex gap-2.5 flex-wrap flex-1">
                                                    {uniqueWeights.map((w) => {
                                                        const isSelected = selectedWeight === w;
                                                        const available = checkAvailable('weight', w);
                                                        const active = isOptionActive('weight', w);

                                                        return (
                                                            <button
                                                                key={w}
                                                                onClick={() => active && updateSelection({ weight: w })}
                                                                disabled={!active}
                                                                className={`px-5 py-2 rounded-lg border text-sm font-medium transition-all duration-200
                                                                    ${isSelected
                                                                        ? 'bg-white text-[#91C934] border-[#91C934] border-2 shadow-sm'
                                                                        : !available
                                                                            ? 'border-gray-200 border-dashed text-gray-400 bg-gray-50/30 cursor-pointer text-xs'
                                                                            : 'bg-white border-gray-300 text-gray-700 hover:border-[#91C934] hover:text-[#91C934]'
                                                                    }`}
                                                            >
                                                                {formatWeight(w)}
                                                            </button>
                                                        );
                                                    })}
                                                </div>
                                            </div>
                                        )}

                                        {/* By Strength */}
                                        {uniqueStrengths.length > 1 && (
                                            <div className="flex items-start gap-3">
                                                <p className="text-sm font-bold text-gray-900 w-[65px] pt-2.5 flex-shrink-0">Strength</p>
                                                <div className="flex gap-2.5 flex-wrap flex-1">
                                                    {uniqueStrengths.map((str) => {
                                                        const isSelected = selectedStrength === str;
                                                        const available = checkAvailable('strength', str);
                                                        const active = isOptionActive('strength', str);

                                                        return (
                                                            <button
                                                                key={str}
                                                                onClick={() => active && updateSelection({ strength: str })}
                                                                disabled={!active}
                                                                className={`px-5 py-2 rounded-lg border text-sm font-medium transition-all duration-200
                                                                    ${isSelected
                                                                        ? 'bg-white text-[#91C934] border-[#91C934] border-2 shadow-sm'
                                                                        : !available
                                                                            ? 'border-gray-200 border-dashed text-gray-400 bg-gray-50/30 cursor-pointer text-xs'
                                                                            : 'bg-white border-gray-300 text-gray-700 hover:border-[#91C934] hover:text-[#91C934]'
                                                                    }`}
                                                            >
                                                                {str}
                                                            </button>
                                                        );
                                                    })}
                                                </div>
                                            </div>
                                        )}

                                        {/* Choose Volume */}
                                        {uniqueVolumes.length > 1 && (
                                            <div className="flex items-start gap-3">
                                                <p className="text-sm font-bold text-gray-900 w-[65px] pt-2.5 flex-shrink-0">Volume</p>
                                                <div className="flex gap-2.5 flex-wrap flex-1">
                                                    {uniqueVolumes.map((vol) => {
                                                        const isSelected = selectedVolume === vol;
                                                        const available = checkAvailable('volume', vol);
                                                        const active = isOptionActive('volume', vol);

                                                        return (
                                                            <button
                                                                key={vol}
                                                                onClick={() => active && updateSelection({ volume: vol })}
                                                                disabled={!active}
                                                                className={`px-5 py-2 rounded-lg border text-sm font-medium transition-all duration-200
                                                                    ${isSelected
                                                                        ? 'bg-white text-[#91C934] border-[#91C934] border-2 shadow-sm'
                                                                        : !available
                                                                            ? 'border-gray-200 border-dashed text-gray-400 bg-gray-50/30 cursor-pointer text-xs'
                                                                            : 'bg-white border-gray-300 text-gray-700 hover:border-[#91C934] hover:text-[#91C934]'
                                                                    }`}
                                                            >
                                                                {formatVolume(vol)}
                                                            </button>
                                                        );
                                                    })}
                                                </div>
                                            </div>
                                        )}

                                        {/* By Count */}
                                        {uniqueCounts.length > 1 && (
                                            <div className="flex items-start gap-3">
                                                <p className="text-sm font-bold text-gray-900 w-[65px] pt-2.5 flex-shrink-0">Count</p>
                                                <div className="flex gap-2.5 flex-wrap flex-1">
                                                    {uniqueCounts.map((countStr) => {
                                                        const isSelected = selectedCount === countStr;
                                                        const available = checkAvailable('count', countStr);
                                                        const active = isOptionActive('count', countStr);

                                                        return (
                                                            <button
                                                                key={countStr}
                                                                onClick={() => active && updateSelection({ count: countStr })}
                                                                disabled={!active}
                                                                className={`px-5 py-2 rounded-lg border text-sm font-medium transition-all duration-200
                                                                    ${isSelected
                                                                        ? 'bg-white text-[#91C934] border-[#91C934] border-2 shadow-sm'
                                                                        : !available
                                                                            ? 'border-gray-200 border-dashed text-gray-400 bg-gray-50/30 cursor-pointer text-xs'
                                                                            : 'bg-white border-gray-300 text-gray-700 hover:border-[#91C934] hover:text-[#91C934]'
                                                                    }`}
                                                            >
                                                                {countStr}
                                                            </button>
                                                        );
                                                    })}
                                                </div>
                                            </div>
                                        )}

                                        {/* By Flavor */}
                                        {uniqueFlavors.length > 1 && (
                                            <div className="flex items-start gap-3">
                                                <p className="text-sm font-bold text-gray-900 w-[65px] pt-2.5 flex-shrink-0">Flavour</p>
                                                <div className="flex gap-2.5 flex-wrap flex-1">
                                                    {uniqueFlavors.map((flav) => {
                                                        const isSelected = selectedFlavor === flav;
                                                        const available = checkAvailable('flavor', flav);
                                                        const active = isOptionActive('flavor', flav);

                                                        return (
                                                            <button
                                                                key={flav}
                                                                onClick={() => active && updateSelection({ flavor: flav })}
                                                                disabled={!active}
                                                                className={`px-5 py-2 rounded-lg border text-sm font-medium transition-all duration-200
                                                                    ${isSelected
                                                                        ? 'bg-white text-[#91C934] border-[#91C934] border-2 shadow-sm'
                                                                        : !available
                                                                            ? 'border-gray-200 border-dashed text-gray-400 bg-gray-50/30 cursor-pointer text-xs'
                                                                            : 'bg-white border-gray-300 text-gray-700 hover:border-[#91C934] hover:text-[#91C934]'
                                                                    }`}
                                                            >
                                                                {flav}
                                                            </button>
                                                        );
                                                    })}
                                                </div>
                                            </div>
                                        )}

                                        {/* Pack of */}
                                        {uniquePacks.length > 1 && (
                                            <div className="flex items-start gap-3">
                                                <p className="text-sm font-bold text-gray-900 w-[65px] pt-3 flex-shrink-0">Pack of</p>
                                                <div className="flex gap-2.5 flex-wrap flex-1">
                                                    {uniquePacks.map((pack) => {
                                                        const isSelected = selectedPack === pack;
                                                        const available = checkAvailable('pack', pack);
                                                        const active = isOptionActive('pack', pack);

                                                        return (
                                                            <button
                                                                key={pack}
                                                                onClick={() => active && updateSelection({ pack })}
                                                                disabled={!active}
                                                                className={`w-11 h-11 rounded-lg border text-sm font-semibold transition-all duration-200 flex items-center justify-center
                                                                    ${isSelected
                                                                        ? 'bg-white text-[#91C934] border-[#91C934] border-2 shadow-sm'
                                                                        : !available
                                                                            ? 'border-gray-200 border-dashed text-gray-400 bg-gray-50/30 cursor-pointer text-xs'
                                                                            : 'bg-white border-gray-300 text-gray-700 hover:border-[#91C934] hover:text-[#91C934]'
                                                                    }`}
                                                            >
                                                                {pack}
                                                            </button>
                                                        );
                                                    })}
                                                </div>
                                            </div>
                                        )}

                                    </div>
                                );
                            })()}
                        </div>




                        {/* STOCK BADGE (Hidden if available, shown if issues) */}
                        {isUnavailable && (
                            <div className="flex items-center gap-4 py-2">
                                {isComingSoon ? (
                                    <div className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-semibold bg-purple-50 text-purple-700 border border-purple-200">
                                        ­ƒòÆ Coming Soon
                                    </div>
                                ) : isExpired ? (
                                    <div className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-semibold bg-red-50 text-red-600 border border-red-200">
                                        <AlertTriangle size={12} /> Availability Ended
                                    </div>
                                ) : isOutOfStock && (
                                    <div className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-semibold bg-red-50 text-red-600 border border-red-200">
                                        <AlertTriangle size={12} /> Out of Stock
                                    </div>
                                )}
                            </div>
                        )}

                        {/* QUANTITY + ACTION BUTTONS ROW */}
                        <div className="pt-2">
                            {isOutOfStock ? (
                                <div className="bg-red-50 p-4 rounded-xl border border-red-100 flex flex-col gap-3">
                                    <div className="flex items-center gap-2 text-red-700 font-semibold mb-1">
                                        <AlertTriangle size={16} />
                                        <span>Notify me when back in stock</span>
                                    </div>
                                    <div className="flex gap-2">
                                        <input
                                            type="email"
                                            placeholder="Enter your email address"
                                            className="flex-1 px-4 py-2 border border-red-200 rounded-lg text-sm focus:outline-none focus:border-red-400 focus:ring-1 focus:ring-red-400 bg-white placeholder-red-300"
                                            value={restockEmail}
                                            onChange={(e) => setRestockEmail(e.target.value)}
                                        />
                                        <button
                                            onClick={handleRestockNotify}
                                            disabled={isRestockNotifying || !restockEmail}
                                            className="px-6 py-2 bg-red-600 text-white font-bold rounded-lg hover:bg-red-700 transition disabled:opacity-50 text-sm whitespace-nowrap shadow-sm shadow-red-200"
                                        >
                                            {isRestockNotifying ? <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin inline-block" /> : 'Notify Me'}
                                        </button>
                                    </div>
                                </div>
                            ) : existingCartItem ? (
                                <div className="grid grid-cols-[auto_1fr_1fr] gap-3">
                                    {/* Qty Selector */}
                                    <div className="flex items-center justify-between border border-gray-300 rounded-lg p-1 bg-white h-[48px] w-[110px]">
                                        <button
                                            onClick={async () => {
                                                const newQty = existingCartQty - 1;
                                                if (newQty <= 0) {
                                                    await removeItem(existingCartItem.cart_item_id);
                                                    toast.success('Removed from cart');
                                                } else {
                                                    await updateQuantity(existingCartItem.cart_item_id, newQty);
                                                }
                                            }}
                                            disabled={cartLoading}
                                            className="w-10 h-10 flex items-center justify-center text-gray-500 hover:text-gray-800 transition"
                                        >
                                            {existingCartQty <= 1 ? <Trash2 size={16} /> : <Minus size={16} />}
                                        </button>
                                        <span className="text-base font-bold text-gray-900">{existingCartQty}</span>
                                        <button
                                            onClick={async () => {
                                                const maxStock = stockQty ?? 99;
                                                if (existingCartQty >= maxStock) {
                                                    toast('Maximum stock reached', { icon: 'ÔÜá´©Å' });
                                                    return;
                                                }
                                                await updateQuantity(existingCartItem.cart_item_id, existingCartQty + 1);
                                            }}
                                            disabled={cartLoading || existingCartQty >= (stockQty ?? 99)}
                                            className="w-10 h-10 flex items-center justify-center text-gray-500 hover:text-gray-800 transition disabled:opacity-30 disabled:cursor-not-allowed"
                                        >
                                            <Plus size={16} />
                                        </button>
                                    </div>
                                    <button
                                        onClick={() => router.push(`/${country || 'us'}/cart`)}
                                        className="w-full bg-white border border-gray-300 hover:border-[#91C934] text-gray-800 font-bold rounded-lg h-[48px] transition-colors flex items-center justify-center gap-2 group"
                                    >
                                        <ShoppingCart size={18} className="text-[#91C934]" /> View Cart
                                    </button>
                                    <button
                                        onClick={handleBuyNow}
                                        disabled={isUnavailable || cartLoading}
                                        className={`w-full rounded-lg py-2 flex justify-center items-center gap-2 font-bold transition-all h-[48px] ${isUnavailable
                                            ? 'bg-gray-100 text-gray-400 cursor-not-allowed border border-gray-200'
                                            : 'bg-[#91C934] hover:bg-[#7ab52a] text-white shadow-sm'
                                            }`}
                                    >
                                        Buy Now
                                    </button>
                                </div>
                            ) : (
                                <div className="grid grid-cols-[auto_1fr_1fr] gap-3">
                                    {/* Qty Selector */}
                                    <div className="flex items-center justify-between border border-gray-300 rounded-lg p-1 bg-white h-[48px] w-[110px]">
                                        <button
                                            onClick={handleMinus}
                                            disabled={pageQuantity <= 1}
                                            className="w-10 h-10 flex items-center justify-center text-gray-500 hover:text-gray-800 transition disabled:opacity-30"
                                        >
                                            <Minus className="h-4 w-4" />
                                        </button>
                                        <span className="text-base font-bold text-gray-900">{pageQuantity}</span>
                                        <button
                                            onClick={handlePlus}
                                            disabled={pageQuantity >= effectiveMaxQty}
                                            className="w-10 h-10 flex items-center justify-center text-gray-500 hover:text-gray-800 transition disabled:opacity-30"
                                        >
                                            <Plus className="h-4 w-4" />
                                        </button>
                                    </div>

                                    <button
                                        onClick={(e) => handleAddToCart(e)}
                                        disabled={isUnavailable || cartLoading}
                                        className={`w-full rounded-lg py-2 flex cursor-pointer justify-center items-center gap-2 font-semibold transition-all h-[48px] ${isUnavailable
                                            ? 'bg-gray-100 text-gray-400 cursor-not-allowed border-2 border-[#91C934]'
                                            : 'bg-white border-2 border-[#91C934] hover:border-[#91C934] hover:bg-gray-50 text-[#91C934] shadow-sm'
                                            }`}
                                    >
                                        <ShoppingCart size={18} className={isUnavailable ? "text-gray-400" : "text-[#91C934]"} />
                                        {isComingSoon ? 'Coming Soon' : isExpired ? 'Unavailable' : isVariantInactive ? 'Unavailable' : 'Add to Cart'}
                                    </button>

                                    <button
                                        onClick={handleBuyNow}
                                        disabled={isUnavailable || cartLoading}
                                        className={`w-full rounded-lg py-2 flex cursor-pointer justify-center items-center gap-2 font-bold transition-all h-[48px] ${isUnavailable
                                            ? 'bg-gray-100 text-gray-400 cursor-not-allowed border border-gray-200'
                                            : 'bg-[#91C934] hover:bg-[#7ab52a] text-white shadow-sm'
                                            }`}
                                    >
                                        Buy Now
                                    </button>
                                </div>
                            )}
                        </div>

