const LANGUAGES = [
  { code: 'en', label: 'English' },
  { code: 'hi', label: 'Óñ╣Óñ┐Óñ¿ÓÑìÓñªÓÑÇ (Hindi)' },
  { code: 'ko', label: 'Ýò£ÛÁ¡ýû┤ (Korean)' },
  { code: 'ru', label: 'ðáÐâÐüÐüð║ð©ð╣ (Russian)' },
  { code: 'es', label: 'Espa├▒ol (Spanish)' },
  { code: 'fr', label: 'Fran├ºais (French)' },
  { code: 'de', label: 'Deutsch (German)' },
  { code: 'ja', label: 'µùÑµ£¼Þ¬× (Japanese)' },
  { code: 'zh-CN', label: 'õ©¡µûç (Chinese)' },
  { code: 'ar', label: 'Ïº┘äÏ╣Ï▒Ï¿┘èÏ® (Arabic)' },
  { code: 'pt', label: 'Portugu├¬s' },
  { code: 'it', label: 'Italiano (Italian)' },
];

/**
 * Hides Google Translate's toolbar/banner using CSS only (no DOM removal).
 * Removing elements from the DOM breaks translation, so we only visually hide them.
 */
function hideGoogleToolbar() {
  // Hide the banner iframe
  document.querySelectorAll('.goog-te-banner-frame, .goog-te-banner-frame.skiptranslate, iframe.goog-te-banner-frame').forEach(el => {
    const iframe = el as HTMLElement;
    iframe.style.setProperty('display', 'none', 'important');
    iframe.style.setProperty('visibility', 'hidden', 'important');
    iframe.style.setProperty('height', '0', 'important');
  });

  // Hide the top notification bar ("Translated into: Russian | Show original")
  document.querySelectorAll('.skiptranslate').forEach(el => {
    const elem = el as HTMLElement;
    // Don't hide our own hidden container
    if (elem.id === 'gtranslate-hidden') return;
    // Only hide top-level skiptranslate divs (not nested ones that might break things)
    if (elem.tagName === 'DIV' && elem.classList.contains('skiptranslate')) {
      elem.style.setProperty('display', 'none', 'important');
      elem.style.setProperty('height', '0', 'important');
      elem.style.setProperty('visibility', 'hidden', 'important');
      elem.style.setProperty('opacity', '0', 'important');
      elem.style.setProperty('overflow', 'hidden', 'important');
    }
  });

  // Hide Google's notification container by known class names
  document.querySelectorAll(
    '.VIpgJd-ZVi9od-aZ2wEe-wOHMyf, .VIpgJd-ZVi9od-aZ2wEe-wOHMyf-ti6hGc, #goog-gt-tt, .goog-te-menu-value'
  ).forEach(el => {
    (el as HTMLElement).style.setProperty('display', 'none', 'important');
  });

  // Reset the body layout shift that Google pushes
  document.body.style.setProperty('top', '0px', 'important');
  document.body.style.setProperty('margin-top', '0px', 'important');
  document.body.style.setProperty('padding-top', '0px', 'important');
  document.body.style.setProperty('position', '', '');
}

export default function GoogleTranslateWidget({ upward = false }: { upward?: boolean }) {
  const initialized = useRef(false);
  const [open, setOpen] = useState(false);
  const [activeLang, setActiveLang] = useState('en');
  const [ready, setReady] = useState(false);
  const wrapperRef = useRef<HTMLDivElement>(null);
  const [shouldLoadScript, setShouldLoadScript] = useState(false);

  // Lazy-load: only start downloading Google Translate when user interacts
  const initGoogleTranslate = useCallback(() => {
    if (shouldLoadScript) return;
    setShouldLoadScript(true);
  }, [shouldLoadScript]);

  useEffect(() => {
    if (!shouldLoadScript || initialized.current) return;
    initialized.current = true;

    window.googleTranslateElementInit = () => {
      new window.google.translate.TranslateElement(
        {
          pageLanguage: 'en',
          includedLanguages: LANGUAGES.map(l => l.code).join(','),
          autoDisplay: false,
        },
        'gtranslate-hidden'
      );
      // Poll for the <select> to appear
      const poll = setInterval(() => {
        const sel = document.querySelector('#gtranslate-hidden select.goog-te-combo') as HTMLSelectElement;
        if (sel) {
          clearInterval(poll);
          setReady(true);
        }
      }, 200);
    };

    if (!document.getElementById('gtranslate-script')) {
      const script = document.createElement('script');
      script.id = 'gtranslate-script';
      script.src = 'https://translate.google.com/translate_a/element.js?cb=googleTranslateElementInit';
      script.async = true;
      document.head.appendChild(script);
    }

    // Periodically hide Google's toolbar (CSS only ÔÇö never remove from DOM)
    const interval = setInterval(hideGoogleToolbar, 300);
    // Also react to DOM mutations
    const observer = new MutationObserver(hideGoogleToolbar);
    observer.observe(document.body, { childList: true, subtree: false, attributes: true, attributeFilter: ['style', 'class'] });

    // Inject styles dynamically to prevent Next.js hydration mismatch
    const styleId = 'gtranslate-widget-styles';
    if (!document.getElementById(styleId)) {
      const style = document.createElement('style');
      style.id = styleId;
      style.innerHTML = `
        .goog-te-banner-frame,
        .goog-te-banner-frame.skiptranslate,
        iframe.goog-te-banner-frame,
        .skiptranslate:not(#gtranslate-hidden),
        div.skiptranslate,
        .VIpgJd-ZVi9od-aZ2wEe-wOHMyf,
        .VIpgJd-ZVi9od-aZ2wEe-wOHMyf-ti6hGc {
          display: none !important;
          height: 0 !important;
          max-height: 0 !important;
          visibility: hidden !important;
          box-shadow: none !important;
          overflow: hidden !important;
          opacity: 0 !important;
          pointer-events: none !important;
          position: fixed !important;
          top: -9999px !important;
          left: -9999px !important;
        }
        body {
          top: 0px !important;
          margin-top: 0px !important;
          padding-top: 0px !important;
        }
        #goog-gt-tt,
        .goog-te-menu-value,
        .goog-te-spinner-pos,
        .goog-tooltip,
        .goog-tooltip:hover,
        #google_translate_element2,
        .goog-te-ftab-link {
          display: none !important;
        }
        .goog-text-highlight {
          background: none !important;
          box-shadow: none !important;
        }
        .gtranslate-dropdown-container {
          left: 50% !important;
          transform: translateX(-50%) !important;
          transform-origin: ${upward ? 'bottom' : 'top'} !important;
        }
        @media (min-width: 640px) {
          .gtranslate-dropdown-container {
            left: auto !important;
            right: -8px !important;
            transform: none !important;
            transform-origin: ${upward ? 'bottom right' : 'top right'} !important;
          }
        }
      `;
      document.head.appendChild(style);
    }

    return () => {
      clearInterval(interval);
      observer.disconnect();
    };
  }, [shouldLoadScript]);

  // Close on outside click
  useEffect(() => {
    if (!open) return;
    const handleClick = (e: MouseEvent) => {
      if (wrapperRef.current && !wrapperRef.current.contains(e.target as Node)) {
        setOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, [open]);

  const selectLanguage = useCallback((langCode: string) => {
    setActiveLang(langCode);
    setOpen(false);

    const select = document.querySelector('#gtranslate-hidden select.goog-te-combo') as HTMLSelectElement;
    if (!select) return;

    select.value = langCode;
    // Fire a native change event to trigger Google Translate
    const evt = document.createEvent('HTMLEvents');
    evt.initEvent('change', true, true);
    select.dispatchEvent(evt);

    // Hide the toolbar that appears after translation (with retries)
    for (const delay of [500, 1000, 1500, 2500]) {
      setTimeout(hideGoogleToolbar, delay);
    }
  }, []);

  const activeLabel = LANGUAGES.find(l => l.code === activeLang)?.label || 'English';

  return (
    <>
      {/* Google Translate's actual element ÔÇö visually hidden but in the DOM */}
      <div
        id="gtranslate-hidden"
        style={{
          position: 'absolute',
          left: '-9999px',
          top: '-9999px',
          width: '1px',
          height: '1px',
          overflow: 'hidden',
          opacity: 0,
        }}
        suppressHydrationWarning
      />

      <div ref={wrapperRef} style={{ position: 'relative', display: 'flex', alignItems: 'center' }} suppressHydrationWarning>
        <button
          onClick={() => { initGoogleTranslate(); setOpen(!open); }}
          onMouseEnter={initGoogleTranslate}
          onFocus={initGoogleTranslate}
          style={{
            padding: '8px',
            background: 'none',
            border: 'none',
            cursor: 'pointer',
            position: 'relative',
            display: 'flex',
            alignItems: 'center',
          }}
          aria-label={`Translate ÔÇö ${activeLabel}`}
          title={`Translate ÔÇö ${activeLabel}`}
          type="button"
          suppressHydrationWarning
        >
          <Globe
            style={{
              width: '20px',
              height: '20px',
              color: open ? '#3B5D3B' : '#555',
              transition: 'color 0.2s',
            }}
          />
          {activeLang !== 'en' && (
            <span
              style={{
                position: 'absolute',
                top: '4px',
                right: '4px',
                width: '8px',
                height: '8px',
                background: '#3B5D3B',
                borderRadius: '50%',
                border: '2px solid white',
              }}
            />
          )}
        </button>

        {/* Dropdown */}
        {open && (
          <div
            className="gtranslate-dropdown-container"
            style={{
              position: 'absolute',
              bottom: upward ? 'calc(100% + 8px)' : 'auto',
              top: upward ? 'auto' : 'calc(100% + 8px)',
              width: '200px',
              background: '#fff',
              border: '1px solid #e8e4dc',
              borderRadius: '14px',
              boxShadow: '0 12px 40px rgba(0,0,0,0.12), 0 2px 8px rgba(0,0,0,0.04)',
              padding: '10px',
              zIndex: 9999,
            }}
          >
            <div
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: '6px',
                paddingBottom: '8px',
                marginBottom: '6px',
                borderBottom: '1px solid #f0ece4',
                fontSize: '10px',
                fontWeight: 700,
                textTransform: 'uppercase' as const,
                letterSpacing: '0.12em',
                color: '#3B5D3B',
              }}
            >
              <Globe style={{ width: '14px', height: '14px', color: '#3B5D3B' }} />
              <span>Translate</span>
            </div>

            <div
              style={{
                maxHeight: '280px',
                overflowY: 'auto',
                display: 'flex',
                flexDirection: 'column',
                gap: '2px',
              }}
            >
              {LANGUAGES.map(lang => {
                const isActive = activeLang === lang.code;
                return (
                  <button
                    key={lang.code}
                    onClick={() => selectLanguage(lang.code)}
                    type="button"
                    style={{
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'space-between',
                      padding: '8px 10px',
                      borderRadius: '8px',
                      fontSize: '13px',
                      fontWeight: isActive ? 600 : 450,
                      color: isActive ? '#3B5D3B' : '#374151',
                      background: isActive ? '#edf5ed' : 'transparent',
                      border: 'none',
                      cursor: ready ? 'pointer' : 'wait',
                      width: '100%',
                      textAlign: 'left' as const,
                      transition: 'background 0.15s',
                      opacity: ready ? 1 : 0.5,
                    }}
                    onMouseEnter={e => {
                      if (!isActive) (e.currentTarget.style.background = '#f5f2e8');
                    }}
                    onMouseLeave={e => {
                      if (!isActive) (e.currentTarget.style.background = isActive ? '#edf5ed' : 'transparent');
                    }}
                    disabled={!ready}
                  >
                    <span>{lang.label}</span>
                    {isActive && <Check style={{ width: '14px', height: '14px', color: '#3B5D3B' }} />}
                  </button>
                );
              })}
            </div>
          </div>
        )}
      </div>
    </>
  );
}

'use client';

import { useState, useEffect, useCallback, useRef } from 'react';
import Link from 'next/link';
import Image from 'next/image';
import { ArrowRight, ChevronLeft, ChevronRight } from 'lucide-react';
import { API_URL, getHeroSlides, getHeroSettings } from '@/lib/api';
import { useParams } from 'next/navigation';
import { buildPath, getCountryFromPathname } from '@/lib/currency';

// API_URL imported from @/lib/api

export interface TextElement {
    id: string;
    text: string;
    color: string;
    fontSize: string;
}

export interface ButtonElement {
    id: string;
    label: string;
    url: string;
    bgColor: string;
    textColor: string;
    size: string;
}

export interface HeroSlide {
    id: string;
    image_url: string;
    headings: TextElement[];
    subheadings: TextElement[];
    buttons: ButtonElement[];
    overlay_opacity: number;
    link_url?: string;
}

export interface HeroSettings {
    slider_speed: number;
    arrow_visibility: 'visible' | 'hover' | 'hidden';
    loop: boolean;
    slideshow_type: 'fade' | 'slide_right_to_left' | 'slide_left_to_right';
}

export interface HeroCarouselProps {
    initialSlides?: HeroSlide[];
    initialSettings?: HeroSettings;
}

export default function HeroCarousel({ initialSlides = [], initialSettings = undefined }: HeroCarouselProps) {
    const params = useParams<{ country: string }>();
    const country = params?.country || 'us';
    const [slides, setSlides] = useState<HeroSlide[]>(initialSlides);
    const [settings, setSettings] = useState<HeroSettings>(
        initialSettings || { slider_speed: 3000, arrow_visibility: 'hover', loop: true, slideshow_type: 'fade' }
    );
    const [loading, setLoading] = useState(false);
    const [current, setCurrent] = useState(0);
    const [paused, setPaused] = useState(false);
    const [hovering, setHovering] = useState(false);
    const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);
    const prevIndexRef = useRef<number>(0);
    const directionRef = useRef<'next' | 'prev'>('next');
    const [touchStart, setTouchStart] = useState<number | null>(null);
    const [touchEnd, setTouchEnd] = useState<number | null>(null);

    const minSwipeDistance = 50;

    const handleTouchStart = (e: React.TouchEvent) => {
        setTouchEnd(null);
        setTouchStart(e.targetTouches[0].clientX);
    };

    const handleTouchMove = (e: React.TouchEvent) => setTouchEnd(e.targetTouches[0].clientX);

    const handleTouchEnd = () => {
        if (!touchStart || !touchEnd) return;
        const distance = touchStart - touchEnd;
        const isLeftSwipe = distance > minSwipeDistance;
        const isRightSwipe = distance < -minSwipeDistance;
        if (isLeftSwipe) next();
        if (isRightSwipe) prev();
    };

    useEffect(() => {
        // If we received initial slides from SSR, check if they are real or just fallbacks
        // If they are fallbacks (starting with 'default-'), we still want to try fetching the real ones on the client
        const hasRealSlides = slides.length > 0 && !slides.some(s => s.id.startsWith('default-'));
        if (hasRealSlides) return;

        setLoading(true);
        // Fetch active slides and settings in parallel using helpers
        Promise.all([
            getHeroSlides(),
            getHeroSettings()
        ])
            .then(([slidesData, settingsData]) => {
                if (slidesData.success && slidesData.data?.length > 0) {
                    setSlides(slidesData.data);
                }
                if (settingsData.success && settingsData.data) setSettings(settingsData.data);
            })
            .catch(() => { })
            .finally(() => setLoading(false));
    }, []);

    // Auto-duplicate slides for 2-item loop seamlessly
    const displaySlides = (settings.loop && slides.length === 2)
        ? [...slides, ...slides.map(s => ({ ...s, id: s.id + '_clone' }))]
        : slides;

    const goTo = useCallback((index: number) => {
        if (!settings.loop) {
            let nextIndex = index;
            if (nextIndex < 0) nextIndex = 0;
            if (nextIndex >= displaySlides.length) nextIndex = displaySlides.length - 1;

            directionRef.current = nextIndex >= current ? 'next' : 'prev';
            prevIndexRef.current = current;
            setCurrent(nextIndex);
        } else {
            const nextIndex = (index + displaySlides.length) % displaySlides.length;

            // Determine logical direction for infinite loop
            if (current === displaySlides.length - 1 && nextIndex === 0) directionRef.current = 'next';
            else if (current === 0 && nextIndex === displaySlides.length - 1) directionRef.current = 'prev';
            else directionRef.current = nextIndex > current ? 'next' : 'prev';

            prevIndexRef.current = current;
            setCurrent(nextIndex);
        }
    }, [displaySlides.length, settings.loop, current]);

    const next = useCallback(() => goTo(current + 1), [current, goTo]);
    const prev = useCallback(() => goTo(current - 1), [current, goTo]);

    // Auto-advance
    useEffect(() => {
        if (displaySlides.length <= 1 || paused) return;
        if (!settings.loop && current >= displaySlides.length - 1) return; // Stop if not looping and reached end
        timerRef.current = setInterval(next, settings.slider_speed);
        return () => { if (timerRef.current) clearInterval(timerRef.current); };
    }, [displaySlides.length, paused, next, settings.slider_speed, settings.loop, current]);

    const slide = displaySlides[current];
    const showArrows = settings.arrow_visibility === 'visible' || (settings.arrow_visibility === 'hover' && hovering);

    if (loading) {
        return (
            <section className="relative overflow-hidden bg-neutral-200/50 animate-pulse aspect-[1920/550] w-full rounded-none sm:rounded-2xl lg:rounded-3xl">
                <div className="relative z-20 mx-auto max-w-7xl px-4 h-full flex items-center justify-center"></div>
            </section>
        );
    }

    if (slides.length === 0) {
        return null;
    }

    const getSlideClasses = (index: number) => {
        if (settings.slideshow_type === 'fade') {
            return index === current ? 'opacity-100 z-10' : 'opacity-0 z-0';
        }

        const isRTL = settings.slideshow_type === 'slide_right_to_left';

        if (index === current) {
            return 'opacity-100 z-10 translate-x-0';
        }

        // If it's the slide we just left, slide it OUT in the opposite direction
        if (index === prevIndexRef.current) {
            if (directionRef.current === 'next') {
                return `opacity-0 z-0 ${isRTL ? '-translate-x-full' : 'translate-x-full'}`;
            } else {
                return `opacity-0 z-0 ${isRTL ? 'translate-x-full' : '-translate-x-full'}`;
            }
        }

        // For all other inactive slides, stage them IN the direction they will come from
        if (directionRef.current === 'next') {
            return `opacity-0 z-0 ${isRTL ? 'translate-x-full' : '-translate-x-full'}`;
        } else {
            return `opacity-0 z-0 ${isRTL ? '-translate-x-full' : 'translate-x-full'}`;
        }
    };

    return (
        <section
            className="relative overflow-hidden group aspect-[1920/550] w-full flex items-center justify-center rounded-none sm:rounded-2xl lg:rounded-3xl shadow-none sm:shadow-md touch-pan-y"
            onMouseEnter={() => { setPaused(true); setHovering(true); }}
            onMouseLeave={() => { setPaused(false); setHovering(false); }}
            onTouchStart={handleTouchStart}
            onTouchMove={handleTouchMove}
            onTouchEnd={handleTouchEnd}
        >
            {/* ÔöÇÔöÇ Slides ÔöÇÔöÇ */}
            {displaySlides.map((s, i) => (
                <div
                    key={s.id}
                    className={`absolute inset-0 transition-all duration-1000 ease-in-out ${getSlideClasses(i)}`}
                >
                    <Image
                        src={s.image_url}
                        alt={s.headings?.[0]?.text || 'Hero banner'}
                        fill
                        sizes="100vw"
                        className="object-cover object-center"
                        priority={i === 0}
                        loading={i === 0 ? 'eager' : 'lazy'}
                    />
                    <div
                        className="absolute inset-0 bg-gradient-to-b from-black/20 to-black/60"
                        style={{ opacity: s.overlay_opacity }}
                    />
                </div>
            ))}

            {/* ÔöÇÔöÇ Content ÔöÇÔöÇ */}
            {(() => {
                const slideContent = (
                    <>
                        {/* Dynamic Headings */}
                        <div className="animate-fade-in-up space-y-1 sm:space-y-2 mb-2 sm:mb-6 shadow-black/20 drop-shadow-2xl">
                            {slide.headings?.map(h => {
                                const isNum = !isNaN(Number(h.fontSize)) && h.fontSize !== '';
                                return (
                                    <h1 
                                        key={h.id} 
                                        style={{ 
                                            color: h.color, 
                                            fontSize: isNum ? `clamp(1.125rem, 5vw, ${h.fontSize}px)` : undefined 
                                        }} 
                                        className={`font-bold leading-tight ${!isNum ? `text-${h.fontSize}` : ''}`}
                                    >
                                        {h.text}
                                    </h1>
                                )
                            })}
                        </div>

                        {/* Dynamic Subheadings */}
                        <div className="animate-fade-in-up space-y-3 mx-auto max-w-2xl shadow-black/20 drop-shadow-md" style={{ animationDelay: '0.2s' }}>
                            {slide.subheadings?.map(s => {
                                const isNum = !isNaN(Number(s.fontSize)) && s.fontSize !== '';
                                return (
                                    <p 
                                        key={s.id} 
                                        style={{ 
                                            color: s.color, 
                                            fontSize: isNum ? `clamp(0.875rem, 3vw, ${s.fontSize}px)` : undefined 
                                        }} 
                                        className={`leading-relaxed mx-auto max-w-[90%] sm:max-w-none ${!isNum ? `text-${s.fontSize}` : ''}`}
                                    >
                                        {s.text}
                                    </p>
                                )
                            })}
                        </div>

                        {/* Dynamic Buttons */}
                        <div className="animate-fade-in-up mt-3 sm:mt-10 flex flex-wrap justify-center gap-2 sm:gap-4" style={{ animationDelay: '0.4s' }}>
                            {slide.buttons?.map(b => (
                                <Link
                                    key={b.id}
                                    href={b.url || '/products'}
                                    data-hero-btn="true"
                                    onClick={(e) => e.stopPropagation()}
                                    style={{
                                        backgroundColor: b.bgColor !== 'transparent' ? b.bgColor : 'transparent',
                                        color: b.textColor,
                                        borderColor: b.bgColor === 'transparent' ? 'rgba(255,255,255,0.3)' : 'transparent',
                                        borderWidth: b.bgColor === 'transparent' ? '2px' : '0px'
                                    }}
                                    className={`inline-flex items-center gap-2 rounded-lg px-5 py-2 sm:px-8 sm:py-3.5 text-[12px] sm:text-sm font-semibold shadow-lg transition-all hover:brightness-110 hover:-translate-y-0.5 hover:shadow-xl ${b.bgColor === 'transparent' ? 'hover:bg-white/10' : ''}`}
                                >
                                    {b.label}
                                    {b.bgColor !== 'transparent' && <ArrowRight className="h-3 w-3 sm:h-4 sm:w-4" />}
                                </Link>
                            ))}
                        </div>
                    </>
                );

                if (slide.link_url) {
                    return (
                        <Link
                            href={`/${country}${slide.link_url.startsWith('/') ? '' : '/'}${slide.link_url}`}
                            className="relative z-20 mx-auto max-w-7xl px-4 py-2 sm:py-8 md:py-10 lg:py-12 text-center w-full h-full flex flex-col justify-center cursor-pointer"
                        >
                            {slideContent}
                        </Link>
                    );
                }

                return (
                    <div className="relative z-20 mx-auto max-w-7xl px-4 py-2 sm:py-8 md:py-10 lg:py-12 text-center w-full h-full flex flex-col justify-center">
                        {slideContent}
                    </div>
                );
            })()}

            {/* ÔöÇÔöÇ Prev / Next arrows (only if multiple slides AND visibility matches setting) ÔöÇÔöÇ */}
            {displaySlides.length > 1 && settings.arrow_visibility !== 'hidden' && (
                <>
                    {(!(!settings.loop && current === 0)) && (
                        <button
                            onClick={prev}
                            className={`absolute left-2 sm:left-4 top-1/2 -translate-y-1/2 z-30 flex items-center justify-center w-8 h-8 sm:w-10 sm:h-10 rounded-full bg-black/30 hover:bg-black/50 text-white backdrop-blur-sm transition-all duration-300 ${showArrows ? 'opacity-100 translate-x-0' : 'opacity-0 -translate-x-4 pointer-events-none'}`}
                        >
                            <ChevronLeft className="h-4 w-4 sm:h-5 sm:w-5" />
                        </button>
                    )}
                    {(!(!settings.loop && current === displaySlides.length - 1)) && (
                        <button
                            onClick={next}
                            className={`absolute right-2 sm:right-4 top-1/2 -translate-y-1/2 z-30 flex items-center justify-center w-8 h-8 sm:w-10 sm:h-10 rounded-full bg-black/30 hover:bg-black/50 text-white backdrop-blur-sm transition-all duration-300 ${showArrows ? 'opacity-100 translate-x-0' : 'opacity-0 translate-x-4 pointer-events-none'}`}
                        >
                            <ChevronRight className="h-4 w-4 sm:h-5 sm:w-5" />
                        </button>
                    )}
                </>
            )}

            {/* ÔöÇÔöÇ Dot indicators ÔöÇÔöÇ */}
            {slides.length > 1 && (
                <div className="absolute bottom-2 sm:bottom-6 left-1/2 -translate-x-1/2 z-30 flex gap-1.5 sm:gap-2">
                    {slides.map((_, i) => {
                        const isActive = (current % slides.length) === i;
                        return (
                            <button
                                key={i}
                                onClick={() => {
                                    // Calculate closest path to requested index to avoid backwards spinning if cloned
                                    let targetIndex = i;
                                    if (settings.loop && slides.length === 2) {
                                        // We have 4 slides total (0, 1, 2, 3)
                                        // E.g. If current is 3 (index 1), and user clicks 0 (index 0).
                                        // The closest equivalent is 0 or 2, we should go to 0. 
                                        // A simple goTo(i) works robustly as a manual manual jump.
                                        targetIndex = i;
                                    }
                                    goTo(targetIndex);
                                }}
                                className={`rounded-full transition-all duration-300 ${isActive
                                    ? 'bg-vedic-gold w-4 h-1 sm:w-6 sm:h-2'
                                    : 'bg-white/40 hover:bg-white/70 w-1.5 h-1.5 sm:w-2 sm:h-2'
                                    }`}
                            />
                        );
                    })}
                </div>
            )}
        </section>
    );
}

