'use client';

import { useState, useRef, useEffect } from 'react';
import { useRouter, usePathname } from 'next/navigation';
import { useCurrency } from '@/context/CurrencyContext';
import { SUPPORTED_COUNTRIES, buildPath, getCountryFromPathname } from '@/lib/currency';
import { ChevronDown, Globe } from 'lucide-react';

export default function RegionSwitcher({ upward = false }: { upward?: boolean }) {
  const { countryConfig } = useCurrency();
  const router = useRouter();
  const pathname = usePathname();
  const [isOpen, setIsOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const country = getCountryFromPathname(pathname || '/');

  // Close dropdown when clicking outside
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleSelect = (newCountry: string) => {
    setIsOpen(false);
    if (newCountry === country) return;

    // Set cookies (7 days)
    document.cookie = `geo_country=${newCountry}; max-age=${7 * 24 * 60 * 60}; path=/`;
    document.cookie = `geo_manual=true; max-age=${7 * 24 * 60 * 60}; path=/`;
    const currencyMap: Record<string, string> = { us: 'USD', ru: 'RUB', kr: 'KRW' };
    document.cookie = `geo_currency=${currencyMap[newCountry] || 'USD'}; max-age=${7 * 24 * 60 * 60}; path=/`;

    // Strip out the old prefix if it had one
    let strippedPath = pathname || '/';
    if (strippedPath.startsWith(`/${country}`)) {
      strippedPath = strippedPath.slice(country.length + 1) || '/';
    }
    
    // Build new path
    const newPath = buildPath(newCountry, strippedPath);

    // Retain query params if any
    const search = window.location.search;
    router.push(newPath + search);
    router.refresh();
  };

  const currentCountryConfig = SUPPORTED_COUNTRIES[country as keyof typeof SUPPORTED_COUNTRIES];

  return (
    <div className="relative inline-block text-left" ref={dropdownRef}>
      <button
        suppressHydrationWarning
        type="button"
        onClick={() => setIsOpen(!isOpen)}
        className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg border transition-all duration-200 group ${
          upward 
            ? 'border-white/20 hover:border-white/40' 
            : 'border-gray-200 hover:border-gray-300 shadow-sm'
        }`}
        aria-expanded={isOpen}
      >
        <img src={`https://flagcdn.com/w40/${country}.png`} alt={currentCountryConfig.name} className={`h-4 w-6 object-cover rounded-sm border ${upward ? 'border-white/10' : 'border-gray-100'}`} />
        <span className={`text-xs font-bold uppercase tracking-wide ${upward ? 'text-white' : 'text-gray-900'}`}>
          {currentCountryConfig.currency} {currentCountryConfig.symbol}
        </span>
        <ChevronDown className={`h-3.5 w-3.5 transition-transform ${isOpen ? 'rotate-180' : ''} ${upward ? 'text-gray-300' : 'text-gray-500'}`} />
      </button>

      {isOpen && (
        <div className={`absolute left-0 sm:left-auto sm:right-0 w-48 rounded-xl bg-white shadow-xl ring-1 ring-black/5 z-[9999] overflow-hidden ${upward ? 'bottom-full mb-2 origin-bottom-left sm:origin-bottom-right' : 'mt-2 origin-top-left sm:origin-top-right'} animate-in fade-in ${upward ? 'slide-in-from-bottom-2' : 'slide-in-from-top-2'} duration-200`}>
          <div className="p-1">
            {Object.entries(SUPPORTED_COUNTRIES).map(([code, config]) => (
              <button
                key={code}
                onClick={() => handleSelect(code)}
                className={`w-full flex items-center justify-between px-3 py-2.5 text-sm rounded-lg transition-colors ${country === code
                  ? 'bg-[#3B5D3B]/10 text-[#3B5D3B] font-bold'
                  : 'text-gray-700 hover:bg-gray-50 font-medium'
                  }`}
              >
                <div className="flex items-center gap-2.5">
                  <img src={`https://flagcdn.com/w40/${code}.png`} alt={config.name} className="h-4 w-6 object-cover rounded-sm" />
                  <span>{config.currency} {config.symbol}</span>
                </div>
                <span className={`text-[10px] tracking-widest uppercase ${country === code ? 'text-[#3B5D3B]' : 'text-gray-400'}`}>
                  {config.currency}
                </span>
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect, useRef, useCallback } from 'react';
import { useRouter, usePathname, useParams } from 'next/navigation';
import { Search, X, Loader2 } from 'lucide-react';
import { searchAutocomplete, type SearchSuggestion } from '@/lib/api';
import { useCurrency } from '@/context/CurrencyContext';
import { buildPath, getCountryFromPathname } from '@/lib/currency';

interface SearchAutocompleteProps {
    /** Called when the sea rch overlay should close (e.g. mobile) */
    onClose?: () => void;
    /** Placeholder text */
    placeholder?: string;
    /** Additional wrap per classes */
    className?: string;
}

export default function SearchAutocomplete({
    onClose,
    placeholder = 'Search productsÔÇª',
    className = '',
}: SearchAutocompleteProps) {
    const router = useRouter();
    const pathname = usePathname();
    const params = useParams();
    const country = (params.country as string) || 'us';
    const { formatPrice } = useCurrency();
    const [query, setQuery] = useState('');
    const [suggestions, setSuggestions] = useState<SearchSuggestion[]>([]);
    const [isOpen, setIsOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const [activeIndex, setActiveIndex] = useState(-1);

    const inputRef = useRef<HTMLInputElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const debounceRef = useRef<ReturnType<typeof setTimeout>>(undefined);

    // ÔöÇÔöÇ Debounced fetch ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
    const fetchSuggestions = useCallback(async (term: string) => {
        if (term.trim().length < 2) {
            setSuggestions([]);
            setIsOpen(false);
            return;
        }

        setIsLoading(true);
        try {
            const results = await searchAutocomplete(term);
            setSuggestions(results);
            if (results.length === 0) {
                import('@/lib/analytics/gtag').then(({ trackEvent }) => {
                    trackEvent('zero_results_search', { search_term: term });
                });
            }
        } catch {
            setSuggestions([]);
        } finally {
            setIsLoading(false);
        }
    }, []);

    useEffect(() => {
        if (debounceRef.current) clearTimeout(debounceRef.current);

        if (query.trim().length < 2) {
            setSuggestions([]);
            setIsOpen(false);
            setIsLoading(false);
            return;
        }

        setIsLoading(true);
        debounceRef.current = setTimeout(() => {
            fetchSuggestions(query);
        }, 300);

        return () => {
            if (debounceRef.current) clearTimeout(debounceRef.current);
        };
    }, [query, fetchSuggestions]);

    // ÔöÇÔöÇ Click outside to close ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
    useEffect(() => {
        const handleClickOutside = (e: MouseEvent) => {
            if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);
 
    // ÔöÇÔöÇ Scroll lock when open (mobile) ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
    useEffect(() => {
        if (isOpen && window.innerWidth < 768) {
            document.body.style.overflow = 'hidden';
        } else {
            document.body.style.overflow = 'unset';
        }
        return () => {
            document.body.style.overflow = 'unset';
        };
    }, [isOpen]);

    // ÔöÇÔöÇ Static Storefront Pages ÔöÇÔöÇ
    const storePages = [
        { title: 'Home', path: buildPath(country, '/') },
        { title: 'All Products', path: buildPath(country, `/products`) },
        { title: 'Categories', path: buildPath(country, `/categories`) },
        { title: 'About Us', path: buildPath(country, `/about`) },
        { title: 'Contact Support', path: buildPath(country, `/contact`) },
    ];

    const matchedPages = query.trim().length >= 2
        ? storePages.filter(p => p.title.toLowerCase().includes(query.toLowerCase()))
        : [];

    const totalItems = matchedPages.length + suggestions.length;
    const isShowingViewAll = suggestions.length > 0;
    const maxIndex = isShowingViewAll ? totalItems : totalItems - 1;

    // ÔöÇÔöÇ Navigate to product, page, or search page ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
    const goToProduct = (id: string) => {
        setIsOpen(false);
        setQuery('');
        onClose?.();
        router.push(buildPath(country, `/products/${id}`));
    };

    const goToPage = (path: string) => {
        setIsOpen(false);
        setQuery('');
        onClose?.();
        router.push(path);
    };

    const goToSearch = () => {
        if (!query.trim()) return;
        setIsOpen(false);
        onClose?.();
        router.push(buildPath(country, `/search?q=${encodeURIComponent(query.trim())}`));
    };

    // ÔöÇÔöÇ Keyboard navigation ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (!isOpen && e.key !== 'Enter') return;

        switch (e.key) {
            case 'ArrowDown':
                e.preventDefault();
                setActiveIndex(prev => prev < maxIndex ? prev + 1 : 0);
                break;
            case 'ArrowUp':
                e.preventDefault();
                setActiveIndex(prev => prev > 0 ? prev - 1 : maxIndex);
                break;
            case 'Enter':
                e.preventDefault();
                if (activeIndex >= 0) {
                    if (activeIndex < matchedPages.length) {
                        goToPage(matchedPages[activeIndex].path);
                    } else if (activeIndex < totalItems) {
                        goToProduct(suggestions[activeIndex - matchedPages.length].product_id);
                    } else if (isShowingViewAll) {
                        goToSearch();
                    }
                } else {
                    goToSearch();
                }
                break;
            case 'Escape':
                setIsOpen(false);
                setActiveIndex(-1);
                inputRef.current?.blur();
                break;
        }
    };



    return (
        <div ref={containerRef} className={`relative ${className}`}>
            {/* ÔöÇÔöÇÔöÇ Search Input ÔöÇÔöÇÔöÇ */}
            <div className="relative flex items-center">
                <Search className="absolute left-4 h-5 w-5 text-gray-400 pointer-events-none" />
                <input
                    ref={inputRef}
                    type="text"
                    value={query}
                    onChange={e => {
                        const val = e.target.value;
                        setQuery(val);
                        setActiveIndex(-1);
                        if (val.trim().length >= 2 && !isOpen) {
                            setIsOpen(true);
                        }
                        // If they clear the search string manually while on the search page, send them back to home
                        if (val.trim().length === 0 && pathname.endsWith('/search')) {
                            router.push('/');
                        }
                    }}
                    onFocus={() => {
                        if (suggestions.length > 0 || query.trim().length >= 2) setIsOpen(true);
                    }}
                    onKeyDown={handleKeyDown}
                    placeholder={placeholder}
                    autoComplete="off"
                    className="
            w-full pl-11 pr-10 py-[10px] rounded-full
            bg-gray-100 border border-gray-300
            text-sm text-gray-800 placeholder-gray-00
            focus:outline-none focus:ring-2 focus:ring-[#e6e3e4]/30 focus:border-[#4b0f1a]/40
            transition-all duration-200
          "
                />
                {/* Clear / Loading indicator */}
                {query && (
                    <button
                        onClick={() => {
                            setQuery('');
                            setSuggestions([]);
                            setIsOpen(false);
                            inputRef.current?.focus();
                            if (pathname.endsWith('/search')) {
                                router.push('/');
                            }
                        }}
                        className="absolute right-4 p-0.5 text-gray-400 hover:text-gray-600 transition-colors"
                    >
                        {isLoading ? (
                            <Loader2 className="h-5 w-5 animate-spin" />
                        ) : (
                            <X className="h-5 w-5" />
                        )}
                    </button>
                )}
            </div>

            {/* ÔöÇÔöÇÔöÇ Dropdown Panel ÔöÇÔöÇÔöÇ */}
            {isOpen && query.trim().length >= 2 && (
                <div className="
          fixed md:absolute top-[56px] md:top-full left-1/2 -translate-x-1/2 md:left-0 md:translate-x-0 
          w-[96vw] md:w-full z-[300]
          bg-white rounded-b-2xl shadow-[0_25px_70px_rgba(0,0,0,0.2)] border border-gray-100
          max-h-[55vh] md:max-h-[420px] overflow-y-auto
          animate-in fade-in slide-in-from-top-1 duration-200
        ">
                    {/* Pages Section */}
                    {matchedPages.length > 0 && (
                        <div className="py-1">
                            <p className="px-4 py-1.5 text-[10px] font-semibold uppercase tracking-wider text-gray-400 bg-gray-50/50">
                                Pages
                            </p>
                            {matchedPages.map((page, index) => (
                                <button
                                    key={page.path}
                                    onClick={() => goToPage(page.path)}
                                    onMouseEnter={() => setActiveIndex(index)}
                                    className={`
                    w-full flex items-center gap-3 px-4 py-2.5 text-left
                    transition-colors duration-100
                    ${activeIndex === index ? 'bg-[#fdf6ee] text-[#4b0f1a]' : 'hover:bg-gray-50 text-gray-700'}
                  `}
                                >
                                    <div className="flex-shrink-0 w-8 h-8 rounded-lg bg-gray-100 flex items-center justify-center">
                                        <Search className="h-3.5 w-3.5 opacity-40" />
                                    </div>
                                    <span className="text-sm font-medium">{page.title}</span>
                                </button>
                            ))}
                        </div>
                    )}

                    {/* Products Section */}
                    {(suggestions.length > 0 || isLoading) && (
                        <div className="py-1 border-t border-gray-100">
                            <p className="px-4 py-1.5 text-[10px] font-semibold uppercase tracking-wider text-gray-400 bg-gray-50/50">
                                Products
                            </p>
                            {isLoading && suggestions.length === 0 && (
                                <div className="flex items-center gap-2 px-4 py-3 text-sm text-gray-400">
                                    <Loader2 className="h-4 w-4 animate-spin" />
                                    Searching...
                                </div>
                            )}
                            {suggestions.map((item, index) => {
                                const globalIndex = index + matchedPages.length;
                                return (
                                    <button
                                        key={item.product_id}
                                        onClick={() => goToProduct(item.product_id)}
                                        onMouseEnter={() => setActiveIndex(globalIndex)}
                                        className={`
                      w-full flex items-center gap-3 px-3 py-2 sm:px-4 sm:py-3 text-left
                      transition-colors duration-100 border-b border-gray-50 last:border-b-0
                      ${activeIndex === globalIndex ? 'bg-[#fdf6ee]' : 'hover:bg-gray-50'}
                    `}
                                    >
                                        {/* Thumbnail */}
                                        <div className="flex-shrink-0 w-8 h-8 sm:w-10 sm:h-10 rounded-lg bg-gray-100 overflow-hidden">
                                            {item.thumbnail_url ? (
                                                <img
                                                    src={item.thumbnail_url}
                                                    alt={item.product_name}
                                                    className="w-full h-full object-cover"
                                                    loading="lazy"
                                                />
                                            ) : (
                                                <div className="w-full h-full flex items-center justify-center text-gray-300">
                                                    <Search className="h-4 w-4" />
                                                </div>
                                            )}
                                        </div>

                                        {/* Text */}
                                        <div className="flex-1 min-w-0 py-0.5">
                                            <p className="text-[13px] sm:text-sm font-bold text-gray-900 leading-tight mb-0.5">
                                                {item.product_name}
                                            </p>
                                            <p className="text-[10px] sm:text-xs text-gray-500 truncate uppercase tracking-wider font-medium">
                                                {[item.brand, item.category].filter(Boolean).join(' ┬À ')}
                                            </p>
                                        </div>
 
                                        {/* Price */}
                                        {item.price != null && (
                                            <span className="flex-shrink-0 text-[13px] sm:text-sm font-black text-[#4b0f1a] bg-gray-50 px-1.5 py-0.5 rounded-md">
                                                {formatPrice(item.price)}
                                            </span>
                                        )}
                                    </button>
                                );
                            })}
                        </div>
                    )}

                    {/* Empty state */}
                    {!isLoading && matchedPages.length === 0 && suggestions.length === 0 && (
                        <div className="px-4 py-6 text-center text-sm text-gray-400">
                            No results found for &ldquo;{query}&rdquo;
                        </div>
                    )}

                    {/* View All Results Link */}
                    {isShowingViewAll && (
                        <button
                            onClick={goToSearch}
                            onMouseEnter={() => setActiveIndex(totalItems)}
                            className={`
                w-full flex items-center justify-center gap-2 px-4 py-3 border-t border-gray-100
                text-sm font-medium transition-colors duration-100
                ${activeIndex === totalItems
                                    ? 'bg-[#4b0f1a] text-white'
                                    : 'bg-[#fdf6ee] text-[#4b0f1a] hover:bg-[#4b0f1a] hover:text-white'
                                }
                rounded-b-xl
              `}
                        >
                            <Search className="h-3.5 w-3.5" />
                            View all results for &ldquo;{query}&rdquo;
                        </button>
                    )}
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useEffect, useRef, useCallback } from 'react';
import { useRouter, usePathname } from 'next/navigation';
import { Search, X, Loader2, Sparkles } from 'lucide-react';
import { getSearchSuggestions, SearchSuggestion } from '@/lib/api';
import Image from 'next/image';
import Link from 'next/link';

interface SearchBarProps {
    /** Current search value (from URL / filter state) */
    value: string;
    /** Called when user commits a search (Enter or suggestion click) */
    onSearch: (query: string) => void;
    /** Visual variant */
    variant?: 'hero' | 'compact';
    placeholder?: string;
    className?: string;
    autoFocus?: boolean;
    /** If true, calls onSearch immediately as user types (debounced) and hides separate suggestions Panel */
    live?: boolean;
}

function useDebounce<T>(value: T, delay: number): T {
    const [debounced, setDebounced] = useState(value);
    useEffect(() => {
        const t = setTimeout(() => setDebounced(value), delay);
        return () => clearTimeout(t);
    }, [value, delay]);
    return debounced;
}

export default function SearchBar({
    value,
    onSearch,
    variant = 'hero',
    placeholder = 'Search products, brands, or categories...',
    className = '',
    autoFocus = false,
    live = false,
}: SearchBarProps) {
    const router = useRouter();
    const pathname = usePathname();

    const [inputValue, setInputValue] = useState(value);
    const [suggestions, setSuggestions] = useState<SearchSuggestion[]>([]);
    const [suggestionsOpen, setSuggestionsOpen] = useState(false);
    const [loading, setLoading] = useState(false);
    const [activeIndex, setActiveIndex] = useState(-1);

    const inputRef = useRef<HTMLInputElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    // Sync external value to local (e.g., on clearAll)
    useEffect(() => {
        setInputValue(value);
    }, [value]);

    const debouncedInput = useDebounce(inputValue, 300);

    // Fetch suggestions / trigger live search whenever debounced input changes
    useEffect(() => {
        if (debouncedInput.trim().length < 2) {
            setSuggestions([]);
            setSuggestionsOpen(false);
            setLoading(false);
            // If live mode, clear search when input is too short
            if (live && value !== '') onSearch('');
            return;
        }

        if (live) {
            onSearch(debouncedInput.trim());
            return;
        }

        let cancelled = false;
        setLoading(true);
        getSearchSuggestions(debouncedInput).then(results => {
            if (!cancelled) {
                setSuggestions(results);
                setSuggestionsOpen(results.length > 0);
                setLoading(false);
            }
        });
        return () => { cancelled = true; };
    }, [debouncedInput, live]);

    // Close dropdown on outside click
    useEffect(() => {
        const handler = (e: MouseEvent) => {
            if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
                setSuggestionsOpen(false);
                setActiveIndex(-1);
            }
        };
        document.addEventListener('mousedown', handler);
        return () => document.removeEventListener('mousedown', handler);
    }, []);

    const commitSearch = useCallback((q: string) => {
        setSuggestionsOpen(false);
        setActiveIndex(-1);
        onSearch(q.trim());
        inputRef.current?.blur();
    }, [onSearch]);

    const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
        if (!suggestionsOpen) {
            if (e.key === 'Enter') commitSearch(inputValue);
            return;
        }
        if (e.key === 'ArrowDown') {
            e.preventDefault();
            setActiveIndex(i => Math.min(i + 1, suggestions.length - 1));
        } else if (e.key === 'ArrowUp') {
            e.preventDefault();
            setActiveIndex(i => Math.max(i - 1, -1));
        } else if (e.key === 'Enter') {
            e.preventDefault();
            if (activeIndex >= 0 && suggestions[activeIndex]) {
                const s = suggestions[activeIndex];
                setInputValue(s.product_name);
                commitSearch(s.product_name);
            } else {
                commitSearch(inputValue);
            }
        } else if (e.key === 'Escape') {
            setSuggestionsOpen(false);
            setActiveIndex(-1);
        }
    };

    const handleSuggestionClick = (s: SearchSuggestion) => {
        setInputValue(s.product_name);
        commitSearch(s.product_name);
    };

    const handleClear = () => {
        setInputValue('');
        setSuggestions([]);
        setSuggestionsOpen(false);
        onSearch('');
        inputRef.current?.focus();
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        commitSearch(inputValue);
    };

    const isHero = variant === 'hero';

    return (
        <div ref={containerRef} className={`relative ${className}`}>
            <form onSubmit={handleSubmit} className="relative">
                {/* Search icon */}
                <Search className={`absolute left-4 top-1/2 -translate-y-1/2 pointer-events-none ${isHero ? 'h-4 w-4 text-white/60' : 'h-4 w-4 text-gray-400'}`} />

                <input
                    ref={inputRef}
                    type="text"
                    value={inputValue}
                    onChange={e => { setInputValue(e.target.value); setSuggestionsOpen(false); }}
                    onFocus={() => { if (suggestions.length > 0) setSuggestionsOpen(true); }}
                    onKeyDown={handleKeyDown}
                    placeholder={placeholder}
                    autoFocus={autoFocus}
                    autoComplete="off"
                    spellCheck={false}
                    className={
                        isHero
                            ? 'w-full px-5 py-3 pl-12 pr-20 rounded-full bg-white/15 backdrop-blur-sm border border-white/25 text-white text-sm placeholder-white/50 focus:outline-none focus:ring-2 focus:ring-white/30 focus:bg-white/20 transition-all'
                            : 'w-full px-4 py-2.5 pl-10 pr-16 rounded-xl bg-white border border-gray-200 text-gray-800 text-sm placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-[#3d5c3a]/20 focus:border-[#3d5c3a] transition-all'
                    }
                    aria-label="Search products"
                    aria-autocomplete="list"
                    aria-expanded={suggestionsOpen}
                    aria-controls="search-suggestions"
                    role="combobox"
                />

                {/* Right side: loader / clear / submit */}
                <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center gap-1">
                    {loading && <Loader2 className={`h-4 w-4 animate-spin ${isHero ? 'text-white/60' : 'text-[#3d5c3a]'}`} />}
                    {inputValue && !loading && (
                        <button
                            type="button"
                            onClick={handleClear}
                            className={`p-1 rounded-full transition-colors cursor-pointer ${isHero ? 'hover:bg-white/10' : 'hover:bg-gray-100'}`}
                            aria-label="Clear search"
                        >
                            <X className={`h-3.5 w-3.5 ${isHero ? 'text-white/60' : 'text-gray-400'}`} />
                        </button>
                    )}
                    {inputValue && (
                        <button
                            type="submit"
                            className={`text-[10px] font-bold px-2 py-1 rounded-full cursor-pointer transition-colors ${isHero ? 'bg-white/20 text-white hover:bg-white/30' : 'bg-[#3d5c3a] text-white hover:bg-[#2d4a2a]'}`}
                            aria-label="Search"
                        >
                            Go
                        </button>
                    )}
                </div>
            </form>

            {/* Suggestions Dropdown - ONLY show in non-live mode */}
            {!live && suggestionsOpen && suggestions.length > 0 && (
                <div
                    id="search-suggestions"
                    role="listbox"
                    className="absolute top-full left-0 right-0 mt-2 bg-white rounded-2xl shadow-2xl border border-gray-100 overflow-hidden z-50 animate-in fade-in slide-in-from-top-2 duration-150"
                >
                    <div className="px-3 py-2 border-b border-gray-50 flex items-center gap-1.5">
                        <Sparkles className="h-3 w-3 text-[#3d5c3a]" />
                        <span className="text-[10px] font-bold uppercase tracking-widest text-gray-400">Suggestions</span>
                    </div>
                    <ul className="max-h-80 overflow-y-auto">
                        {suggestions.map((s, i) => (
                            <li
                                key={s.product_id}
                                role="option"
                                aria-selected={i === activeIndex}
                                className={`flex items-center gap-3 px-4 py-3 cursor-pointer transition-colors ${i === activeIndex ? 'bg-[#3d5c3a]/5' : 'hover:bg-gray-50'}`}
                                onMouseEnter={() => setActiveIndex(i)}
                                onMouseDown={e => e.preventDefault()} // Prevent blur before click
                                onClick={() => handleSuggestionClick(s)}
                            >
                                {/* Thumbnail */}
                                <div className="h-10 w-10 rounded-xl overflow-hidden bg-gray-100 flex-shrink-0">
                                    {s.thumbnail_url ? (
                                        <img
                                            src={s.thumbnail_url}
                                            alt={s.product_name}
                                            className="h-full w-full object-cover"
                                        />
                                    ) : (
                                        <div className="h-full w-full flex items-center justify-center">
                                            <Search className="h-4 w-4 text-gray-300" />
                                        </div>
                                    )}
                                </div>
                                {/* Text */}
                                <div className="flex-1 min-w-0">
                                    <p className="text-sm font-semibold text-gray-900 truncate">{s.product_name}</p>
                                    <p className="text-xs text-gray-400 truncate">
                                        {s.brand && <span>{s.brand}</span>}
                                        {s.brand && s.category && <span className="mx-1">┬À</span>}
                                        {s.category && <span>{s.category}</span>}
                                    </p>
                                </div>
                                {/* Price */}
                                {s.price != null && (
                                    <span className="text-sm font-bold text-[#3d5c3a] flex-shrink-0">
                                        Ôé╣{Number(s.price).toLocaleString('en-IN')}
                                    </span>
                                )}
                            </li>
                        ))}
                    </ul>
                    <div className="px-4 py-2.5 border-t border-gray-50 bg-gray-50/50">
                        <button
                            onClick={() => commitSearch(inputValue)}
                            className="w-full text-xs font-semibold text-[#3d5c3a] hover:text-[#2d4a2a] transition-colors cursor-pointer text-center"
                        >
                            See all results for &ldquo;{inputValue}&rdquo; ÔåÆ
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import Link from 'next/link';
import { useState, useEffect } from 'react';
import { useParams } from 'next/navigation';
import { getCategories, getFilterOptions } from '@/lib/api';
import { buildPath, getCountryFromPathname } from '@/lib/currency';


interface Category {
  category_id: string;
  parent_id: string | null;
  name: string;
  slug: string;
  image_url?: string;
  children?: Category[];
}

const SecondaryMegaMenuLinks = ({ item, country, topLevelSlug, secondLevelSlug, level = 0 }: { item: Category, country: string, topLevelSlug: string, secondLevelSlug?: string, level?: number }) => {
  const hasChildren = item.children && item.children.length > 0;

  let href = buildPath(country, `/products?category=${topLevelSlug}`);
  if (level === 0) {
    href += `&sub_category=${item.slug}`;
  } else if (level === 1) {
    href += `&sub_category=${secondLevelSlug}&sub_sub_category=${item.slug}`;
  } else {
    href += `&sub_category=${secondLevelSlug}&sub_sub_category=${item.slug}`; // Fallback for deeper levels
  }

  return (
    <div className={`flex flex-col items-start ${level === 0 ? 'mb-6' : 'mb-0'}`}>
      <Link
        href={href}
        className={`transition-colors duration-200 inline-block mb-3 ${level === 0
          ? 'text-[15px] font-black text-black uppercase tracking-wide'
          : 'text-[13px] text-gray-500 font-semibold hover:text-[#91CA35] uppercase tracking-tight'
          }`}
      >

        <span>{item.name}</span>
      </Link>

      {hasChildren && (
        <div className={`flex flex-col gap-1.5 ${level === 0 ? 'mt-1' : ''}`}>
          {item.children!.map(child => (
            <SecondaryMegaMenuLinks
              key={child.category_id}
              item={child}
              country={country}
              topLevelSlug={topLevelSlug}
              secondLevelSlug={level === 0 ? item.slug : secondLevelSlug}
              level={level + 1}
            />
          ))}
        </div>
      )}
    </div>
  );
};

export default function SecondaryNavbar() {
  const params = useParams();
  const country = (Array.isArray(params?.country) ? params?.country[0] : params?.country) || 'us';
  const [categories, setCategories] = useState<Category[]>([]);
  const [brands, setBrands] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    Promise.all([
      getCategories(true), // Fetch the full tree
      getFilterOptions()
    ]).then(([cats, filterOpt]) => {
      if (Array.isArray(cats)) {
        setCategories(cats);
      }
      if (filterOpt && filterOpt.brands) {
        setBrands(filterOpt.brands);
      }
      setLoading(false);
    }).catch(e => console.warn('Failed to init navbar', e));
  }, []);

  const parentCategories = categories.filter(c => !c.parent_id);

  // Group brands by first letter
  const groupedBrands = brands.reduce((acc, brand) => {
    const firstLetter = brand.charAt(0).toUpperCase();
    const key = /[A-Z]/.test(firstLetter) ? firstLetter : '#';
    if (!acc[key]) acc[key] = [];
    acc[key].push(brand);
    return acc;
  }, {} as Record<string, string[]>);

  const alphabetKeys = Object.keys(groupedBrands).sort();

  return (
    <div className="hidden md:block bg-white relative z-[90]">
      <div className="mx-auto max-w-[1500px] px-4 sm:px-6 lg:px-8">
        <div className="flex h-[32px] items-center justify-between text-[14px] uppercase font-bold text-black font-sans">

          <div className="flex items-center gap-0 h-full overflow-x-auto no-scrollbar scroll-smooth">
            {/* Individual Categories */}
            {!loading && parentCategories.map((parent, index) => {
              const subcats = parent.children || [];

              return (
                <div key={parent.category_id} className="flex items-center h-full">
                  <div className="group/nav-item h-full flex items-center shrink-0">
                    <Link
                      href={buildPath(country, `/products?category=${parent.slug}`)}
                      className="flex items-center h-full px-1.5 transition-colors cursor-pointer border-b-2 border-transparent group-hover/nav-item:border-[#91CA35] hover:text-[#91CA35]"
                    >
                      {parent.name}
                    </Link>

                    {/* Subcategories Dropdown (Mega Menu) */}
                    {subcats.length > 0 && (
                      <div className="absolute top-full left-0 w-[97vw] rounded-br-xl bg-white shadow-[0_15px_50px_rgba(0,0,0,0.15)] opacity-0 invisible group-hover/nav-item:opacity-100 group-hover/nav-item:visible transition-all duration-300 z-[100]">
                        <div className="mx-auto px-8 pb-8 pt-4 flex flex-col gap-6 min-h-[250px] relative">
                          {/* Category Name on top */}
                          <div className="border-b border-[#3B5D3B]/10 pb-3">
                            <h3 className="text-xl font-extrabold text-[#FFD801]">{parent.name}</h3>
                          </div>

                          <div className="flex flex-col justify-between flex-1">
                            {/* Subcategories and Sub-subcategories below */}
                            <div className="columns-1 sm:columns-2 md:columns-3 lg:columns-4 xl:columns-5 gap-10 mb-2">
                              {subcats.map(sub => (
                                <div key={sub.category_id} className="break-inside-avoid">
                                  <SecondaryMegaMenuLinks item={sub} country={country} topLevelSlug={parent.slug} />
                                </div>
                              ))}
                            </div>

                            {/* "View All" link positioned at the bottom right */}
                            <div className="flex justify-end mt-auto pt-4 border-t border-gray-50/50">
                              <Link href={buildPath(country, `/products?category=${parent.slug}`)} className="text-[#FF0000] hover:text-[#CC0000] flex items-center gap-1 font-bold text-[13px] group/view-all">
                                Explore All {parent.name} <span className="transition-transform group-hover/view-all:translate-x-1">ÔåÆ</span>
                              </Link>
                            </div>
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              );
            })}

            {/* Vertical Divider before Brands */}
            {!loading && parentCategories.length > 0 && (
              <div className="h-4 w-[1px] bg-black/10 self-center shrink-0 mx-2" />
            )}

            {/* Brands A-Z Dropdown */}
            <div className="group/nav-item h-full flex items-center shrink-0">
              <span className="flex items-center h-full px-1.5 hover:text-[#91CA35] transition-colors cursor-pointer border-b-2 border-transparent group-hover/nav-item:border-[#91CA35]">
                Brands A-Z
              </span>

              {/* Brands Mega Dropdown */}
              {!loading && brands.length > 0 && (
                <div className="absolute top-full left-0 w-[90vw] rounded-br-xl bg-white shadow-[0_15px_50px_rgba(0,0,0,0.15)] opacity-0 invisible group-hover/nav-item:opacity-100 group-hover/nav-item:visible transition-all duration-300 z-[100]">
                  <div className="mx-auto px-8 pt-4 pb-8 max-h-[450px] overflow-y-auto w-full">
                    <div className="flex items-center justify-between border-b border-gray-100 pb-2 mb-4">
                      <h3 className="text-xl font-bold text-gray-900">All Brands A-Z</h3>
                      <div className="flex gap-2 invisible md:visible flex-wrap">
                        {alphabetKeys.map(letter => (
                          <a key={letter} href={`#brand-${letter}`} className="text-xs font-bold text-gray-400 hover:text-[#3B5D3B] py-1 px-2">{letter}</a>
                        ))}
                      </div>
                    </div>

                    <div className="columns-1 sm:columns-2 md:columns-3 lg:columns-4 xl:columns-5 gap-8">
                      {alphabetKeys.map(letter => (
                        <div key={letter} id={`brand-${letter}`} className="break-inside-avoid mb-8 scroll-mt-6">
                          <h4 className="text-[18px] font-black text-black mb-3 inline-block px-1 min-w-[30px]">{letter}</h4>
                          <ul className="space-y-2 flex flex-col">
                            {groupedBrands[letter].map(brand => (
                              <li key={brand}>
                                <Link
                                  href={buildPath(country, `/products?brand=${encodeURIComponent(brand)}`)}
                                  className="text-[13px] text-gray-600 font-medium hover:text-[#91CA35] transition-all block truncate"
                                >
                                  {brand}
                                </Link>
                              </li>
                            ))}
                          </ul>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>

          <div className="flex items-center h-full text-[13px] font-bold tracking-wide shrink-0 ml-4">
            <div className="h-4 w-[1px] bg-black/10 self-center mx-3" />
            <Link href={buildPath(country, `/products?bestSeller=true`)} className="text-black hover:text-[#91CA35] h-full flex items-center">Best Sellers</Link>
            <div className="h-4 w-[1px] bg-black/10 self-center mx-3" />
            <Link href={buildPath(country, `/products?newArrival=true`)} className="text-[#FF0000] font-bold h-full flex items-center gap-1.5 group">
              <span className="flex h-2 w-2 rounded-full bg-[#FF0000] animate-promo-blink shadow-[0_0_8px_rgba(255,0,0,0.5)]"></span>
              New Arrivals
            </Link>
          </div>
        </div>
      </div>
      <div className="w-full h-[3px] bg-[#91CA35]" />
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { getSimilarProducts } from '@/lib/api';
import { Product } from '@/types';
import { Sparkles } from 'lucide-react';
import ProductReel from '@/components/ProductReel';

interface SimilarProductsProps {
    productId: string;
}

export default function SimilarProducts({ productId }: SimilarProductsProps) {
    const [products, setProducts] = useState<Product[]>([]);
    const [loading, setLoading] = useState(true);
    const [prevId, setPrevId] = useState(productId);

    if (productId !== prevId) {
        setPrevId(productId);
        setProducts([]);
        setLoading(true);
    }

    useEffect(() => {
        let cancelled = false;

        getSimilarProducts(productId, 12)
            .then(data => {
                if (!cancelled) {
                    setProducts(data);
                    setLoading(false);
                }
            })
            .catch(() => {
                if (!cancelled) setLoading(false);
            });

        return () => { cancelled = true; };
    }, [productId]);

    return (
        <ProductReel
            title="Similar Products"
            products={products}
            loading={loading}
        />
    );
}

'use client';

import { useState, useEffect } from 'react';
import toast from 'react-hot-toast';

interface SocialLoginButtonsProps {
    onLoadingChange?: (loading: boolean) => void;
    disabled?: boolean;
}

const GoogleIcon = () => (
    <svg className="w-5 h-5" viewBox="0 0 24 24">
        <path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92a5.06 5.06 0 0 1-2.2 3.32v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.1z" />
        <path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" />
        <path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" />
        <path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" />
    </svg>
);

export default function SocialLoginButtons({ onLoadingChange, disabled }: SocialLoginButtonsProps) {
    const [loadingProvider, setLoadingProvider] = useState<string | null>(null);

    // ÔöÇÔöÇ Direct Google OAuth (no Clerk) ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
    const handleGoogleLogin = () => {
        setLoadingProvider('google');
        onLoadingChange?.(true);

        const clientId = process.env.NEXT_PUBLIC_GOOGLE_CLIENT_ID;
        const redirectUri = process.env.NEXT_PUBLIC_GOOGLE_REDIRECT_URI;

        if (!clientId || !redirectUri) {
            toast.error('Google login is not configured. Please contact support.');
            setLoadingProvider(null);
            onLoadingChange?.(false);
            return;
        }

        const oauthParams = new URLSearchParams({
            client_id: clientId,
            redirect_uri: redirectUri,
            response_type: 'code',
            scope: 'openid email profile',
            access_type: 'offline',
            prompt: 'select_account',
        });

        window.location.href = `https://accounts.google.com/o/oauth2/v2/auth?${oauthParams.toString()}`;
    };

    // Listen for custom trigger events from parent
    useEffect(() => {
        const handleExternalTrigger = (e: React.MouseEvent) => {
            const provider = e.detail;
            if (provider === 'google') handleGoogleLogin();
        };

        window.addEventListener('trigger-social-login', handleExternalTrigger);
        return () => window.removeEventListener('trigger-social-login', handleExternalTrigger);
    }, []);

    return (
        <div className="space-y-3">
            <button
                type="button"
                data-social="google"
                onClick={handleGoogleLogin}
                disabled={disabled || !!loadingProvider}
                className="w-full flex items-center justify-center gap-3 rounded-lg border px-4 py-3 text-sm font-semibold transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed bg-white hover:bg-gray-50 border-gray-300 text-gray-700"
            >
                {loadingProvider === 'google' ? (
                    <div className="w-5 h-5 border-2 border-current/30 border-t-current rounded-full animate-spin" />
                ) : (
                    <GoogleIcon />
                )}
                <span>Continue with Google</span>
            </button>
        </div>
    );
}

'use client';
import Link from 'next/link';
import { getLoyaltyWallet, getLoyaltyTransactions } from '@/lib/api';
import { useState, useEffect } from 'react';
import { Wallet, Star, History, ArrowUpRight, ArrowDownRight, Award, Loader2, Info, Check } from 'lucide-react';
import toast from 'react-hot-toast';
import { useAuth } from '@/context/AuthContext';

interface MyWalletProps {
    customerId: string;
}

export default function MyWallet({ customerId }: MyWalletProps) {
    const { user } = useAuth();
    const [loading, setLoading] = useState(true);
    const [wallet, setWallet] = useState<Record<string, unknown> | null>(null);
    const [transactions, setTransactions] = useState<Record<string, unknown>[]>([]);

    useEffect(() => {
        if (customerId) {
            fetchWalletData();
        }
    }, [customerId]);

    const fetchWalletData = async () => {
        try {
            const [walletData, txnsData] = await Promise.all([
                getLoyaltyWallet(),
                getLoyaltyTransactions(50, 0)
            ]);

            if (walletData) setWallet(walletData);
            if (txnsData) setTransactions(txnsData);
        } catch (error) {
            toast.error('Failed to load wallet data.');
        } finally {
            setLoading(false);
        }
    };

    // If completely uninitialized and not in cache, wait for load
    if (loading && !user?.loyalty_tier && !wallet) {
        return (
            <div className="flex justify-center items-center py-20">
                <Loader2 className="h-8 w-8 animate-spin text-burgundy" />
            </div>
        );
    }

    if (!loading && (!wallet || !wallet.wallet) && !user?.loyalty_tier) {
        return (
            <div className="text-center py-12 p-6 bg-white rounded-[2rem] border border-[#F0EAD6] shadow-sm animate-fadeIn">
                <div className="w-20 h-20 bg-[#FDFBF7] rounded-full flex items-center justify-center mx-auto mb-6 border border-[#91c934]/10">
                    <Wallet className="h-10 w-10 text-[#91c934]/30" />
                </div>
                <h3 className="text-2xl font-bold text-[#1f2937]">Sanctuary Not Activated</h3>
                <p className="text-[#4A5D4A] mt-2 max-w-sm mx-auto">Embrace the path of wellness. Your ritual journal begins with your first soulful purchase.</p>
                <button
                    onClick={() => window.location.href = '/'}
                    className="mt-8 px-8 py-3 bg-[#91c934] text-white font-bold rounded-xl hover:bg-[#7ab52a] transition-all shadow-lg text-xs uppercase tracking-widest"
                >
                    Begin Your Journey
                </button>
            </div>
        );
    }

    const walletObj = wallet?.wallet || {};
    const tierObj = wallet?.tier || {};
    const { balance, lifetime_earned, lifetime_redeemed } = walletObj;
    const { tier_name, benefits, badge_color } = tierObj;

    // Auth context fallback fields
    const displayTier = tier_name || user?.loyalty_tier || 'Bronze';
    const displayBalance = balance ?? user?.wallet_balance ?? 0;

    return (
        <div className="space-y-8 w-full max-w-5xl mx-auto animate-fadeIn">
            {/* Header Section */}
            <div className="relative group">
                <div className="flex items-center gap-4 mb-2">
                    <div className="p-3 bg-[#91c934]/10 rounded-xl border border-[#91c934]/20 text-[#91c934] group-hover:bg-[#91c934] group-hover:text-white transition-all duration-500 shadow-sm">
                        <Wallet className="h-6 w-6" />
                    </div>
                    <div>
                        <h2 className="text-3xl font-bold text-[#1f2937] tracking-tight">Vedic Ritual Rewards</h2>
                        <p className="text-sm text-[#4A5D4A] font-medium flex items-center gap-1.5 mt-1">
                            <Star className="h-3.5 w-3.5 text-[#FFD801] fill-[#FFD801]" />
                            Your journey towards holistic wellness, rewarded.
                        </p>
                    </div>
                </div>
            </div>

            {/* Wallet Overview Cards */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                {/* Available Balance - The Master Card */}
                <div className="lg:col-span-2 bg-gradient-to-br from-[#5a9a1e] to-[#91c934] text-white p-8 rounded-[2.5rem] shadow-2xl relative overflow-hidden flex flex-col justify-between min-h-[280px] group border border-[#D4A847]/20 hover:border-[#D4A847]/40 transition-all duration-700">
                    {/* Leaf Pattern Background */}
                    <div className="absolute top-0 right-0 w-64 h-64 opacity-[0.03] pointer-events-none transform translate-x-12 -translate-y-12 rotate-12 group-hover:rotate-45 transition-transform duration-1000">
                        <Star className="w-full h-full text-[#D4A847]" />
                    </div>

                    <div className="relative z-10">
                        <div className="flex items-center justify-between mb-4">
                            <p className="text-white text-[10px] font-bold tracking-[0.3em] uppercase">Active Plan</p>
                            <div className="h-2 w-2 rounded-full bg-[#D4A847] shadow-[0_0_10px_#D4A847] animate-pulse" />
                        </div>
                        <h3 className="text-4xl md:text-5xl font-bold text-[#FFD801] mb-4 tracking-tight">
                            {displayTier} Ritualist
                        </h3>
                        {benefits && Array.isArray(benefits) && benefits.length > 0 ? (
                            <p className="text-sm text-white leading-relaxed max-w-md font-medium">
