                                                    {txn.reference_type === 'order' && (
                                                        <span className="h-1 w-1 rounded-full bg-[#D4A847]" />
                                                    )}
                                                    {txn.reference_type === 'order' && (
                                                        <p className="text-[10px] font-bold text-[#D4A847] uppercase tracking-widest">
                                                            Ref: #{txn.reference_id?.substring(0, 8)}
