'use client';

import { useState, useRef } from 'react';
import { Play } from 'lucide-react';

interface LazyVideoProps {
    /** Video source URL */
    src: string;
    /** Poster image URL */
    poster?: string;
    /** Alt text / title */
    title?: string;
    /** CSS class for the container */
    className?: string;
    /** Width of the video */
    width?: number;
    /** Height of the video */
    height?: number;
}

/**
 * Video component that does NOT preload.
 * Shows a poster image with a play button overlay.
 * Loads and plays the actual video only when the user clicks play.
 */
export default function LazyVideo({
    src,
    poster,
    title,
    className = '',
    width,
    height,
}: LazyVideoProps) {
    const [isPlaying, setIsPlaying] = useState(false);
    const videoRef = useRef<HTMLVideoElement>(null);

    const handlePlay = () => {
        setIsPlaying(true);
        // Wait for next tick so the video element mounts
        setTimeout(() => {
            videoRef.current?.play();
        }, 0);
    };

    return (
        <div
            className={`relative overflow-hidden bg-black ${className}`}
            style={{ aspectRatio: width && height ? `${width}/${height}` : '16/9' }}
        >
            {!isPlaying ? (
                /* Poster + Play button */
                <button
                    onClick={handlePlay}
                    className="relative w-full h-full group cursor-pointer"
                    aria-label={`Play video: ${title || 'Product video'}`}
                >
                    {poster ? (
                        <img
                            src={poster}
                            alt={title || 'Video thumbnail'}
                            className="w-full h-full object-cover"
                            loading="lazy"
                        />
                    ) : (
                        <div className="w-full h-full bg-neutral-900 flex items-center justify-center">
                            <span className="text-neutral-500 text-sm">Video</span>
                        </div>
                    )}
                    {/* Play overlay */}
                    <div className="absolute inset-0 flex items-center justify-center bg-black/30 group-hover:bg-black/40 transition-colors">
                        <div className="flex items-center justify-center w-16 h-16 rounded-full bg-white/90 shadow-lg group-hover:scale-110 transition-transform">
                            <Play className="h-7 w-7 text-burgundy ml-1" fill="currentColor" />
                        </div>
                    </div>
                </button>
            ) : (
                /* Actual video (loaded on demand) */
                <video
                    ref={videoRef}
                    src={src}
                    poster={poster}
                    controls
                    preload="none"
                    className="w-full h-full object-contain"
                    title={title}
                >
                    Your browser does not support the video tag.
                </video>
            )}
        </div>
    );
}

'use client';

import StarRating from './StarRating';
import { ThumbsUp, ThumbsDown, BadgeCheck, Flag, CornerDownRight } from 'lucide-react';
import { voteHelpful, reportReview } from '@/lib/api';
import { useState } from 'react';
import toast from 'react-hot-toast';

export interface Review {
    review_id: string;
    rating: number;
    title?: string;
    body?: string;
    reviewer_name: string;
    is_verified_purchase?: boolean;
    helpful_count?: number;
    admin_reply?: string;
    admin_reply_at?: string;
    created_at: string;
    own_vote?: 'up' | 'down' | null;
    has_reported?: boolean;
}

interface ReviewCardProps {
    review: Review;
}

export default function ReviewCard({ review }: ReviewCardProps) {
    const [helpfulCount, setHelpfulCount] = useState(review.helpful_count ?? 0);
    const [voteStatus, setVoteStatus] = useState<'none' | 'up' | 'down'>(review.own_vote || 'none');

    // Reporting state
    const [isReporting, setIsReporting] = useState(false);
    const [reportReason, setReportReason] = useState('');
    const [isSubmittingReport, setIsSubmittingReport] = useState(false);
    const [hasReported, setHasReported] = useState(!!review.has_reported);

    const handleVote = async (type: 'up' | 'down') => {
        if (voteStatus === type) return; // Prevent double voting the same way

        // Optimistic UI update
        const previousVote = voteStatus;
        const previousCount = helpfulCount;

        setVoteStatus(type);
        if (type === 'up') {
            setHelpfulCount(c => c + (previousVote === 'down' ? 2 : 1));
        } else {
            setHelpfulCount(c => c - (previousVote === 'up' ? 2 : 1));
        }

        try {
            const res = await voteHelpful(review.review_id, type);
            if (!res || res.success === false) {
                toast.error(res?.message || 'Failed to register vote. Please log in.');
                setVoteStatus(previousVote);
                setHelpfulCount(previousCount);
            }
        } catch (error) {
            // Revert on network error
            toast.error('Network error. Please try again.');
            setVoteStatus(previousVote);
            setHelpfulCount(previousCount);
        }
    };

    const handleReport = async () => {
        if (!reportReason.trim()) {
            toast.error('Please provide a reason for reporting.');
            return;
        }

        setIsSubmittingReport(true);
        try {
            const res = await reportReview(review.review_id, reportReason);
            if (res && res.success === false) {
                toast.error(res.message || 'Failed to submit report. Ensure you are logged in.');
            } else {
                toast.success('Review reported successfully.');
                setHasReported(true);
                setIsReporting(false);
            }
        } catch (error) {
            toast.error('Network error. Please try again.');
        } finally {
            setIsSubmittingReport(false);
        }
    };

    const dateStr = new Date(review.created_at).toLocaleDateString('en-US', {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
    });

    return (
        <div className="bg-white p-6 rounded-2xl shadow-[0_4px_24px_rgba(0,0,0,0.04)] group mb-4">
            {/* Header */}
            <div className="flex items-center justify-between gap-4 mb-4">
                <StarRating value={review.rating} size="sm" />
                <span className="text-xs font-semibold text-gray-400 uppercase tracking-widest">{dateStr}</span>
            </div>

            {/* Body */}
            {review.body && (
                <p className="text-[15px] font-medium text-gray-800 leading-relaxed italic">
                    &quot;{review.body}&quot;
                </p>
            )}

            {/* Admin Reply */}
            {review.admin_reply && (
                <div className="mt-4 ml-4 bg-[#91C934]/5 p-4 rounded-xl border-l-2 border-[#91C934]">
                    <div className="flex items-center gap-2 mb-1">
                        <CornerDownRight size={14} className="text-[#91C934]" />
                        <span className="text-xs font-bold uppercase tracking-wider text-[#91C934]">Vedashi Response</span>
                        {review.admin_reply_at && (
                            <span className="text-xs text-gray-500 font-medium ml-1">
                                {new Date(review.admin_reply_at).toLocaleDateString('en-US', {
                                    month: 'short', day: 'numeric', year: 'numeric'
                                })}
                            </span>
                        )}
                    </div>
                    <p className="text-[14px] text-gray-600 ml-5 leading-relaxed">
                        {review.admin_reply}
                    </p>
                </div>
            )}

            {/* Footer */}
            <div className="mt-6 flex items-center justify-between gap-4 pt-4 border-t border-gray-100">
                <div className="flex items-center gap-3">
                    <div className="h-8 w-8 rounded-full bg-[#91C934] text-white flex items-center justify-center text-xs font-bold shadow-sm">
                        {review.reviewer_name.charAt(0).toUpperCase()}
                    </div>
                    <div>
                        <span className="block text-sm font-bold text-gray-900">{review.reviewer_name}</span>
                        {review.is_verified_purchase && (
                            <span className="flex items-center gap-1 text-[10px] text-gray-500 font-medium">
                                <BadgeCheck size={12} className="text-[#91C934]" />
                                Verified Purchase
                            </span>
                        )}
                    </div>
                </div>

                <div className="ml-auto flex items-center gap-3">
                    {/* Helpful up/down votes */}
                    <div className="flex items-center gap-2 bg-neutral-50 px-2.5 py-1 rounded-full border border-neutral-100">
                        <button
                            onClick={() => handleVote('up')}
                            className={`flex items-center transition-colors hover:text-[#91C934] ${voteStatus === 'up' ? 'text-[#91C934]' : ''}`}
                            aria-label="Upvote review"
                        >
                            <ThumbsUp size={14} className={voteStatus === 'up' ? 'fill-current' : ''} />
                            <span className="ml-1.5 min-w-[12px] text-center font-medium text-neutral-500">
                                {helpfulCount > 0 ? helpfulCount : 0}
                            </span>
                        </button>
                        <div className="w-[1px] h-3 bg-neutral-200"></div>
                        <button
                            onClick={() => handleVote('down')}
                            className={`flex items-center transition-colors hover:text-red-500 ${voteStatus === 'down' ? 'text-red-500' : ''}`}
                            aria-label="Downvote review"
                        >
                            <ThumbsDown size={14} className={voteStatus === 'down' ? 'fill-current' : ''} />
                        </button>
                    </div>

                    {/* Report button */}
                    <button
                        onClick={() => setIsReporting(!isReporting)}
                        className={`flex items-center gap-1 transition-colors ${isReporting || hasReported ? 'text-red-500' : 'text-neutral-400 hover:text-red-500'}`}
                        title="Report this review"
                        disabled={hasReported}
                    >
                        <Flag size={13} className={hasReported ? "text-red-400" : ""} />
                        <span className="text-xs font-medium">{hasReported ? 'Reported' : 'Report'}</span>
                    </button>
                </div>
            </div>

            {/* Report Form */}
            {isReporting && !hasReported && (
                <div className="mt-3 p-3 bg-red-50 border border-red-100 rounded-md text-sm">
                    <p className="font-medium text-red-800 mb-2">Report Review</p>
                    <textarea
                        value={reportReason}
                        onChange={(e) => setReportReason(e.target.value)}
                        placeholder="Why are you reporting this review? (e.g. harmful language, spam)"
                        className="w-full text-sm border-gray-200 rounded p-2 mb-2 resize-none focus:ring-red-500 focus:border-red-500 bg-white"
                        rows={2}
                    />
                    <div className="flex justify-end gap-2">
                        <button
                            onClick={() => setIsReporting(false)}
                            className="px-3 py-1.5 text-xs font-medium text-neutral-600 hover:bg-neutral-100 rounded transition-colors"
                        >
                            Cancel
                        </button>
                        <button
                            onClick={handleReport}
                            disabled={isSubmittingReport || !reportReason.trim()}
                            className="px-3 py-1.5 text-xs font-medium bg-red-600 text-white rounded hover:bg-red-700 disabled:opacity-50 transition-colors"
                        >
                            {isSubmittingReport ? 'Submitting...' : 'Submit Report'}
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import StarRating from './StarRating';
import ReviewCard from './ReviewCard';
import ReviewForm from './ReviewForm';
import { getProductReviews, getRatingSummary, getMyReviewForProduct } from '@/lib/api';
import { useAuth } from '@/context/AuthContext';
import { useCurrency } from '@/context/CurrencyContext';
import { MessageSquare } from 'lucide-react';

interface RatingSummary {
    total_reviews: number;
    average_rating: number;
    distribution: Record<number, number>;
}

interface Review {
    review_id: string;
    rating: number;
    title?: string;
    body?: string;
    reviewer_name: string;
    is_verified_purchase?: boolean;
    helpful_count?: number;
    created_at: string;
    own_vote?: 'up' | 'down' | null;
    has_reported?: boolean;
}

interface ReviewSectionProps {
    productId: string;
    product?: Record<string, unknown>;
    selectedVariant?: Record<string, unknown>;
    onAddToCart?: (e: React.MouseEvent<HTMLButtonElement>) => void;
}

const SORT_OPTIONS = [
    { label: 'Most Recent', value: 'recent' },
    { label: 'Most Helpful', value: 'helpful' },
    { label: 'Highest Rated', value: 'highest' },
    { label: 'Lowest Rated', value: 'lowest' },
];

export default function ReviewSection({ productId, product, selectedVariant, onAddToCart }: ReviewSectionProps) {
    const { isAuthenticated } = useAuth();
    const { formatPrice } = useCurrency();

    const [summary, setSummary] = useState<RatingSummary | null>(null);
    const [reviews, setReviews] = useState<Review[]>([]);
    const [myReview, setMyReview] = useState<Review | null>(null);
    const [sort, setSort] = useState('recent');
    const [loading, setLoading] = useState(true);

    const fetchData = useCallback(async () => {
        setLoading(true);
        try {
            const [reviewsRes, summaryRes] = await Promise.all([
                getProductReviews(productId, { sort, limit: 50 }),
                getRatingSummary(productId),
            ]);

            if (reviewsRes.success && reviewsRes.data) {
                setReviews(reviewsRes.data.reviews ?? reviewsRes.data ?? []);
                if (reviewsRes.data.summary) {
                    setSummary(reviewsRes.data.summary);
                }
            }
            if (summaryRes.success && summaryRes.data) {
                setSummary(summaryRes.data);
            }

            // Check if user has an existing review
            if (isAuthenticated) {
                try {
                    const myRes = await getMyReviewForProduct(productId);
                    if (myRes.success && myRes.data?.has_reviewed) {
                        setMyReview(myRes.data.review);
                    } else {
                        setMyReview(null);
                    }
                } catch { setMyReview(null); }
            }
        } catch (err) {
            console.error('[Reviews] Failed to fetch:', err);
        } finally {
            setLoading(false);
        }
    }, [productId, sort, isAuthenticated]);

    useEffect(() => {
        fetchData();
    }, [fetchData]);

    const basePrice = selectedVariant?.price ?? product?.price ?? 0;

    return (
        <section className="pt-6">
            {/* Section header */}
            <div className="mb-10 max-w-2xl">
                <h2 className="text-3xl font-bold text-gray-900 mb-2">Community Experiences</h2>
                <p className="text-[15px] text-gray-500">Stories of restoration and balance from our collective.</p>
            </div>

            {loading ? (
                <div className="space-y-4">
                    {Array.from({ length: 3 }).map((_, i) => (
                        <div key={i} className="h-20 animate-pulse rounded-lg bg-neutral-100" />
                    ))}
                </div>
            ) : (
                <div className="grid gap-10 lg:grid-cols-[1fr_320px] items-stretch">
                    {/* ÔöÇÔöÇ Left: Reviews + Form ÔöÇÔöÇ */}
                    <div className="flex flex-col">
                        {/* Sort */}
                        {reviews.length > 0 && (
                            <div className="mb-8 flex items-center justify-between">
                                <p className="text-sm font-semibold text-gray-500 uppercase tracking-wider">
                                    {reviews.length} Review{reviews.length !== 1 ? 's' : ''}
                                </p>
                                <select
                                    value={sort}
                                    onChange={e => setSort(e.target.value)}
                                    className="rounded-full border border-gray-200 px-4 py-2 text-sm font-medium text-gray-700 focus:outline-none focus:border-[#91C934] focus:ring-1 focus:ring-[#91C934] bg-white cursor-pointer hover:bg-gray-50 transition-colors"
                                >
                                    {SORT_OPTIONS.map(o => (
                                        <option key={o.value} value={o.value}>{o.label}</option>
                                    ))}
                                </select>
                            </div>
                        )}

                        {/* Review list ÔÇöÔÇö flex-1 to push form down */}
                        <div className="flex-1 pb-10">
                            {reviews.length > 0 ? (
                                <div className="space-y-6">
                                    {reviews.map(r => (
                                        <ReviewCard key={r.review_id} review={r} />
                                    ))}
                                </div>
                            ) : (
                                <div className="rounded-xl border border-dashed border-neutral-200 py-12 text-center bg-white h-full flex flex-col justify-center">
                                    <MessageSquare className="mx-auto h-8 w-8 text-neutral-300 mb-2" />
                                    <p className="text-neutral-500 text-sm">No reviews yet. Be the first to share your thoughts!</p>
                                </div>
                            )}
                        </div>

                        {/* Review form ÔÇöÔÇö Bottom-aligned */}
                        <ReviewForm
                            productId={productId}
                            existingReview={myReview ? {
                                rating: myReview.rating,
                                title: myReview.title,
                                body: myReview.body,
                            } : null}
                            onSubmitted={fetchData}
                        />
                    </div>

                    {/* ÔöÇÔöÇ Right: Sidebar (Summary + Product Card) ÔöÇÔöÇ */}
                    <div className="flex flex-col">
                        <div className="lg:sticky lg:top-24 flex-1 flex flex-col items-stretch">
                            {/* Rating Summary Card (TOP) */}
                            <div className="rounded-xl border border-neutral-200 bg-white p-6 shadow-sm">
                                <div className="text-center">
                                    <p className="text-5xl font-bold text-gray-900 leading-none">
                                        {(summary?.average_rating ?? 0).toFixed(1)}
                                    </p>
                                    <StarRating
                                        value={summary?.average_rating ?? 0}
                                        size="lg"
                                        className="justify-center mt-3"
                                    />
                                    <p className="mt-3 text-sm text-neutral-500 font-medium">
                                        Based on {summary?.total_reviews ?? 0} review{(summary?.total_reviews ?? 0) !== 1 ? 's' : ''}
                                    </p>
                                </div>

                                {/* Star distribution bars */}
                                {summary && summary.total_reviews > 0 && (
                                    <div className="mt-8 space-y-2.5">
                                        {[5, 4, 3, 2, 1].map(star => {
                                            const count = summary.distribution[star] ?? 0;
                                            const pct = (count / (summary.total_reviews || 1)) * 100;
                                            return (
                                                <div key={star} className="flex items-center gap-3 text-sm">
                                                    <span className="w-3 text-right text-gray-500 font-medium">{star}</span>
                                                    <StarRating value={star} size="sm" className="flex-shrink-0" />
                                                    <div className="flex-1 h-1.5 bg-gray-100 rounded-full overflow-hidden">
                                                        <div
                                                            className="h-full rounded-full bg-[#91C934] transition-all duration-500"
                                                            style={{ width: `${pct}%` }}
                                                        />
                                                    </div>
                                                    <span className="w-8 text-right text-xs font-semibold text-gray-400">{count}</span>
                                                </div>
                                            );
                                        })}
                                    </div>
                                )}
                            </div>

                            {/* Spacing element to push product card to the very bottom */}
                            <div className="flex-1 min-h-[40px]" />

                            {/* Ô£à STICKY PRODUCT CARD ÔÇöÔÇö Balanced & Context-Aware */}
                            {product && (
                                <div className="overflow-hidden rounded-xl border border-neutral-200 bg-white shadow-sm transition-all hover:shadow-md">
                                    <div className="p-5">
                                        <div className="aspect-square w-full mb-4 overflow-hidden rounded-lg bg-gray-50 flex items-center justify-center">
                                            <img 
                                                src={product.thumbnail_url || product.images?.[0] || '/placeholder.png'} 
                                                alt={product.product_name}
                                                className="max-h-full max-w-full object-contain p-4 transition-transform hover:scale-110 duration-500"
                                            />
                                        </div>
                                        <h3 className="text-sm font-bold text-gray-900 line-clamp-2 leading-snug mb-2">
                                            {product.product_name}
                                        </h3>
                                        <div className="flex items-baseline gap-2">
                                            <p className="text-base font-bold text-gray-900">
                                                {formatPrice(basePrice, product?.country_prices)}
                                            </p>
                                            {selectedVariant?.size_label && (
                                                <p className="text-[10px] text-gray-400 uppercase tracking-wider font-bold">
                                                    / {selectedVariant.size_label}
                                                </p>
                                            )}
                                        </div>
                                    </div>

                                    <div className="px-0 pb-6">
                                        {product.variants?.length > 1 ? (
                                            <button
                                                onClick={() => {
                                                    window.scrollTo({ top: 0, behavior: 'smooth' });
                                                }}
                                                className="w-full bg-[#91C934] py-3.5 text-[11px] font-bold text-white transition-colors hover:bg-[#7ab52a] flex items-center justify-center gap-2 uppercase tracking-[0.2em]"
                                            >
                                                <svg viewBox="0 0 24 24" className="w-4 h-4 fill-none stroke-current stroke-2">
                                                    <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z" />
                                                    <circle cx="12" cy="12" r="3" />
                                                </svg>
                                                Preview Options
                                            </button>
                                        ) : (
                                            <button
                                                onClick={onAddToCart}
                                                className="w-full bg-[#91C934] py-4 text-[11px] font-bold text-white transition-colors hover:bg-[#7ab52a] flex items-center justify-center gap-2 uppercase tracking-[0.2em]"
                                            >
                                                Add to Bag
                                            </button>
                                        )}
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            )}
        </section>
    );
}

import React from 'react';

interface Block {
    type: 'heading' | 'paragraph' | 'html';
    text: string;
}

interface LegalContentRendererProps {
    content: string;
}

export default function LegalContentRenderer({ content }: LegalContentRendererProps) {
    if (!content) {
        return <p className="text-gray-500 italic">Content is currently being updated. Please check back later.</p>;
    }

    let parsedBlocks: Block[] | null = null;
    try {
        parsedBlocks = JSON.parse(content);
    } catch (e) {
        // Fallback for legacy HTML content
    }

    if (Array.isArray(parsedBlocks) && parsedBlocks.length > 0 && parsedBlocks[0].type) {
        return (
            <div className="space-y-8">
                {parsedBlocks.map((block: Block, idx: number) => (
                    <div key={idx}>
                        {block.type === 'heading' ? (
                            <h2 className="text-2xl lg:text-3xl font-bold text-gray-900 mt-12 mb-6 first:mt-0">
                                {block.text}
                            </h2>
                        ) : (
                            block.type === 'paragraph' && !/<[a-z][\s\S]*>/i.test(block.text) ? (
                                <p className="text-gray-700 text-lg leading-relaxed whitespace-pre-wrap mb-6 last:mb-0 text-left">
                                    {block.text}
                                </p>
                            ) : (
                                <div 
                                    className="legal-custom-html max-w-none text-left" 
                                    dangerouslySetInnerHTML={{ __html: block.text }} 
                                />
                            )
                        )}
                    </div>
                ))}
            </div>
        );
    }

    // Heuristic: If it looks like escaped HTML, unescape the most common tags
    let finalContent = content;
    if (content.includes('&lt;') && !content.includes('<')) {
        finalContent = content
            .replace(/&lt;/g, '<')
            .replace(/&gt;/g, '>')
            .replace(/&quot;/g, '"')
            .replace(/&amp;/g, '&')
            .replace(/&nbsp;/g, ' ');
    }

    return (
        <div 
            className="legal-rich-text max-w-none text-left"
            dangerouslySetInnerHTML={{ __html: finalContent }}
        />
    );
}

'use client';

import { createContext, useContext, useState, useEffect, ReactNode, useCallback, useRef } from 'react';
import { authFetch, API_URL } from '@/lib/api';
import { setUserId, clearUserId } from '@/lib/analytics/gtag';
import { useCookieConsent } from '@/context/CookieConsentContext';

interface AuthContextType {
    user: UserInfo | null;
    isAuthenticated: boolean;
    isLoading: boolean;
    login: (email: string, password: string, rememberMe?: boolean, turnstileToken?: string) => Promise<{ success: boolean; error?: string; code?: string; role?: string; access_token?: string; requireCaptcha?: boolean; blocked?: boolean; retryAfter?: number }>;
    register: (name: string, email: string, password: string, turnstileToken?: string) => Promise<RegisterResponse>;
    /** Log-in the user directly from verification data (after OTP verified and account created) */
    loginFromVerification: (customerData: Record<string, unknown>) => void;
    logout: () => void;
    /** Update partial user info (like avatar_url) dynamically in cache and context */
    updateUser: (updates: Partial<UserInfo>) => void;
    /** Register callbacks that run after login/logout so Carts + Wishlist can react */
    onAuthChange: (cb: AuthChangeCallback) => () => void;
}

type AuthChangeCallback = (event: 'login' | 'logout', user: UserInfo | null) => void;

interface RegisterResponse {
    success: boolean;
    email?: string;
    requires_verification?: boolean;
    error?: string;
    requireCaptcha?: boolean;
}

interface UserInfo {
    id: string;
    name: string;
    email: string;
    role?: string;
    avatar_url?: string;
    auth_method?: string;
    is_email_verified?: boolean;
    is_mobile_verified?: boolean;
    phone?: string;
    loyalty_tier?: string;
    wallet_balance?: number;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);
// API_URL imported from @/lib/api
const USER_KEY = 'vedashi_user';
// SECURITY: No TOKEN_KEY ÔÇö access tokens are handled exclusively via HttpOnly cookies

/** Map backend customer shape ÔåÆ frontend UserInfo */
function toUserInfo(customer: Record<string, unknown>): UserInfo {
    return {
        id: (customer.customer_id ?? customer.id ?? '') as string,
        name: (customer.full_name ?? customer.name ?? '') as string,
        email: (customer.email ?? '') as string,
        role: (customer.role as string) || 'customer',
        avatar_url: (customer.avatar_url as string) || undefined,
        auth_method: (customer.auth_method as string) || undefined,
        is_email_verified: !!(customer.is_email_verified),
        is_mobile_verified: !!(customer.is_mobile_verified),
        phone: (customer.phone ?? customer.mobile_phone ?? '') as string,
        loyalty_tier: (customer.loyalty_tier as string) || 'Bronze',
        wallet_balance: Number(customer.wallet_balance || 0),
    };
}

export function AuthProvider({ children }: { children: ReactNode }) {
    const [user, setUser] = useState<UserInfo | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const listenersRef = useRef<Set<AuthChangeCallback>>(new Set());
    const { consent } = useCookieConsent();

    /** Helper: push user_id to dataLayer only if analytics consent is granted */
    const pushUserId = useCallback((userId: string) => {
        if (consent?.analytics) setUserId(userId);
    }, [consent]);

    /** Helper: clear user_id from dataLayer only if analytics consent is granted */
    const pushClearUserId = useCallback(() => {
        if (consent?.analytics) clearUserId();
    }, [consent]);

    /** Subscribe to auth events ÔÇö returns unsubscribe function */
    const onAuthChange = useCallback((cb: AuthChangeCallback) => {
        listenersRef.current.add(cb);
        return () => { listenersRef.current.delete(cb); };
    }, []);

    const notifyListeners = useCallback((event: 'login' | 'logout', u: UserInfo | null) => {
        listenersRef.current.forEach(cb => cb(event, u));
    }, []);

    // ÔöÇÔöÇ Automatically set user properties when user state changes ÔöÇÔöÇ
    useEffect(() => {
        if (user && typeof window !== 'undefined' && window.gtag) {
            window.gtag('set', 'user_properties', {
                loyalty_tier: user.loyalty_tier || 'Bronze',
                is_returning_customer: 'true'
            });
        }
    }, [user]);

    // ÔöÇÔöÇ Listen for session-expired event (from authFetch interceptor) ÔöÇÔöÇ
    useEffect(() => {
        if (typeof window === 'undefined') return;
        const handler = () => {
            setUser(null);
            localStorage.removeItem(USER_KEY);
            sessionStorage.removeItem('justSignedIn');
            sessionStorage.removeItem('social_otp_data');
            pushClearUserId();
            notifyListeners('logout', null);
        };
        window.addEventListener('session-expired', handler);
        return () => window.removeEventListener('session-expired', handler);
    }, [notifyListeners]);

    // On mount: try to restore session from localStorage cache + validate with server
    useEffect(() => {
        if (typeof window === 'undefined') {
            setIsLoading(false);
            return;
        }

        const stored = localStorage.getItem(USER_KEY);
        if (stored) {
            try {
                const cachedUser: UserInfo = JSON.parse(stored);
                setUser(cachedUser);
                // Push user_id for analytics (consent-gated)
                pushUserId(cachedUser.id);
                // Notify listeners (Cart/Wishlist) about restored session
                setTimeout(() => notifyListeners('login', cachedUser), 0);

                // Validate session with server via HttpOnly cookie
                authFetch(`${API_URL}/api/auth/me`)
                    .then(res => res.json())
                    .then(json => {
                        if (json.success && json.data) {
                            const updatedUser = toUserInfo(json.data);

                            // ÔöÇÔöÇ SECURITY ROLE CHECK ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
                            // Prevent admins from using the storefront app as a user
                            if (['admin', 'Super Admin', 'owner'].includes(updatedUser.role || '')) {
                                console.warn('[Auth] Admin role detected in storefront - clearing session');
                                setUser(null);
                                localStorage.removeItem(USER_KEY);
                                notifyListeners('logout', null);
                                return;
                            }

                            setUser(updatedUser);
                            localStorage.setItem(USER_KEY, JSON.stringify(updatedUser));
                            // Re-push user_id with verified data
                            pushUserId(updatedUser.id);
                        } else {
                            // Cookie expired or invalid ÔÇö clear cached user
                            setUser(null);
                            localStorage.removeItem(USER_KEY);
                            pushClearUserId();
                            notifyListeners('logout', null);
                        }
                    }).catch(() => {
                        // Network error ÔÇö keep cached user for offline resilience
                    }).finally(() => {
                        setIsLoading(false);
                    });
            } catch {
                localStorage.removeItem(USER_KEY);
                setIsLoading(false);
            }
        } else {
            // ÔöÇÔöÇ SILENT RECOVERY CHECK ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
            // If no local storage but cookies exist, try to restore customer session
            authFetch(`${API_URL}/api/auth/me`)
                .then(res => res.json())
                .then(json => {
                    if (json.success && json.data) {
                        const updatedUser = toUserInfo(json.data);
                        // ONLY auto-log if it is NOT an admin
                        if (!['admin', 'Super Admin', 'owner'].includes(updatedUser.role || '')) {
                            setUser(updatedUser);
                            localStorage.setItem(USER_KEY, JSON.stringify(updatedUser));
                            pushUserId(updatedUser.id);
                            notifyListeners('login', updatedUser);
                        }
                    }
                })
                .catch(() => { })
                .finally(() => {
                    setIsLoading(false);
                });
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const login = useCallback(async (email: string, password: string, rememberMe: boolean = true, turnstileToken?: string | null) => {
        try {
            const body: Record<string, unknown> = { email, password, remember_me: rememberMe, source: 'storefront' };
            if (turnstileToken) body.turnstile_token = turnstileToken;

            const res = await authFetch(`${API_URL}/api/auth/login`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                credentials: 'include',
                body: JSON.stringify(body),
            });
            const json = await res.json();
            if (res.ok && json.success && json.data?.customer) {
                const u = toUserInfo(json.data.customer);

                // ÔöÇÔöÇ SECURITY ROLE CHECK ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
                // Prevent admins from being authenticated as customers in the storefront state
                if (['admin', 'Super Admin', 'owner'].includes(u.role || '')) {
                    console.info('[Auth] Admin login detected - returning success for redirection');
                    // We return success: true so the login page can redirect to the admin panel,
                    // but we DO NOT call setUser(u) or store the user locally.
                    return { success: true, role: u.role };
                }

                setUser(u);
                localStorage.setItem(USER_KEY, JSON.stringify(u));
                // SECURITY: No token stored ÔÇö access token is in HttpOnly cookie
                sessionStorage.setItem('justSignedIn', String(Date.now()));
                pushUserId(u.id);
                notifyListeners('login', u);
                return { success: true, role: u.role };
            }
            if (json.message) return {
                success: false,
                error: json.message,
                code: json.code,
                requireCaptcha: json.requireCaptcha,
                blocked: json.blocked,
                retryAfter: json.retryAfter,
            };
        } catch (err) {
            console.error('[Auth] Login error:', err);
        }

        return { success: false, error: 'Login failed. Please check your credentials.' };
    }, [notifyListeners]);

    const register = useCallback(async (
        name: string,
        email: string,
        password: string,
        turnstileToken?: string
    ): Promise<RegisterResponse> => {
        try {
            const res = await authFetch(`${API_URL}/api/auth/initiate-registration`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                credentials: 'include',
                body: JSON.stringify({ full_name: name, email, password, turnstile_token: turnstileToken }),
            });
            const json = await res.json();
            if (res.ok && json.success) {
                return {
                    success: true,
                    email: json.data?.email || email,
                    requires_verification: true,
                };
            }
            if (json.message) return { success: false, error: json.message, requireCaptcha: json.requireCaptcha };
        } catch (err) {
            console.error('[Auth] Register error:', err);
        }

        return { success: false, error: 'Registration failed. Please try again.' };
    }, []);

    /** Log in the user from verification page data (after OTP created the account) */
    const loginFromVerification = useCallback((customerData: Record<string, unknown>) => {
        const u = toUserInfo(customerData);
        setUser(u);
        localStorage.setItem(USER_KEY, JSON.stringify(u));
        // SECURITY: No token stored ÔÇö access token is in HttpOnly cookie
        sessionStorage.setItem('justSignedIn', String(Date.now()));
        pushUserId(u.id);
        notifyListeners('login', u);
    }, [notifyListeners, pushUserId]);

    /** Update user fields dynamically */
    const updateUser = useCallback((updates: Partial<UserInfo>) => {
        setUser(prev => {
            if (!prev) return null;
            const updated = { ...prev, ...updates };
            localStorage.setItem(USER_KEY, JSON.stringify(updated));
            // Trigger login event to simulate an update broadcast
            // Notify listeners outside the state updater to avoid React update errors
            setTimeout(() => notifyListeners('login', updated), 0);
            return updated;
        });
    }, [notifyListeners]);

    const logout = useCallback(() => {
        authFetch(`${API_URL}/api/auth/logout`, { method: 'POST', credentials: 'include' }).catch(() => { });
        setUser(null);
        localStorage.removeItem(USER_KEY);
        // Clear all auth-related session storage
        sessionStorage.removeItem('justSignedIn');
        sessionStorage.removeItem('social_otp_data');
        // SECURITY: HttpOnly cookies are cleared server-side by the /api/auth/logout endpoint
        pushClearUserId();
        notifyListeners('logout', null);
    }, [notifyListeners, pushClearUserId]);


    return (
        <AuthContext.Provider value={{
            user, isAuthenticated: !!user, isLoading,
            login, register, loginFromVerification, logout, updateUser, onAuthChange,
        }}>
            {children}
        </AuthContext.Provider>
    );
}

export function useAuth() {
    const context = useContext(AuthContext);
    if (!context) throw new Error('useAuth must be used within AuthProvider');
    return context;
}

'use client';

import { createContext, useContext, useState, useCallback, useEffect, useMemo, ReactNode, useRef } from 'react';
import { BackendCartItem, BackendCart } from '@/types';
import { useAuth } from '@/context/AuthContext';
import { trackEcommerce } from '@/lib/analytics/gtag';
import {
    createCart as apiCreateCart,
    getCart as apiGetCart,
    addCartItem as apiAddCartItem,
    updateCartItem as apiUpdateCartItem,
    removeCartItem as apiRemoveCartItem,
    mergeGuestCart as apiMergeGuestCart,
    validateCoupon as apiValidateCoupon,
    getBestAutoApplyCoupon as apiGetBestAutoApplyCoupon,
    saveForLater as apiSaveForLater,
    moveToCartFromSaved as apiMoveToCart,
    getSavedItems as apiGetSavedItems,
} from '@/lib/api';

const GUEST_CART_KEY = 'ksp_guest_cart_id';

interface CartContextType {
    items: BackendCartItem[];
    savedItems: BackendCartItem[];
    cartId: string | null;
    loading: boolean;
    error: string | null;
    addItem: (productId: string, variantId: string | null, quantity?: number) => Promise<void>;
    removeItem: (cartItemId: string) => Promise<void>;
    updateQuantity: (cartItemId: string, quantity: number) => Promise<void>;
    clearCart: (localOnly?: boolean) => Promise<void>;
    saveForLater: (cartItemId: string) => Promise<void>;
    moveToCart: (cartItemId: string) => Promise<void>;
    totalItems: number;
    totalPrice: number;
    couponCode: string | null;
    couponDiscount: number;
    couponType: string | null;
    couponError: string | null;
    applyCoupon: (code: string) => Promise<boolean>;
    removeCoupon: () => void;
    orderNotes: string;
    setOrderNotes: (notes: string) => void;
    /** Find a cart item by productId + optional variantId. Returns the item or undefined. */
    getItemInCart: (productId: string, variantId?: string | null) => BackendCartItem | undefined;
}

const CartContext = createContext<CartContextType | undefined>(undefined);

/** Flatten backend cart item ÔåÆ easy-to-consume shape with top-level product_id, product_name, price */
function flattenCartItem(item: BackendCartItem): BackendCartItem {
    return {
        ...item,
        product_id: item.product?.product_id || item.product_id || '',
        product_name: item.product?.product_name || item.product_name || 'Product',
        slug: item.product?.slug || item.slug || '',
        sku: item.variant?.variant_sku || item.product?.product_sku || item.sku || (item as unknown as Record<string, unknown>).product_sku as string || '',
        price: item.pricing?.effective_price ?? item.pricing?.unit_price ?? item.price ?? 0,
        original_price: item.pricing?.unit_price ?? item.price ?? 0,
        size_label: item.variant?.size_label || item.size_label || '',
        image_url: item.product?.thumbnail_url || item.image_url || '',
        stock_quantity: item.variant?.stock_quantity ?? (item as unknown as Record<string, unknown>).stock_quantity as number ?? 0,
        country_prices: item.product?.country_prices || [],
    };
}

export function CartProvider({ children }: { children: ReactNode }) {
    const [items, setItems] = useState<BackendCartItem[]>([]);
    const [savedItems, setSavedItems] = useState<BackendCartItem[]>([]);
    const [cartId, setCartId] = useState<string | null>(null);
    const pendingQtyUpdates = useRef(0);

    // DERIVED VALUE ÔÇö single source of truth, can never desync from items
    const totalItems = useMemo(() => new Set(items.map(i => String(i.product_id))).size, [items]);
    const totalPrice = useMemo(() => items.reduce((s, i) => s + (i.price || 0) * i.quantity, 0), [items]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [couponCode, setCouponCode] = useState<string | null>(null);
    const [couponDiscount, setCouponDiscount] = useState(0);
    const [couponType, setCouponType] = useState<string | null>(null);
    const [couponError, setCouponError] = useState<string | null>(null);
    const [autoApplyDisabled, setAutoApplyDisabled] = useState(false);
    const [orderNotes, setOrderNotes] = useState('');
    const { onAuthChange, isAuthenticated, user } = useAuth();
    const initDone = useRef(false);

    const fetchSavedItems = useCallback(async (cId: string) => {
        try {
            const res = await apiGetSavedItems(cId);
            if (res.success && res.data) {
                setSavedItems((res.data || []).map(flattenCartItem));
            }
        } catch (err) {
            console.error('[CartContext] fetchSavedItems error:', err);
        }
    }, []);

    /** Fetch full cart state from backend */
    const fetchCart = useCallback(async (cId: string): Promise<BackendCart | undefined> => {
        try {
            const res = await apiGetCart({ cart_id: cId });
            if (res.success && res.data) {
                const cart = res.data as BackendCart;
                const flatItems = (cart.items || []).map(flattenCartItem);
                setItems(flatItems);
                // totalItems and totalPrice are derived via useMemo ÔÇö no manual set needed
                await fetchSavedItems(cId);
                return cart;
            }
        } catch (err) {
            console.error('[CartContext] fetchCart error:', err);
        }
    }, [fetchSavedItems]);

    /** Initialize cart for a logged-in customer (optionally merging a guest cart first) */
    const initCart = useCallback(async (customerId: string) => {
        setLoading(true);
        setError(null);
        try {
            // Check if there's a guest cart to merge
            const guestCartId = typeof window !== 'undefined' ? localStorage.getItem(GUEST_CART_KEY) : null;
            if (guestCartId) {
                try {
                    await apiMergeGuestCart(guestCartId, customerId);
                } catch (mergeErr) {
                    console.warn('[CartContext] Guest cart merge failed (cart may have expired):', mergeErr);
                }
                localStorage.removeItem(GUEST_CART_KEY);
            }

            const getRes = await apiGetCart({ customer_id: customerId });
            if (getRes.success && getRes.data) {
                const cart = getRes.data as BackendCart;
                setCartId(cart.cart_id);
                const flatItems = (cart.items || []).map(flattenCartItem);
                setItems(flatItems);
                await fetchSavedItems(cart.cart_id);
            } else {
                const createRes = await apiCreateCart(customerId);
                if (createRes.success && createRes.data) {
                    setCartId(createRes.data.cart_id);
                    setItems([]);
                    setSavedItems([]);
                }
            }
        } catch (err) {
            console.error('[CartContext] initCart error:', err);
            setError('Failed to load cart');
        } finally {
            setLoading(false);
        }
    }, []);

    /** Restore a guest cart from localStorage (if user is NOT authenticated) */
    const restoreGuestCart = useCallback(async () => {
        if (typeof window === 'undefined') return;
        const savedCartId = localStorage.getItem(GUEST_CART_KEY);
        if (!savedCartId) return;

        setLoading(true);
        try {
            const res = await apiGetCart({ cart_id: savedCartId });
            if (res.success && res.data) {
                const cart = res.data as BackendCart;
                setCartId(cart.cart_id);
                const flatItems = (cart.items || []).map(flattenCartItem);
                setItems(flatItems);
                await fetchSavedItems(cart.cart_id);
            } else {
                // Guest cart expired or deleted ÔÇö clean up
                localStorage.removeItem(GUEST_CART_KEY);
            }
        } catch (err) {
            console.error('[CartContext] restoreGuestCart error:', err);
            localStorage.removeItem(GUEST_CART_KEY);
        } finally {
            setLoading(false);
        }
    }, []);

    /** Create a guest cart on-the-fly (called when a guest clicks "Add to Cart") */
    const ensureGuestCart = useCallback(async (): Promise<string | null> => {
        try {
            const createRes = await apiCreateCart(); // no customer_id ÔåÆ guest cart
            if (createRes.success && createRes.data) {
                const newCartId = createRes.data.cart_id;
                setCartId(newCartId);
                localStorage.setItem(GUEST_CART_KEY, newCartId);
                return newCartId;
            }
        } catch (err) {
            console.error('[CartContext] ensureGuestCart error:', err);
        }
        return null;
    }, []);

    const resetCart = useCallback(() => {
        setCartId(null);
        setItems([]);
        setSavedItems([]);
        setError(null);
        setCouponCode(null);
        setCouponDiscount(0);
        setCouponType(null);
        setCouponError(null);
        setAutoApplyDisabled(false);
        if (typeof window !== 'undefined') {
            localStorage.removeItem(GUEST_CART_KEY);
        }
        setOrderNotes('');
    }, []);

    const applyCoupon = useCallback(async (code: string): Promise<boolean> => {
        setCouponError(null);
        try {
            // Compute cart_total from items directly to avoid stale totalPrice state
            const computedCartTotal = items.reduce((sum, item) => sum + (item.price || 0) * item.quantity, 0);
            const cartTotalToSend = computedCartTotal > 0 ? computedCartTotal : totalPrice;

            if (!cartTotalToSend || cartTotalToSend <= 0) {
                setCouponError('Please add items to your cart before applying a coupon');
                return false;
            }

            const res = await apiValidateCoupon(code, cartTotalToSend);
            if (res.success) {
                setCouponCode(res.data.coupon.code);
                setCouponType(res.data.coupon.discount_type || null);

                let computedDiscount = 0;

                if (res.data.coupon.discount_type === 'bogo') {
                    const buyQty = res.data.coupon.bogo_buy_qty || 1;
                    const getQty = res.data.coupon.bogo_get_qty || 1;

                    const flatPrices: number[] = [];
                    items.forEach(it => {
                        for (let i = 0; i < it.quantity; i++) {
                            // Effective price
                            flatPrices.push(it.price || 0);
                        }
                    });

                    flatPrices.sort((a, b) => a - b);
                    const bogoGroups = Math.floor(flatPrices.length / (buyQty + getQty));
                    const freeItemsCount = bogoGroups * getQty;

                    let bogoDiscount = 0;
                    for (let i = 0; i < freeItemsCount; i++) {
                        bogoDiscount += flatPrices[i];
                    }

                    if (res.data.coupon.max_discount_cap !== null) {
                        bogoDiscount = Math.min(bogoDiscount, parseFloat(res.data.coupon.max_discount_cap));
                    }
                    computedDiscount = bogoDiscount;
                } else {
                    computedDiscount = res.data.discount;
                }

                // Enforce minimum payable of Ôé╣1 ÔÇö cap discount so total never drops below Ôé╣MINIMUM_PAYABLE
                const minPayable = Number(process.env.NEXT_PUBLIC_MINIMUM_PAYABLE_AMOUNT) || 1;
                const maxAllowedDiscount = Math.max(0, cartTotalToSend - minPayable);
                computedDiscount = Math.min(computedDiscount, maxAllowedDiscount);

                setCouponDiscount(computedDiscount);
                return true;
            } else {
                setCouponError(res.message || 'Invalid coupon');
                setCouponCode(null);
                setCouponDiscount(0);
                setCouponType(null);
                return false;
            }
        } catch {
            setCouponError('Failed to validate coupon');
            return false;
        }
    }, [totalPrice, items]);

    const removeCoupon = useCallback(() => {
        setCouponCode(null);
        setCouponDiscount(0);
        setCouponType(null);
        setCouponError(null);
        setAutoApplyDisabled(true); // Don't forcibly auto-apply again if user actively removed it
    }, []);

    // Subscribe to auth changes
    useEffect(() => {
        const unsub = onAuthChange((event, user) => {
            if (event === 'login' && user) {
                initCart(user.id);
            } else if (event === 'logout') {
                resetCart();
            }
        });
        return unsub;
    }, [onAuthChange, initCart, resetCart]);

    // On mount: if not authenticated, try to restore guest cart
    useEffect(() => {
        if (initDone.current) return;
        initDone.current = true;

        // If user is already authenticated, initCart is handled by onAuthChange listener
        // If not authenticated, try to restore a guest cart from localStorage
        if (!isAuthenticated) {
            restoreGuestCart();
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    // Auto-apply effect
    useEffect(() => {
        if (couponCode || totalPrice <= 0 || autoApplyDisabled) return;

        let active = true;
        apiGetBestAutoApplyCoupon(totalPrice)
            .then(res => {
                if (active && res.success && res.data?.coupon?.code) {
                    // Temporarily skip setCouponError on this automatic background attempt
                    applyCoupon(res.data.coupon.code).catch(() => { });
                }
            })
            .catch(() => { });

        return () => { active = false; };
    }, [totalPrice, couponCode, autoApplyDisabled, applyCoupon]);


    // Re-validate applied coupon when cart changes
    useEffect(() => {
        if (couponCode && !loading) {
            applyCoupon(couponCode).catch(err => {
                console.warn('[CartContext] Coupon re-validation failed:', err);
            });
        }
        // We only want to re-run this when items or total price changes to keep discount accurate
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [items.length, totalPrice]);

    const addItem = useCallback(async (productId: string, variantId: string | null, quantity = 1) => {
        let activeCartId = cartId;

        // If no cart exists, create one (guest cart if not authenticated)
        if (!activeCartId) {
            if (isAuthenticated && user) {
                // Shouldn't normally happen, but just in case
                const createRes = await apiCreateCart(user.id);
                if (createRes.success && createRes.data) {
                    activeCartId = createRes.data.cart_id;
                    setCartId(activeCartId);
                }
            } else {
                activeCartId = await ensureGuestCart();
            }
        }

        if (!activeCartId) {
            setError('Failed to create cart. Please try again.');
            return;
        }

        setLoading(true);
        setError(null);
        try {
            if (variantId) {
                await apiAddCartItem(activeCartId, variantId, quantity, true);
            } else {
                await apiAddCartItem(activeCartId, productId, quantity, false);
            }
            const freshCart = await fetchCart(activeCartId);
            const freshItems = freshCart ? (freshCart.items || []).map(flattenCartItem) : [];
            const addedItem = freshItems.find(i =>
                String(i.product_id) === String(productId) &&
                (variantId ? String(i.variant_id) === String(variantId) : true)
            );

            if (addedItem) {
                trackEcommerce('add_to_cart', {
                    currency: 'INR',
                    value: (addedItem.price || 0) * quantity,
                    items: [{
                        item_id: String(addedItem.product_id || productId),
                        item_name: addedItem.product_name || productId,
                        price: addedItem.price || 0,
                        quantity,
                    }],
                });
            } else {
                // Fallback: Fire the event with the data we already know
                trackEcommerce('add_to_cart', {
                    currency: 'INR',
                    value: 0, // Fallback value
                    items: [{
                        item_id: String(productId),
                        item_name: productId,
                        price: 0, // Fallback price
                        quantity,
                    }],
                });
            }
        } catch (err) {
            console.error('[CartContext] addItem error:', err);
            const msg = 'Failed to add item to cart';
            setError(msg);
            throw err; // Re-throw to inform caller (e.g. for toast handling)
        } finally {
            setLoading(false);
        }
    }, [cartId, fetchCart, isAuthenticated, user, ensureGuestCart]);

    const updateQuantity = useCallback(async (cartItemId: string, quantity: number) => {
        let snapshot: BackendCartItem[] = [];

        // Optimistic UI Update Phase
        setItems(prev => {
            snapshot = prev;
            if (quantity <= 0) {
                return prev.filter(i => i.cart_item_id !== cartItemId);
            }
            return prev.map(item => item.cart_item_id === cartItemId ? { ...item, quantity } : item);
        });

        setError(null);
        pendingQtyUpdates.current += 1;

        try {
            if (quantity <= 0) {
                await apiRemoveCartItem(cartItemId);
            } else {
                await apiUpdateCartItem(cartItemId, quantity);
            }
        } catch (err) {
            console.error('[CartContext] updateQuantity error:', err);
            setItems(snapshot); // Revert on failure
            setError('Failed to update quantity');
            throw err;
        } finally {
            pendingQtyUpdates.current -= 1;
            // Only perform a full backend sync when all rapid clicks have resolved to avoid screen flickering
            if (pendingQtyUpdates.current === 0 && cartId) {
                fetchCart(cartId); // Background sync, does not block the UI
            }
        }
    }, [cartId, fetchCart]);

    const removeItem = useCallback(async (cartItemId: string) => {
        // Capture item data BEFORE removal for the GA4 event
        const removedItem = items.find(i => i.cart_item_id === cartItemId);
        let snapshot: BackendCartItem[] = [];

        // Optimistic UI Removal
        setItems(prev => {
            snapshot = prev;
            return prev.filter(i => i.cart_item_id !== cartItemId);
        });

        setError(null);
        try {
            await apiRemoveCartItem(cartItemId);
            if (cartId) await fetchCart(cartId);

            // GA4: remove_from_cart
            if (removedItem) {
                trackEcommerce('remove_from_cart', {
                    currency: 'INR',
                    value: (removedItem.price || 0) * removedItem.quantity,
                    items: [{
                        item_id: removedItem.product_id || '',
                        item_name: removedItem.product_name || 'Product',
                        price: removedItem.price || 0,
                        quantity: removedItem.quantity,
                    }],
                });
            }
        } catch (err) {
            console.error('[CartContext] removeItem error:', err);
            setItems(snapshot); // Revert on failure
            setError('Failed to remove item');
            throw err;
        }
    }, [cartId, fetchCart, items]);

    const saveForLater = useCallback(async (cartItemId: string) => {
        setLoading(true);
        setError(null);
        try {
            await apiSaveForLater(cartItemId);
            if (cartId) await fetchCart(cartId);
        } catch (err) {
            console.error('[CartContext] saveForLater error:', err);
            setError('Failed to save item for later');
        } finally {
            setLoading(false);
        }
    }, [cartId, fetchCart]);

    const moveToCart = useCallback(async (cartItemId: string) => {
        setLoading(true);
        setError(null);
        try {
            await apiMoveToCart(cartItemId);
            // fetchCart sets items via setItems ÔåÆ totalItems auto-recalculates via useMemo
            if (cartId) await fetchCart(cartId);
        } catch (err) {
            console.error('[CartContext] moveToCart error:', err);
            setError('Failed to move item to cart');
        } finally {
            setLoading(false);
        }
    }, [cartId, fetchCart]);

    const clearCart = useCallback(async (localOnly = false) => {
        if (!cartId) return;
        setLoading(true);
        try {
            if (!localOnly) {
                for (const item of items) {
                    await apiRemoveCartItem(item.cart_item_id);
                }
            }
            setItems([]);
            // totalItems and totalPrice auto-reset to 0 via useMemo when items is []
        } catch (err) {
            console.error('[CartContext] clearCart error:', err);
        } finally {
            setLoading(false);
        }
    }, [cartId, items]);

    // Real-time stock polling & validation
    useEffect(() => {
        if (!cartId || items.length === 0) return;

        // Auto-check quantities against stock
        items.forEach(item => {
            const stock = item.stock_quantity ?? 0;
            if (stock > 0 && item.quantity > stock) {
                updateQuantity(item.cart_item_id, stock).catch(() => { });
                import('react-hot-toast').then(({ default: toast }) => {
                    toast(`Quantity of ${item.product_name} reduced to ${stock} due to limited stock.`, { icon: 'ÔÜá´©Å' });
                });
            }
        });

        // Poll cart every 30 seconds
        const pollInterval = setInterval(() => {
            fetchCart(cartId).catch(() => { });
        }, 30000);

        return () => clearInterval(pollInterval);
    }, [cartId, items, fetchCart, updateQuantity]);

    /** Find a cart item by productId + optional variantId */
    const getItemInCart = useCallback((productId: string, variantId?: string | null): BackendCartItem | undefined => {
        return items.find(i =>
            String(i.product_id) === String(productId) &&
            (variantId ? String(i.variant_id) === String(variantId) : true)
        );
    }, [items]);

    return (
        <CartContext.Provider value={{
            items, savedItems, cartId, loading, error,
            addItem, removeItem, updateQuantity, clearCart, saveForLater, moveToCart,
            totalItems, totalPrice,
            couponCode, couponDiscount, couponType, couponError,
            applyCoupon, removeCoupon,
            orderNotes, setOrderNotes,
            getItemInCart,
        }}>
            {children}
        </CartContext.Provider>
    );
}

export function useCart() {
    const context = useContext(CartContext);
    if (!context) throw new Error('useCart must be used within CartProvider');
    return context;
}

