'use client';

import React, { createContext, useContext, useEffect, useState, useMemo } from 'react';
import {
  CountryConfig,
  SUPPORTED_COUNTRIES,
  SupportedCountryCode,
  CurrencyConfigEntry,
  CountryPriceOverride,
  resolveBasePrice,
  formatPrice,
  formatLocal,
  deriveCountryMrp,
} from '@/lib/currency';
import { API_URL } from '@/lib/api';

interface CurrencyContextType {
  countryCode: SupportedCountryCode;
  countryConfig: CountryConfig;
  currencyConfigs: CurrencyConfigEntry[];
  /**
   * Format a price for display. Handles country-based conversion automatically.
   *
   * @param amountUsd - Default price in USD (base currency)
   * @param countryPrices - Optional per-product country price overrides from the backend
   */
  formatPrice: (
    amountUsd: number | string | null | undefined,
    countryPrices?: CountryPriceOverride[] | null
  ) => string;
  /**
   * Format an MRP for display. For countries with a price override,
   * derives the MRP from the country SP using the USD discount percentage.
   *
   * @param usdMrp       - The MRP / original price in USD
   * @param usdSp        - The selling / display price in USD
   * @param countryPrices - Optional per-product country price overrides
   */
  formatMrp: (
    usdMrp: number | string | null | undefined,
    usdSp: number | string | null | undefined,
    countryPrices?: CountryPriceOverride[] | null
  ) => string;
  /**
   * Resolve a USD price to the active country's numerical value (applying overrides or exchange rate).
   */
  resolvePrice: (
    amountUsd: number | string | null | undefined,
    countryPrices?: CountryPriceOverride[] | null
  ) => number;
  /**
   * Resolve a USD MRP to the active country's numerical MRP value.
   */
  resolveMrp: (
    usdMrp: number | string | null | undefined,
    usdSp: number | string | null | undefined,
    countryPrices?: CountryPriceOverride[] | null
  ) => number;
  /**
   * Format a numerical value that is ALREADY in the active country's currency.
   */
  format: (localAmount: number | string | null | undefined) => string;
  isLoadingRates: boolean;
}

const CurrencyContext = createContext<CurrencyContextType | null>(null);

export function CurrencyProvider({
  children,
  countryCode
}: {
  children: React.ReactNode;
  countryCode: SupportedCountryCode;
}) {
  const [currencyConfigs, setCurrencyConfigs] = useState<CurrencyConfigEntry[]>([]);
  const [isLoadingRates, setIsLoadingRates] = useState(true);

  const countryConfig = SUPPORTED_COUNTRIES[countryCode] || SUPPORTED_COUNTRIES['us'];

  useEffect(() => {
    async function fetchCurrencyConfig() {
      try {
        const res = await fetch(`${API_URL}/api/currency-config`, { next: { revalidate: 3600 } } as any);
        if (res.ok) {
          const data = await res.json();
          if (data.success && Array.isArray(data.data)) {
            setCurrencyConfigs(data.data.map((entry: any) => ({
              ...entry,
              exchange_rate: Number(entry.exchange_rate),
            })));
          }
        }
      } catch (error) {
        console.error('Failed to fetch currency config:', error);
      } finally {
        setIsLoadingRates(false);
      }
    }

    // Only fetch if we are not in the US (base currency), to save API calls
    if (countryConfig.currency !== 'USD') {
      fetchCurrencyConfig();
    } else {
      setIsLoadingRates(false);
    }
  }, [countryConfig.currency]);

  // 1. Core resolve function for SP
  const resolvePriceFn = useMemo(() => {
    const upperCode = countryCode.toUpperCase();
    const currentConfig = currencyConfigs.find(c => c.country_code === upperCode);

    return (
      amountUsd: number | string | null | undefined,
      countryPrices?: CountryPriceOverride[] | null
    ): number => {
      const baseAmount = Number(amountUsd) || 0;

      if (countryPrices && countryPrices.length > 0) {
        const override = countryPrices.find(cp => cp.country_code.toUpperCase() === upperCode);
        if (override && Number(override.price_inr) > 0) {
          return Number(override.price_inr);
        }
      }

      if (currentConfig) {
        return baseAmount * currentConfig.exchange_rate;
      }
      return baseAmount;
    };
  }, [countryCode, currencyConfigs]);

  // 2. Core resolve function for MRP
  const resolveMrpFn = useMemo(() => {
    const upperCode = countryCode.toUpperCase();
    const currentConfig = currencyConfigs.find(c => c.country_code === upperCode);

    return (
      usdMrp: number | string | null | undefined,
      usdSp: number | string | null | undefined,
      countryPrices?: CountryPriceOverride[] | null
    ): number => {
      const mrp = Number(usdMrp) || 0;
      const sp = Number(usdSp) || 0;

      if (countryPrices && countryPrices.length > 0) {
        const override = countryPrices.find(cp => cp.country_code.toUpperCase() === upperCode);
        if (override && Number(override.price_inr) > 0) {
          const overrideSp = Number(override.price_inr);
          return deriveCountryMrp(overrideSp, sp, mrp);
        }
      }

      if (currentConfig) {
        return mrp * currentConfig.exchange_rate;
      }
      return mrp;
    };
  }, [countryCode, currencyConfigs]);

  // 3. Core formatter (already converted)
  const formatFn = useMemo(() => {
    const upperCode = countryCode.toUpperCase();
    const currentConfig = currencyConfigs.find(c => c.country_code === upperCode);
    
    return (localAmount: number | string | null | undefined): string => {
      if (countryCode === 'us') return formatLocal(localAmount, 'USD', 'en-US');
      if (currentConfig) return formatLocal(localAmount, currentConfig.currency_code, countryConfig.locale);
      return formatLocal(localAmount, 'USD', 'en-US');
    };
  }, [countryCode, countryConfig.locale, currencyConfigs]);

  // 4. Backward compatible formatPrice (resolve + format)
  const boundFormatPrice = useMemo(() => {
    return (
      amountUsd: number | string | null | undefined,
      countryPrices?: CountryPriceOverride[] | null
    ): string => {
      const localNum = resolvePriceFn(amountUsd, countryPrices);
      return formatFn(localNum);
    };
  }, [resolvePriceFn, formatFn]);

  // 5. Backward compatible formatMrp (resolve + format)
  const boundFormatMrp = useMemo(() => {
    return (
      usdMrp: number | string | null | undefined,
      usdSp: number | string | null | undefined,
      countryPrices?: CountryPriceOverride[] | null
    ): string => {
      const localNum = resolveMrpFn(usdMrp, usdSp, countryPrices);
      return formatFn(localNum);
    };
  }, [resolveMrpFn, formatFn]);

  const value: CurrencyContextType = {
    countryCode,
    countryConfig,
    currencyConfigs,
    resolvePrice: resolvePriceFn,
    resolveMrp: resolveMrpFn,
    format: formatFn,
    formatPrice: boundFormatPrice,
    formatMrp: boundFormatMrp,
    isLoadingRates,
  };

  return (
    <CurrencyContext.Provider value={value}>
      {children}
    </CurrencyContext.Provider>
  );
}

export function useCurrency() {
  const context = useContext(CurrencyContext);
  if (!context) {
    // If used outside provider (e.g. in root layout or admin), fallback to USD/US
    return {
      countryCode: 'us' as SupportedCountryCode,
      countryConfig: SUPPORTED_COUNTRIES['us'],
      currencyConfigs: [],
      resolvePrice: (usdAmount: number | string | null | undefined, itemOverrides?: CountryPriceOverride[] | null | undefined) => Number(usdAmount) || 0,
      resolveMrp: (usdMrp: number | string | null | undefined, usdSp?: number | string | null | undefined, itemOverrides?: CountryPriceOverride[] | null | undefined) => Number(usdMrp) || 0,
      format: (localAmount: number | string | null | undefined) => formatPrice(localAmount, 'USD', 1, 'en-US'),
      formatPrice: (amount: number | string | null | undefined, countryPrices?: CountryPriceOverride[] | null) => formatPrice(amount, 'USD', 1, 'en-US'),
      formatMrp: (usdMrp: number | string | null | undefined, usdSp?: number | string | null | undefined, countryPrices?: CountryPriceOverride[] | null) => formatPrice(usdMrp, 'USD', 1, 'en-US'),
      isLoadingRates: false,
    };
  }
  return context;
}

'use client';
//   j
import { useSearchParams, useRouter, usePathname } from 'next/navigation';
import { useCallback, useMemo } from 'react';
import { FILTER_CONFIGS } from '@/lib/filterConfig';

export interface FilterState {
    search: string;
    category: string;
    sub_category: string;
    sub_sub_category: string;
    brands: string[];
    country: string;
    form: string[];
    specialities: string[];
    ratings: string[];
    priceRange: [number, number];
    inStock: boolean;
    bestSellers: boolean;
    newArrivals: boolean;
    sort: string;
    discountMin: number | null;
    attributes: Record<string, string[]>;
}

const DEFAULTS: FilterState = {
    search: '',
    category: '',
    sub_category: '',
    sub_sub_category: '',
    brands: [],
    country: '',
    form: [],
    specialities: [],
    ratings: [],
    priceRange: [0, Infinity],
    inStock: false,
    bestSellers: false,
    newArrivals: false,
    sort: '',
    discountMin: null,
    attributes: {},
};

function parseArray(val: string | null): string[] {
    if (!val) return [];
    return val.split(',').filter(Boolean);
}

function parseRange(val: string | null, fallback: [number, number]): [number, number] {
    if (!val) return fallback;
    const parts = val.split('-').map(Number);
    if (parts.length === 2 && !isNaN(parts[0]) && !isNaN(parts[1])) {
        return [parts[0], parts[1]];
    }
    return fallback;
}

export function useFilters(formatPrice?: (v: number) => string) {
    const searchParams = useSearchParams();
    const router = useRouter();
    const pathname = usePathname();

    // Read current state from URL
    const filters: FilterState = useMemo(() => {
        const attributes: Record<string, string[]> = {};
        searchParams.forEach((val, key) => {
            if (key.startsWith('attr_')) {
                const attrKey = key.replace('attr_', '');
                attributes[attrKey] = val.split(',').filter(Boolean);
            }
        });

        return {
            search: searchParams.get('search') || DEFAULTS.search,
            category: searchParams.get('category') || DEFAULTS.category,
            sub_category: searchParams.get('sub_category') || DEFAULTS.sub_category,
            sub_sub_category: searchParams.get('sub_sub_category') || DEFAULTS.sub_sub_category,
            brands: parseArray(searchParams.get('brand')),
            country: searchParams.get('country') || DEFAULTS.country,
            form: parseArray(searchParams.get('form')),
            specialities: parseArray(searchParams.get('specialities')),
            ratings: parseArray(searchParams.get('rating')),
            priceRange: parseRange(searchParams.get('price'), DEFAULTS.priceRange),
            inStock: searchParams.get('inStock') === 'true',
            bestSellers: (searchParams.get('bestSeller') === 'true' || searchParams.get('bestSellers') === 'true'),
            newArrivals: (searchParams.get('newArrival') === 'true' || searchParams.get('newArrivals') === 'true'),
            sort: searchParams.get('sort') || DEFAULTS.sort,
            discountMin: searchParams.get('discount_min') ? Number(searchParams.get('discount_min')) : null,
            attributes,
        };
    }, [searchParams]);

    // Push updates to URL (shallow ÔÇö no full reload)
    const setParam = useCallback((updates: Record<string, string | null>) => {
        const params = new URLSearchParams(searchParams.toString());
        Object.entries(updates).forEach(([key, value]) => {
            if (value === null || value === '' || value === 'false') {
                params.delete(key);
            } else {
                params.set(key, value);
            }
        });
        // Reset page on filter  change
        params.delete('page');
        const qs = params.toString();
        router.replace(`${pathname}${qs ? '?' + qs : ''}`, { scroll: false });
    }, [searchParams, router, pathname]);

    // Setter  helpers
    const setSearch = useCallback((val: string) => setParam({ search: val || null }), [setParam]);
    const setCategory = useCallback((val: string) => setParam({ category: val || null, sub_category: null, sub_sub_category: null }), [setParam]);
    const setSubCategory = useCallback((val: string) => setParam({ sub_category: val || null, sub_sub_category: null }), [setParam]);
    const setSubSubCategory = useCallback((val: string) => setParam({ sub_sub_category: val || null }), [setParam]);
    const setBrands = useCallback((val: string[]) => setParam({ brand: val.length ? val.join(',') : null }), [setParam]);
    const setCountry = useCallback((val: string) => setParam({ country: val || null }), [setParam]);
    const setForm = useCallback((val: string[]) => setParam({ form: val.length ? val.join(',') : null }), [setParam]);
    const setSpecialities = useCallback((val: string[]) => setParam({ specialities: val.length ? val.join(',') : null }), [setParam]);
    const setRatings = useCallback((val: string[]) => setParam({ rating: val.length ? val.join(',') : null }), [setParam]);
    const setPriceRange = useCallback((val: [number, number], maxPriceInStore?: number) => {
        const pMax = maxPriceInStore ?? Infinity;
        const isDefault = val[0] === 0 && (val[1] === pMax || val[1] === Infinity);
        setParam({ price: isDefault ? null : `${val[0]}-${val[1]}` });
    }, [setParam]);

    const setInStock = useCallback((val: boolean) => setParam({ inStock: val ? 'true' : null }), [setParam]);
    const setBestSellers = useCallback((val: boolean) => setParam({ bestSeller: val ? 'true' : null }), [setParam]);
    const setNewArrivals = useCallback((val: boolean) => setParam({ newArrival: val ? 'true' : null }), [setParam]);
    const setSort = useCallback((val: string) => setParam({ sort: val || null }), [setParam]);
    const setDiscountMin = useCallback((val: number | null) => setParam({ discount_min: val ? String(val) : null }), [setParam]);
    const setAttribute = useCallback((key: string, val: string[]) => setParam({ [`attr_${key}`]: val.length ? val.join(',') : null }), [setParam]);

    const clearAll = useCallback(() => {
        router.replace(pathname, { scroll: false });
    }, [router, pathname]);

    // Remove a single chip
    const removeFilter = useCallback((key: string, value: string) => {
        if (key.startsWith('attr_')) {
            const attrKey = key.replace('attr_', '');
            const current = filters.attributes[attrKey] || [];
            setAttribute(attrKey, current.filter(v => v !== value));
            return;
        }

        switch (key) {
            case 'brand': setBrands(filters.brands.filter(b => b !== value)); break;
            case 'country': setCountry(''); break;
            case 'form': setForm(filters.form.filter(f => f !== value)); break;
            case 'specialities': setSpecialities(filters.specialities.filter(s => s !== value)); break;
            case 'rating': setRatings(filters.ratings.filter(r => r !== value)); break;
            case 'category': setParam({ category: null, sub_category: null, sub_sub_category: null }); break;
            case 'sub_category': setParam({ sub_category: null, sub_sub_category: null }); break;
            case 'sub_sub_category': setSubSubCategory(''); break;
            case 'search': setSearch(''); break;
            case 'price': setPriceRange(DEFAULTS.priceRange); break;
            case 'inStock': setInStock(false); break;
            case 'bestSellers': setBestSellers(false); break;
            case 'newArrivals': setNewArrivals(false); break;
            case 'discount_min': setDiscountMin(null); break;
            case 'sort': setSort(''); break;
        }
    }, [filters, setBrands, setCountry, setRatings, setCategory, setSubCategory, setSearch, setPriceRange, setInStock, setBestSellers, setNewArrivals, setSort, setDiscountMin, setAttribute, setParam, setForm, setSpecialities, setSubSubCategory]);

    // Build chips from active filters
    const activeChips = useMemo(() => {
        const chips: { key: string; label: string; value: string }[] = [];
        if (filters.search) chips.push({ key: 'search', label: 'Search', value: filters.search });
        if (filters.category) chips.push({ key: 'category', label: 'Category', value: filters.category });
        if (filters.sub_category) chips.push({ key: 'sub_category', label: 'Subcategory', value: filters.sub_category });
        if (filters.sub_sub_category) chips.push({ key: 'sub_sub_category', label: 'Sub-subcategory', value: filters.sub_sub_category });
        filters.brands.forEach(b => chips.push({ key: 'brand', label: 'Brand', value: b }));
        if (filters.country) chips.push({ key: 'country', label: 'Country', value: filters.country });
        filters.form.forEach(f => chips.push({ key: 'form', label: 'Form', value: f }));
        filters.specialities.forEach(s => chips.push({ key: 'specialities', label: 'Speciality', value: s }));
        filters.ratings.forEach(r => chips.push({ key: 'rating', label: 'Rating', value: r }));
        
        const fmtPrice = formatPrice || ((v: number) => `Ôé╣${v.toLocaleString()}`);
        if (filters.priceRange[0] !== 0 || filters.priceRange[1] !== Infinity) {
            const min = fmtPrice(filters.priceRange[0]);
            const max = filters.priceRange[1] === Infinity ? 'Max' : fmtPrice(filters.priceRange[1]);
            chips.push({ key: 'price', label: 'Price', value: `${min} ÔÇô ${max}` });
        }
        if (filters.inStock) chips.push({ key: 'inStock', label: 'Status', value: 'In Stock' });
        if (filters.bestSellers) chips.push({ key: 'bestSellers', label: 'Collection', value: 'Best Sellers' });
        if (filters.newArrivals) chips.push({ key: 'newArrivals', label: 'Collection', value: 'New Arrivals' });
        if (filters.discountMin) chips.push({ key: 'discount_min', label: 'Discount', value: `${filters.discountMin}% & above` });
        
        Object.entries(filters.attributes).forEach(([key, values]) => {
            values.forEach(v => chips.push({ key: `attr_${key}`, label: key.replace(/-/g, ' ').replace(/\b\w/g, l => l.toUpperCase()), value: v }));
        });

        return chips;
    }, [filters, formatPrice]);

    return {
        filters,
        activeChips,
        setSearch,
        setCategory,
        setSubCategory,
        setSubSubCategory,
        setBrands,
        setCountry,
        setForm,
        setSpecialities,
        setRatings,
        setPriceRange,
        setInStock,
        setBestSellers,
        setNewArrivals,
        setSort,
        setDiscountMin,
        setAttribute,
        removeFilter,
        clearAll,
    };
}

'use client';

import { useEffect, useRef } from 'react';
import { trackEvent, isConsentGranted } from './gtag';

// Constants
const MAX_TIME_SECONDS = 300; // 5 minutes cap
const SCROLL_THRESHOLDS = [25, 50, 75, 100];

export function useScrollDepthTracker(pageType: string) {
  const firedThresholds = useRef<Set<number>>(new Set());
  const ticking = useRef(false);

  useEffect(() => {
    firedThresholds.current.clear(); // Reset on new pageType/mount

    const handleScroll = () => {
      if (!isConsentGranted()) return;

      if (!ticking.current) {
        window.requestAnimationFrame(() => {
          const scrollableHeight = document.documentElement.scrollHeight - window.innerHeight;
          // Avoid division by zero on very short pages
          if (scrollableHeight <= 0) return;

          const scrollPercentage = Math.round((window.scrollY / scrollableHeight) * 100);

          SCROLL_THRESHOLDS.forEach((threshold) => {
            if (scrollPercentage >= threshold && !firedThresholds.current.has(threshold)) {
              firedThresholds.current.add(threshold);
              
              // Ensure we use the exact threshold value (e.g. 25, 50 for the event payload)
              trackEvent('scroll_depth', {
                scroll_percentage: threshold,
                page_type: pageType,
              });
            }
          });

          ticking.current = false;
        });
        ticking.current = true;
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, [pageType]);
  
  return firedThresholds; // Expose ref for engagement score
}

export function useTimeOnPageTracker(pageType: string) {
  const startTime = useRef<number>(0);
  const hasFired = useRef<boolean>(false);

  useEffect(() => {
    startTime.current = Date.now();
    hasFired.current = false;

    const fireTimeOnPage = () => {
      if (hasFired.current || !isConsentGranted()) return;
      
      const durationSeconds = Math.round((Date.now() - startTime.current) / 1000);
      if (durationSeconds > 0) {
        trackEvent('time_on_page', {
          duration_seconds: durationSeconds,
          page_type: pageType,
        });
      }
      hasFired.current = true;
    };

    const handleVisibilityChange = () => {
      if (document.visibilityState === 'hidden') {
        fireTimeOnPage();
      }
    };

    window.addEventListener('visibilitychange', handleVisibilityChange);
    window.addEventListener('beforeunload', fireTimeOnPage);

    return () => {
      window.removeEventListener('visibilitychange', handleVisibilityChange);
      window.removeEventListener('beforeunload', fireTimeOnPage);
      fireTimeOnPage(); // Fire on route change / unmount
    };
  }, [pageType]);
  
  return startTime;
}

export function useEngagementScore(pageType: string) {
  const scrollTracker = useScrollDepthTracker(pageType);
  const timeTracker = useTimeOnPageTracker(pageType);
  const interactionCount = useRef<number>(0);
  const hasFiredScore = useRef<boolean>(false);

  useEffect(() => {
    interactionCount.current = 0;
    hasFiredScore.current = false;

    const handleInteraction = (e: MouseEvent | TouchEvent) => {
      // Basic interaction tracking (clicks/touches on interactive elements)
      const target = e.target as HTMLElement;
      if (target && (target.tagName === 'A' || target.tagName === 'BUTTON' || target.closest('a') || target.closest('button') || target.tagName === 'INPUT' || target.tagName === 'SELECT')) {
         interactionCount.current++;
      }
    };

    window.addEventListener('click', handleInteraction, { passive: true });
    window.addEventListener('touchstart', handleInteraction, { passive: true });

    return () => {
      window.removeEventListener('click', handleInteraction);
      window.removeEventListener('touchstart', handleInteraction);
      
      const currentTimeTracker = timeTracker.current;
      
      if (!hasFiredScore.current && isConsentGranted()) {
        const timeSpent = Math.min(Math.round((Date.now() - currentTimeTracker) / 1000), MAX_TIME_SECONDS);
        const maxScroll = Math.max(0, ...Array.from(scrollTracker.current));

        // Formula: (scroll% / 100) ├ù 40 + (time / max_time) ├ù 40 + interactions ├ù 20
        // Cap the interaction term at 20 (assuming let's say 1 interaction = 2 points, max 10 interactions)
        const scrollComponent = (maxScroll / 100) * 40;
        const timeComponent = (timeSpent / MAX_TIME_SECONDS) * 40;
        const interactionComponent = Math.min(interactionCount.current * 2, 20);

        const score = Math.round(scrollComponent + timeComponent + interactionComponent);

        if (score > 0) {
            trackEvent('engagement_score', {
              score,
              page_type: pageType,
            });
        }
        hasFiredScore.current = true;
      }
    };
  }, [pageType, scrollTracker, timeTracker]);
}

/**
 * Storefront  API Client
 * Consumes existing backend at https://ecommerce-backend-h23p.onrender.com
 * Backend response format: { success: boolean, message: string, data: T }
 */

import { Product, FilteredProduct, FilterMeta, ProductWithDetails, ProductAsset, ApiResponse } from '@/types';
import { buildPath } from './currency';
import { env } from '@/lib/env';
import PerformanceStore from '@/lib/analytics/performance';
import { isConsentGranted } from '@/lib/analytics/gtag';

// Force IPv4 first on server to avoid 'localhost' resolving to '::1' if backend is only on 127.0.0.1
if (typeof window === 'undefined' && process.env.NEXT_RUNTIME === 'nodejs') {
    try {
        // eslint-disable-next-line @typescript-eslint/no-require-imports
        const dns = require('dns');
        if (dns && dns.setDefaultResultOrder) {
            dns.setDefaultResultOrder('ipv4first');
        }
    } catch (_err) {
        // Ignore error if dns module is not available (e.g. in certain restricted environment)
    }
}

export let API_URL = env.NEXT_PUBLIC_API_URL || 'http://localhost:5000';

// Normalize API_URL: remove trailing slash
if (API_URL.endsWith('/')) {
    API_URL = API_URL.slice(0, -1);
}

if (typeof window !== 'undefined' && (API_URL.includes('localhost') || API_URL.includes('127.0.0.1'))) {
    API_URL = `${window.location.protocol}//${window.location.hostname}:5000`;
}
// SECURITY: Access tokens are handled exclusively via HttpOnly cookies.
// No token is ever stored in localStorage or sent via Authorization headers.
// All authenticated requests rely on credentials: 'include' to send cookies automatically.

let cachedCsrfToken: string | null = null;

/** Read the CSRF token from cache or cookie */
function getCsrfToken(): string | null {
    if (cachedCsrfToken) return cachedCsrfToken;
    if (typeof document === 'undefined') return null;
    const match = document.cookie.match(/(?:^|;\s*)_csrf=([^;]*)/);
    return match ? decodeURIComponent(match[1]) : null;
}

/** Ensure a CSRF token exists (lazy-loaded by authFetch) */
export async function initCsrf(): Promise<void> {
    if (typeof window === 'undefined') return;
    if (cachedCsrfToken) return;
    try {
        const res = await apiFetch(`${API_URL}/api/csrf-token`, { credentials: 'include' });
        const json = await res.json();
        if (json.success && json.data?.csrfToken) {
            cachedCsrfToken = json.data.csrfToken;
        }
    } catch {
        // Non-critical
    }
}

const lastApiLatencies: Record<string, number> = {};

/** Centralized helper to track API latency */
async function apiFetch(url: string, init?: RequestInit): Promise<Response> {
    const startTime = performance.now();
    try {
        const res = await fetch(url, init);
        const latency = Math.round(performance.now() - startTime);

        if (typeof window !== 'undefined' && isConsentGranted()) {
            try {
                const urlObj = new URL(url, window.location.origin);
                const path = urlObj.pathname;

                // Sensitive endpoint filtering
                if (!path.includes('/api/auth/') && !path.includes('/api/csrf-token') && !path.includes('/api/gdpr/')) {
                    // Throttling (100ms per endpoint)
                    const now = Date.now();
                    const lastSent = lastApiLatencies[path] || 0;
                    if (now - lastSent > 100) {
                        lastApiLatencies[path] = now;

                        // Storage for purchase correlation
                        PerformanceStore.recordApiLatency(latency);

                        // Push with category
                        const category = PerformanceStore.getPerformanceCategory(latency, 'api');

                        if ((window as Window & typeof globalThis & { dataLayer: unknown[] }).dataLayer) {
                            (window as Window & typeof globalThis & { dataLayer: unknown[] }).dataLayer.push({
                                event: 'api_latency',
                                api_endpoint: path,
                                latency_ms: latency,
                                latency_category: category,
                                status_code: res.status,
                                method: init?.method?.toUpperCase() || 'GET'
                            });
                        }
                    }
                }
            } catch { /* ignore parse error */ }
        }
        return res;
    } catch (_error) {
        throw error;
    }
}

export async function authFetch(url: string, init?: RequestInit): Promise<Response> {
    const isStateChanging = init?.method && ['POST', 'PUT', 'PATCH', 'DELETE'].includes(init.method.toUpperCase());

    // Auto-fetch CSRF token if missing on a state-changing browser request
    if (isStateChanging && typeof window !== 'undefined' && !cachedCsrfToken) {
        await initCsrf();
    }

    const csrfToken = getCsrfToken();
    const headers: Record<string, string> = { ...((init?.headers as Record<string, string>) || {}) };
    if (csrfToken) headers['X-CSRF-Token'] = csrfToken;

    let res = await apiFetch(url, { ...init, headers, credentials: 'include' });

    // Auto-retry once on CSRF failure
    if (res.status === 403 && isStateChanging && typeof window !== 'undefined') {
        const cloned = res.clone();
        try {
            const data = await cloned.json();
            if (data.message === 'CSRF token invalid or expired' || data.message === 'CSRF token missing') {
                cachedCsrfToken = null;
                await initCsrf();
                headers['X-CSRF-Token'] = cachedCsrfToken || '';
                res = await apiFetch(url, { ...init, headers, credentials: 'include' });
            }
        } catch {
            // ignore non-json error
        }
    }

    // ÔöÇÔöÇ Inactivity session expiry interceptors ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
    if (res.status === 401 && typeof window !== 'undefined') {
        const isAuthEndpoint = url.includes('/api/auth/login') || url.includes('/api/auth/register') || url.includes('/api/auth/refresh-token') || url.includes('/api/auth/initiate-registration');
        const isLoginPage = window.location.pathname.includes('/login');

        if (!isAuthEndpoint && !isLoginPage) {
            const cloned = res.clone();
            try {
                const data = await cloned.json();
                if (data.code === 'SESSION_INACTIVE_TIMEOUT' || data.code === 'TOKEN_VERSION_MISMATCH') {
                    localStorage.removeItem('vedashi_user');
                    window.dispatchEvent(new CustomEvent('session-expired'));
                    const pathParts = window.location.pathname.split('/');
                    const country = pathParts[1] || 'us';
                    window.location.href = buildPath(country, `/login?session_expired=1`);
                    return res;
                }
            } catch { /* ignore */ }
        }
    }

    return res;
}

